(
    '43010000-0000-4000-8100-000000000001'::uuid,
    'beginner-01-greet-your-neighbour-politely', 'Greet your neighbour politely', 'Say hello to the neighbours and learn when to add po.',
    'beginner', 5, 1, false, 1,
    'beginner-v1', 'say-hello', 'Say hello',
    1, 1, 3, 14,
    1.00, array['lifeInThePhilippines', 'family', 'travel']::text[], 'authored_roadmap', 'native_speaker_review_required',
    '{"title":"Greet your neighbour politely","scenarioKey":"roadmap_beginner_01_say_hello","scenario":"Say hello to the neighbours and learn when to add po.","minutes":5,"difficulty":1,"rounds":[{"topicKey":"roadmap_beginner_01_say_hello","situation":"Your new neighbour, a woman your age, waves at you.","tagalog":"Uy! Kumusta ka?","translation":"Hi! How are you?","chunks":[{"tagalog":"Uy!","english":"hey!","note":"A warm, casual way to get someone''s attention."},{"tagalog":"Kumusta ka?","english":"how are you?","note":"Ka is the casual ''you'' for people your age."}],"wordGlosses":[{"token":"Uy!","english":"hey"},{"token":"Kumusta","english":"how are"},{"token":"ka?","english":"you (casual)"}],"speakingPrompt":"Greet her the easy, friendly way."},{"topicKey":"roadmap_beginner_01_say_hello","situation":"An older neighbour, Aling Nena, steps out of her gate.","tagalog":"Magandang umaga po.","translation":"Good morning, ma''am.","chunks":[{"tagalog":"Magandang umaga","english":"good morning","note":"Literally ''beautiful morning''."},{"tagalog":"po.","english":"(respect)","note":"Po shows respect to an older person."}],"wordGlosses":[{"token":"Magandang","english":"beautiful / good"},{"token":"umaga","english":"morning"},{"token":"po.","english":"(respect marker)"}],"speakingPrompt":"Greet her respectfully."},{"topicKey":"roadmap_beginner_01_say_hello","situation":"Ask Aling Nena how she is.","tagalog":"Kumusta po kayo?","translation":"How are you, ma''am?","chunks":[{"tagalog":"Kumusta","english":"how are","note":"Start the thought with this reusable chunk."},{"tagalog":"po kayo?","english":"you (respectful)?","note":"Kayo is the respectful ''you''; po adds courtesy."}],"wordGlosses":[{"token":"Kumusta","english":"how are"},{"token":"po","english":"(respect marker)"},{"token":"kayo?","english":"you (respectful)"}],"speakingPrompt":"Ask how she is, keeping it respectful.","responseExercise":{"promptTagalog":"Kumusta po kayo?","promptTranslation":"How are you, ma''am?","options":[{"englishTranslation":"I''m fine, thank you."},{"englishTranslation":"How are you, ma''am?"},{"englishTranslation":"Take care!"}],"correctOptionIndex":1}},{"topicKey":"roadmap_beginner_01_say_hello","situation":"She asks how you are. Tell her you''re fine.","tagalog":"Mabuti naman po, salamat po.","translation":"I''m fine, thank you.","chunks":[{"tagalog":"Mabuti naman","english":"I''m fine","note":"Naman softens it: ''fine, thankfully''."},{"tagalog":"po,","english":"(respect)","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"salamat po.","english":"thank you (respectful)","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Mabuti","english":"good / well"},{"token":"naman","english":"(softener) thankfully"},{"token":"po,","english":"(respect marker)"},{"token":"salamat","english":"thank you"},{"token":"po.","english":"(respect marker)"}],"speakingPrompt":"Answer and thank her politely."},{"topicKey":"roadmap_beginner_01_say_hello","situation":"Your friendly neighbour heads off to work.","tagalog":"Ingat ka!","translation":"Take care!","chunks":[{"tagalog":"Ingat","english":"take care","note":"A very common way to say goodbye."},{"tagalog":"ka!","english":"you!","note":"Casual ''you'' again for a friend."}],"wordGlosses":[{"token":"Ingat","english":"take care"},{"token":"ka!","english":"you (casual)"}],"speakingPrompt":"Wish her well as she leaves.","responseExercise":{"promptTagalog":"Ingat ka!","promptTranslation":"Take care!","options":[{"englishTranslation":"Hi! How are you?"},{"englishTranslation":"Take care!"},{"englishTranslation":"Good morning, ma''am."}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Uy","english":"hey!","example":"Uy! Kumusta ka?","exampleTranslation":"Hi! How are you?"},{"tagalog":"Kumusta ka","english":"how are you?","example":"Uy! Kumusta ka?","exampleTranslation":"Hi! How are you?"},{"tagalog":"Magandang umaga","english":"good morning","example":"Magandang umaga po.","exampleTranslation":"Good morning, ma''am."},{"tagalog":"po","english":"(respect)","example":"Magandang umaga po.","exampleTranslation":"Good morning, ma''am."},{"tagalog":"Kumusta","english":"how are","example":"Kumusta po kayo?","exampleTranslation":"How are you, ma''am?"},{"tagalog":"po kayo","english":"you (respectful)?","example":"Kumusta po kayo?","exampleTranslation":"How are you, ma''am?"},{"tagalog":"Mabuti naman","english":"I''m fine","example":"Mabuti naman po, salamat po.","exampleTranslation":"I''m fine, thank you."},{"tagalog":"salamat po","english":"thank you (respectful)","example":"Mabuti naman po, salamat po.","exampleTranslation":"I''m fine, thank you."},{"tagalog":"Ingat","english":"take care","example":"Ingat ka!","exampleTranslation":"Take care!"},{"tagalog":"ka","english":"you!","example":"Ingat ka!","exampleTranslation":"Take care!"}]}'::jsonb, '63cd69f213819773095066f86871b41ef1a1f8588169ffc8d6c0352b04a9d2c2', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
  ),
(
    '43010000-0000-4000-8100-000000000002'::uuid,
    'beginner-02-introduce-yourself-at-a-barkada-party', 'Introduce yourself at a barkada party', 'Meet your friend''s barkada: share your name and where you''re from.',
    'beginner', 5, 2, false, 1,
    'beginner-v1', 'say-hello', 'Say hello',
    1, 2, 3, 14,
    1.10, array['partner', 'culture', 'lifeInThePhilippines']::text[], 'authored_roadmap', 'native_speaker_review_required',
    '{"title":"Introduce yourself at a barkada party","scenarioKey":"roadmap_beginner_02_say_hello","scenario":"Meet your friend''s barkada: share your name and where you''re from.","minutes":5,"difficulty":1.1,"rounds":[{"topicKey":"roadmap_beginner_02_say_hello","situation":"At a friend''s birthday, someone from their barkada smiles and comes over.","tagalog":"Hi! Ako si Sam.","translation":"Hi! I''m Sam.","chunks":[{"tagalog":"Hi!","english":"hi!","note":"Friends in Manila greet each other with an English ''hi'' all the time."},{"tagalog":"Ako si","english":"I am","note":"Si comes right before a person''s name."},{"tagalog":"Sam.","english":"Sam.","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Hi!","english":"hi"},{"token":"Ako","english":"I / me"},{"token":"si","english":"(marks a name)"},{"token":"Sam.","english":"Sam (a name)"}],"speakingPrompt":"Say hi and tell her your name."},{"topicKey":"roadmap_beginner_02_say_hello","situation":"She laughs and says she forgot to introduce herself.","tagalog":"Ikaw, anong pangalan mo?","translation":"And you, what''s your name?","chunks":[{"tagalog":"Ikaw,","english":"and you,","note":"Starting with ikaw turns the question back: ''how about you?''"},{"tagalog":"anong pangalan","english":"what name","note":"Anong is ano plus the linker -ng."},{"tagalog":"mo?","english":"your?","note":"Mo means ''your'' and comes after the noun."}],"wordGlosses":[{"token":"Ikaw,","english":"you"},{"token":"anong","english":"what (+ linker)"},{"token":"pangalan","english":"name"},{"token":"mo?","english":"your"}],"speakingPrompt":"Turn the question back to her."},{"topicKey":"roadmap_beginner_02_say_hello","situation":"Her name is Joy. You hear an accent and get curious about her home province.","tagalog":"Taga-saan ka?","translation":"Where are you from?","chunks":[{"tagalog":"Taga-saan","english":"from where","note":"Taga- means ''from'' a place, so taga-saan is ''from where?''"},{"tagalog":"ka?","english":"are you?","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Taga-saan","english":"from where"},{"token":"ka?","english":"you (casual)"}],"speakingPrompt":"Ask where she''s from.","responseExercise":{"promptTagalog":"Taga-saan ka?","promptTranslation":"Where are you from?","options":[{"englishTranslation":"I''m from Canada, but I live in Makati."},{"englishTranslation":"Where are you from?"},{"englishTranslation":"Okay, see you around!"}],"correctOptionIndex":1}},{"topicKey":"roadmap_beginner_02_say_hello","situation":"Joy is from Cebu. She asks about you.","tagalog":"Taga-Canada ako, pero sa Makati ako nakatira.","translation":"I''m from Canada, but I live in Makati.","chunks":[{"tagalog":"Taga-Canada ako,","english":"I''m from Canada,","note":"Put taga- in front of any place name."},{"tagalog":"pero sa Makati","english":"but in Makati","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"ako nakatira.","english":"I live.","note":"Nakatira means ''living, residing''."}],"wordGlosses":[{"token":"Taga-Canada","english":"from Canada"},{"token":"ako,","english":"I / me"},{"token":"pero","english":"but"},{"token":"sa","english":"at / to / in"},{"token":"Makati","english":"Makati (a Manila city)"},{"token":"ako","english":"I / me"},{"token":"nakatira.","english":"living / residing"}],"speakingPrompt":"Say where you''re from and where you live now."},{"topicKey":"roadmap_beginner_02_say_hello","situation":"Your friend calls Joy over to cut the cake.","tagalog":"Sige, kita-kits!","translation":"Okay, see you around!","chunks":[{"tagalog":"Sige,","english":"okay,","note":"Sige is the all-purpose ''okay, go ahead''."},{"tagalog":"kita-kits!","english":"see you!","note":"Playful slang among friends, from ''kita tayo''."}],"wordGlosses":[{"token":"Sige,","english":"okay"},{"token":"kita-kits!","english":"see you! (slang)"}],"speakingPrompt":"Say a casual goodbye for now.","responseExercise":{"promptTagalog":"Sige, kita-kits!","promptTranslation":"Okay, see you around!","options":[{"englishTranslation":"Hi! I''m Sam."},{"englishTranslation":"Okay, see you around!"},{"englishTranslation":"And you, what''s your name?"}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Hi","english":"hi!","example":"Hi! Ako si Sam.","exampleTranslation":"Hi! I''m Sam."},{"tagalog":"Ako si","english":"I am","example":"Hi! Ako si Sam.","exampleTranslation":"Hi! I''m Sam."},{"tagalog":"Sam","english":"Sam.","example":"Hi! Ako si Sam.","exampleTranslation":"Hi! I''m Sam."},{"tagalog":"Ikaw","english":"and you,","example":"Ikaw, anong pangalan mo?","exampleTranslation":"And you, what''s your name?"},{"tagalog":"anong pangalan","english":"what name","example":"Ikaw, anong pangalan mo?","exampleTranslation":"And you, what''s your name?"},{"tagalog":"mo","english":"your?","example":"Ikaw, anong pangalan mo?","exampleTranslation":"And you, what''s your name?"},{"tagalog":"Taga-saan","english":"from where","example":"Taga-saan ka?","exampleTranslation":"Where are you from?"},{"tagalog":"ka","english":"are you?","example":"Taga-saan ka?","exampleTranslation":"Where are you from?"},{"tagalog":"Taga-Canada ako","english":"I''m from Canada,","example":"Taga-Canada ako, pero sa Makati ako nakatira.","exampleTranslation":"I''m from Canada, but I live in Makati."},{"tagalog":"pero sa Makati","english":"but in Makati","example":"Taga-Canada ako, pero sa Makati ako nakatira.","exampleTranslation":"I''m from Canada, but I live in Makati."}]}'::jsonb, '2a2657151ec4450fe5f8330d8bc4f5329562f0096b742bceb95d6686b7577d99', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
