(
    '43010000-0000-4000-8100-000000000003'::uuid,
    'beginner-03-meet-lola-with-a-mano', 'Meet Lola with a mano', 'Greet your grandmother the respectful way and introduce your partner.',
    'beginner', 5, 3, false, 1,
    'beginner-v1', 'say-hello', 'Say hello',
    1, 3, 3, 14,
    1.20, array['family', 'partner', 'culture']::text[], 'authored_roadmap', 'native_speaker_review_required',
    '{"title":"Meet Lola with a mano","scenarioKey":"roadmap_beginner_03_say_hello","scenario":"Greet your grandmother the respectful way and introduce your partner.","minutes":5,"difficulty":1.2,"rounds":[{"topicKey":"roadmap_beginner_03_say_hello","situation":"You arrive at your family''s house with your partner. Lola is sitting in the living room.","tagalog":"Mano po, Lola.","translation":"Your blessing, Lola.","chunks":[{"tagalog":"Mano po,","english":"your hand (blessing)","note":"Say this as you press her hand to your forehead."},{"tagalog":"Lola.","english":"Grandma.","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Mano po,","english":"your blessing, please"},{"token":"Lola.","english":"Grandma"}],"speakingPrompt":"Ask for her blessing as you take her hand to your forehead."},{"topicKey":"roadmap_beginner_03_say_hello","situation":"Lola squeezes your hand and smiles.","tagalog":"Magandang hapon po, Lola. Kumusta po kayo?","translation":"Good afternoon, Lola. How are you?","chunks":[{"tagalog":"Magandang hapon po,","english":"good afternoon,","note":"Hapon is the afternoon."},{"tagalog":"Lola.","english":"Grandma.","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"Kumusta po kayo?","english":"how are you?","note":"Use kayo and po with elders, never ka."}],"wordGlosses":[{"token":"Magandang","english":"beautiful / good"},{"token":"hapon","english":"afternoon"},{"token":"po,","english":"(respect marker)"},{"token":"Lola.","english":"Grandma"},{"token":"Kumusta","english":"how are"},{"token":"po","english":"(respect marker)"},{"token":"kayo?","english":"you (respectful)"}],"speakingPrompt":"Greet her and ask how she is."},{"topicKey":"roadmap_beginner_03_say_hello","situation":"Lola looks curiously at the person beside you.","tagalog":"Lola, si Alex po, ang boyfriend ko.","translation":"Lola, this is Alex, my boyfriend.","chunks":[{"tagalog":"Lola,","english":"Grandma,","note":"Start the thought with this reusable chunk."},{"tagalog":"si Alex po,","english":"this is Alex,","note":"Si plus a name is enough to introduce someone."},{"tagalog":"ang boyfriend ko.","english":"my boyfriend.","note":"Ko means ''my'' and comes after the noun."}],"wordGlosses":[{"token":"Lola,","english":"Grandma"},{"token":"si","english":"(marks a name)"},{"token":"Alex","english":"Alex (a name)"},{"token":"po,","english":"(respect marker)"},{"token":"ang","english":"the (topic marker)"},{"token":"boyfriend","english":"boyfriend"},{"token":"ko.","english":"my / I"}],"speakingPrompt":"Introduce your partner to her.","responseExercise":{"promptTagalog":"Lola, si Alex po, ang boyfriend ko.","promptTranslation":"Lola, this is Alex, my boyfriend.","options":[{"englishTranslation":"He''s learning Tagalog."},{"englishTranslation":"Lola, this is Alex, my boyfriend."},{"englishTranslation":"Thank you, Lola. We''ll eat now."}],"correctOptionIndex":1}},{"topicKey":"roadmap_beginner_03_say_hello","situation":"Alex tries out a shy hello. Lola is delighted.","tagalog":"Nag-aaral po siya ng Tagalog.","translation":"He''s learning Tagalog.","chunks":[{"tagalog":"Nag-aaral po siya","english":"he''s studying","note":"Nag-aaral is ''studying'' right now."},{"tagalog":"ng Tagalog.","english":"Tagalog.","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Nag-aaral","english":"is studying"},{"token":"po","english":"(respect marker)"},{"token":"siya","english":"he / she"},{"token":"ng","english":"of / (object marker)"},{"token":"Tagalog.","english":"Tagalog"}],"speakingPrompt":"Tell her he''s learning the language."},{"topicKey":"roadmap_beginner_03_say_hello","situation":"Lola waves you both toward the table full of food.","tagalog":"Salamat po, Lola. Kakain na po kami.","translation":"Thank you, Lola. We''ll eat now.","chunks":[{"tagalog":"Salamat po, Lola.","english":"thank you, Grandma.","note":"Start the thought with this reusable chunk."},{"tagalog":"Kakain na po","english":"we''ll eat now","note":"Kakain is ''will eat''; na means ''now''."},{"tagalog":"kami.","english":"we (not including her).","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Salamat","english":"thank you"},{"token":"po,","english":"(respect marker)"},{"token":"Lola.","english":"Grandma"},{"token":"Kakain","english":"will eat"},{"token":"na","english":"already / now"},{"token":"po","english":"(respect marker)"},{"token":"kami.","english":"we (not including you)"}],"speakingPrompt":"Thank her and say you''ll both eat.","responseExercise":{"promptTagalog":"Salamat po, Lola. Kakain na po kami.","promptTranslation":"Thank you, Lola. We''ll eat now.","options":[{"englishTranslation":"Your blessing, Lola."},{"englishTranslation":"Thank you, Lola. We''ll eat now."},{"englishTranslation":"Good afternoon, Lola. How are you?"}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Mano po","english":"your hand (blessing)","example":"Mano po, Lola.","exampleTranslation":"Your blessing, Lola."},{"tagalog":"Lola","english":"Grandma.","example":"Mano po, Lola.","exampleTranslation":"Your blessing, Lola."},{"tagalog":"Magandang hapon po","english":"good afternoon,","example":"Magandang hapon po, Lola. Kumusta po kayo?","exampleTranslation":"Good afternoon, Lola. How are you?"},{"tagalog":"Kumusta po kayo","english":"how are you?","example":"Magandang hapon po, Lola. Kumusta po kayo?","exampleTranslation":"Good afternoon, Lola. How are you?"},{"tagalog":"si Alex po","english":"this is Alex,","example":"Lola, si Alex po, ang boyfriend ko.","exampleTranslation":"Lola, this is Alex, my boyfriend."},{"tagalog":"ang boyfriend ko","english":"my boyfriend.","example":"Lola, si Alex po, ang boyfriend ko.","exampleTranslation":"Lola, this is Alex, my boyfriend."},{"tagalog":"Nag-aaral po siya","english":"he''s studying","example":"Nag-aaral po siya ng Tagalog.","exampleTranslation":"He''s learning Tagalog."},{"tagalog":"ng Tagalog","english":"Tagalog.","example":"Nag-aaral po siya ng Tagalog.","exampleTranslation":"He''s learning Tagalog."},{"tagalog":"Salamat po, Lola","english":"thank you, Grandma.","example":"Salamat po, Lola. Kakain na po kami.","exampleTranslation":"Thank you, Lola. We''ll eat now."},{"tagalog":"Kakain na po","english":"we''ll eat now","example":"Salamat po, Lola. Kakain na po kami.","exampleTranslation":"Thank you, Lola. We''ll eat now."}]}'::jsonb, '8330a62e75509c7d754e004b7d8c7a11e14f46304f55005e3bfb6e7d365a747f', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
