(
    '43010000-0000-4000-8100-000000000004'::uuid,
    'beginner-04-order-at-the-carinderia', 'Order at the carinderia', 'Point at the dishes, order a meal with rice and pay for it.',
    'beginner', 5, 4, false, 1,
    'beginner-v1', 'eat-and-pay', 'Eat and pay',
    2, 4, 3, 14,
    1.30, array['lifeInThePhilippines', 'travel']::text[], 'authored_roadmap', 'native_speaker_review_required',
    '{"title":"Order at the carinderia","scenarioKey":"roadmap_beginner_04_eat_and_pay","scenario":"Point at the dishes, order a meal with rice and pay for it.","minutes":5,"difficulty":1.3,"rounds":[{"topicKey":"roadmap_beginner_04_eat_and_pay","situation":"You''re at a busy roadside eatery with trays of food behind the glass. Point at one.","tagalog":"Ate, ano po ito?","translation":"Miss, what''s this?","chunks":[{"tagalog":"Ate,","english":"miss,","note":"Ate (''big sister'') is a polite way to address a woman serving you."},{"tagalog":"ano po","english":"what","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"ito?","english":"is this?","note":"Ito is ''this'', for something near you."}],"wordGlosses":[{"token":"Ate,","english":"miss (lit. big sister)"},{"token":"ano","english":"what"},{"token":"po","english":"(respect marker)"},{"token":"ito?","english":"this"}],"speakingPrompt":"Ask the server what the dish is."},{"topicKey":"roadmap_beginner_04_eat_and_pay","situation":"She says it''s sinigang, a sour soup. It looks great.","tagalog":"Isa nga pong sinigang.","translation":"One sinigang, please.","chunks":[{"tagalog":"Isa nga pong","english":"one, please,","note":"Nga po makes a request polite; po becomes pong before a noun."},{"tagalog":"sinigang.","english":"sinigang (sour soup).","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Isa","english":"one"},{"token":"nga","english":"please (softener)"},{"token":"pong","english":"(respect marker + linker)"},{"token":"sinigang.","english":"sinigang (sour soup)"}],"speakingPrompt":"Order one serving of it."},{"topicKey":"roadmap_beginner_04_eat_and_pay","situation":"She asks if you want anything with it.","tagalog":"Saka isang kanin po.","translation":"And one rice, please.","chunks":[{"tagalog":"Saka","english":"and also","note":"Saka adds one more thing; many people say tsaka."},{"tagalog":"isang kanin","english":"one rice","note":"Isa becomes isang before a noun."},{"tagalog":"po.","english":"(respect)","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Saka","english":"and also"},{"token":"isang","english":"one (+ linker)"},{"token":"kanin","english":"rice (cooked)"},{"token":"po.","english":"(respect marker)"}],"speakingPrompt":"Add a cup of rice to your order.","responseExercise":{"promptTagalog":"Saka isang kanin po.","promptTranslation":"And one rice, please.","options":[{"englishTranslation":"How much is it all?"},{"englishTranslation":"And one rice, please."},{"englishTranslation":"Here''s my payment."}],"correctOptionIndex":1}},{"topicKey":"roadmap_beginner_04_eat_and_pay","situation":"You finish eating and walk to the counter.","tagalog":"Magkano po lahat?","translation":"How much is it all?","chunks":[{"tagalog":"Magkano po","english":"how much","note":"Magkano is the question for prices."},{"tagalog":"lahat?","english":"for everything?","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Magkano","english":"how much"},{"token":"po","english":"(respect marker)"},{"token":"lahat?","english":"everything / all"}],"speakingPrompt":"Ask for the total."},{"topicKey":"roadmap_beginner_04_eat_and_pay","situation":"She tells you the total. Hand her the money.","tagalog":"Heto po ang bayad ko.","translation":"Here''s my payment.","chunks":[{"tagalog":"Heto po","english":"here","note":"Heto is ''here it is'' as you hand something over."},{"tagalog":"ang bayad ko.","english":"my payment.","note":"Bayad is a payment or fare."}],"wordGlosses":[{"token":"Heto","english":"here it is"},{"token":"po","english":"(respect marker)"},{"token":"ang","english":"the (topic marker)"},{"token":"bayad","english":"payment / fare"},{"token":"ko.","english":"my / I"}],"speakingPrompt":"Say this as you hand over the money.","responseExercise":{"promptTagalog":"Heto po ang bayad ko.","promptTranslation":"Here''s my payment.","options":[{"englishTranslation":"Miss, what''s this?"},{"englishTranslation":"Here''s my payment."},{"englishTranslation":"One sinigang, please."}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Ate","english":"miss,","example":"Ate, ano po ito?","exampleTranslation":"Miss, what''s this?"},{"tagalog":"ano po","english":"what","example":"Ate, ano po ito?","exampleTranslation":"Miss, what''s this?"},{"tagalog":"ito","english":"is this?","example":"Ate, ano po ito?","exampleTranslation":"Miss, what''s this?"},{"tagalog":"Isa nga pong","english":"one, please,","example":"Isa nga pong sinigang.","exampleTranslation":"One sinigang, please."},{"tagalog":"sinigang","english":"sinigang (sour soup).","example":"Isa nga pong sinigang.","exampleTranslation":"One sinigang, please."},{"tagalog":"Saka","english":"and also","example":"Saka isang kanin po.","exampleTranslation":"And one rice, please."},{"tagalog":"isang kanin","english":"one rice","example":"Saka isang kanin po.","exampleTranslation":"And one rice, please."},{"tagalog":"po","english":"(respect)","example":"Saka isang kanin po.","exampleTranslation":"And one rice, please."},{"tagalog":"Magkano po","english":"how much","example":"Magkano po lahat?","exampleTranslation":"How much is it all?"},{"tagalog":"lahat","english":"for everything?","example":"Magkano po lahat?","exampleTranslation":"How much is it all?"}]}'::jsonb, 'b84ccaf64ba4c9f9d44ba3fa1d393fdfd02a08661a8f3bf1c9702b992ba271f5', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
