    1.40, array['lifeInThePhilippines', 'travel']::text[], 'authored_roadmap', 'native_speaker_review_required',
    '{"title":"Sari-sari store run","scenarioKey":"roadmap_beginner_05_eat_and_pay","scenario":"Buy a snack and a drink at the corner store and check your change.","minutes":5,"difficulty":1.4,"rounds":[{"topicKey":"roadmap_beginner_05_eat_and_pay","situation":"You walk up to the little corner store window. The owner is inside watching TV.","tagalog":"Pabili po!","translation":"Excuse me, I''d like to buy something!","chunks":[{"tagalog":"Pabili","english":"may I buy","note":"The classic call at a store window, roughly ''selling, please!''"},{"tagalog":"po!","english":"(respect)!","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Pabili","english":"may I buy"},{"token":"po!","english":"(respect marker)"}],"speakingPrompt":"Call out to get the owner''s attention."},{"topicKey":"roadmap_beginner_05_eat_and_pay","situation":"She comes to the window. Point at the snacks hanging up.","tagalog":"Isang chicharon nga po.","translation":"One chicharon, please.","chunks":[{"tagalog":"Isang chicharon","english":"one chicharon","note":"Pork cracklings, a classic store snack."},{"tagalog":"nga po.","english":"please.","note":"Nga po softens a request."}],"wordGlosses":[{"token":"Isang","english":"one (+ linker)"},{"token":"chicharon","english":"pork cracklings"},{"token":"nga po.","english":"please (polite)"}],"speakingPrompt":"Ask for one bag of pork cracklings."},{"topicKey":"roadmap_beginner_05_eat_and_pay","situation":"It''s hot out and you''re thirsty.","tagalog":"May malamig po ba kayong tubig?","translation":"Do you have cold water?","chunks":[{"tagalog":"May malamig","english":"is there cold","note":"May means ''there is'' or ''have''."},{"tagalog":"po ba","english":"(question)","note":"Ba turns the sentence into a yes-or-no question."},{"tagalog":"kayong tubig?","english":"water, do you?","note":"Kayo plus the linker -ng joins it to tubig."}],"wordGlosses":[{"token":"May","english":"there is / have"},{"token":"malamig","english":"cold"},{"token":"po","english":"(respect marker)"},{"token":"ba","english":"(question marker)"},{"token":"kayong","english":"you (respectful, + linker)"},{"token":"tubig?","english":"water"}],"speakingPrompt":"Ask whether she has cold water.","responseExercise":{"promptTagalog":"May malamig po ba kayong tubig?","promptTranslation":"Do you have cold water?","options":[{"englishTranslation":"Eighty? Here''s a hundred."},{"englishTranslation":"Do you have cold water?"},{"englishTranslation":"My change is twenty, right?"}],"correctOptionIndex":1}},{"topicKey":"roadmap_beginner_05_eat_and_pay","situation":"She says it all comes to eighty pesos. You only have a big bill.","tagalog":"Otsenta po? Heto pong isang daan.","translation":"Eighty? Here''s a hundred.","chunks":[{"tagalog":"Otsenta po?","english":"eighty?","note":"Prices are often said with Spanish numbers: otsenta is 80."},{"tagalog":"Heto pong","english":"here''s","note":"Heto po becomes heto pong before the amount."},{"tagalog":"isang daan.","english":"one hundred.","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Otsenta","english":"eighty"},{"token":"po?","english":"(respect marker)"},{"token":"Heto","english":"here it is"},{"token":"pong","english":"(respect marker + linker)"},{"token":"isang daan.","english":"one hundred"}],"speakingPrompt":"Check the price and hand her the bill."},{"topicKey":"roadmap_beginner_05_eat_and_pay","situation":"She counts out some coins and hands them to you.","tagalog":"Bente po ang sukli, di ba?","translation":"My change is twenty, right?","chunks":[{"tagalog":"Bente po","english":"twenty","note":"Bente is 20, from Spanish veinte."},{"tagalog":"ang sukli,","english":"is the change,","note":"Sukli is the change you get back."},{"tagalog":"di ba?","english":"right?","note":"Di ba is short for hindi ba, ''isn''t it?''"}],"wordGlosses":[{"token":"Bente","english":"twenty"},{"token":"po","english":"(respect marker)"},{"token":"ang","english":"the (topic marker)"},{"token":"sukli,","english":"change (money back)"},{"token":"di ba?","english":"right?"}],"speakingPrompt":"Check that your change is right.","responseExercise":{"promptTagalog":"Bente po ang sukli, di ba?","promptTranslation":"My change is twenty, right?","options":[{"englishTranslation":"Excuse me, I''d like to buy something!"},{"englishTranslation":"My change is twenty, right?"},{"englishTranslation":"One chicharon, please."}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Pabili","english":"may I buy","example":"Pabili po!","exampleTranslation":"Excuse me, I''d like to buy something!"},{"tagalog":"po","english":"(respect)!","example":"Pabili po!","exampleTranslation":"Excuse me, I''d like to buy something!"},{"tagalog":"Isang chicharon","english":"one chicharon","example":"Isang chicharon nga po.","exampleTranslation":"One chicharon, please."},{"tagalog":"nga po","english":"please.","example":"Isang chicharon nga po.","exampleTranslation":"One chicharon, please."},{"tagalog":"May malamig","english":"is there cold","example":"May malamig po ba kayong tubig?","exampleTranslation":"Do you have cold water?"},{"tagalog":"po ba","english":"(question)","example":"May malamig po ba kayong tubig?","exampleTranslation":"Do you have cold water?"},{"tagalog":"kayong tubig","english":"water, do you?","example":"May malamig po ba kayong tubig?","exampleTranslation":"Do you have cold water?"},{"tagalog":"Otsenta po","english":"eighty?","example":"Otsenta po? Heto pong isang daan.","exampleTranslation":"Eighty? Here''s a hundred."},{"tagalog":"Heto pong","english":"here''s","example":"Otsenta po? Heto pong isang daan.","exampleTranslation":"Eighty? Here''s a hundred."},{"tagalog":"isang daan","english":"one hundred.","example":"Otsenta po? Heto pong isang daan.","exampleTranslation":"Eighty? Here''s a hundred."}]}'::jsonb, 'addbbb73242014d47c6191a0f15661ff1d6ad13c9b1ce7748361038d614a935f', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
