(
    '43010000-0000-4000-8100-000000000006'::uuid,
    'beginner-06-let-s-eat-lunch-with-a-friend', 'Let''s eat: lunch with a friend', 'Check if your friend has eaten, then pick a dish and a place.',
    'beginner', 5, 6, false, 1,
    'beginner-v1', 'eat-and-pay', 'Eat and pay',
    2, 6, 3, 14,
    1.50, array['partner', 'culture', 'lifeInThePhilippines']::text[], 'authored_roadmap', 'native_speaker_review_required',
    '{"title":"Let''s eat: lunch with a friend","scenarioKey":"roadmap_beginner_06_eat_and_pay","scenario":"Check if your friend has eaten, then pick a dish and a place.","minutes":5,"difficulty":1.5,"rounds":[{"topicKey":"roadmap_beginner_06_eat_and_pay","situation":"It''s noon and your friend Carlo drops by your desk.","tagalog":"Kumain ka na?","translation":"Have you eaten yet?","chunks":[{"tagalog":"Kumain","english":"eaten","note":"Kumain is the completed form of ''eat''."},{"tagalog":"ka na?","english":"have you yet?","note":"Asking this is a way of saying ''I care about you''."}],"wordGlosses":[{"token":"Kumain","english":"ate / have eaten"},{"token":"ka","english":"you (casual)"},{"token":"na?","english":"already / now"}],"speakingPrompt":"Ask him the classic Filipino check-in question."},{"topicKey":"roadmap_beginner_06_eat_and_pay","situation":"He says not yet, and he''s starving.","tagalog":"Tara, kain tayo!","translation":"Come on, let''s eat!","chunks":[{"tagalog":"Tara,","english":"come on,","note":"Tara is ''let''s go''."},{"tagalog":"kain tayo!","english":"let''s eat!","note":"Tayo is the ''we'' that includes the listener."}],"wordGlosses":[{"token":"Tara,","english":"come on / let''s go"},{"token":"kain","english":"eat"},{"token":"tayo!","english":"we / let''s (including you)"}],"speakingPrompt":"Invite him to go eat with you."},{"topicKey":"roadmap_beginner_06_eat_and_pay","situation":"On the way out, he asks what you''re in the mood for. You turn it back to him.","tagalog":"Anong gusto mong kainin?","translation":"What do you want to eat?","chunks":[{"tagalog":"Anong gusto","english":"what (do you) want","note":"Gusto means ''want'' or ''like''."},{"tagalog":"mong kainin?","english":"you to eat?","note":"Mo plus -ng links it to kainin, ''to eat''."}],"wordGlosses":[{"token":"Anong","english":"what (+ linker)"},{"token":"gusto","english":"want / like"},{"token":"mong","english":"you (+ linker)"},{"token":"kainin?","english":"to eat (it)"}],"speakingPrompt":"Ask what he feels like eating.","responseExercise":{"promptTagalog":"Anong gusto mong kainin?","promptTranslation":"What do you want to eat?","options":[{"englishTranslation":"Me, I''d like sisig."},{"englishTranslation":"What do you want to eat?"},{"englishTranslation":"Let''s just go to the corner place. It''s cheap there."}],"correctOptionIndex":1}},{"topicKey":"roadmap_beginner_06_eat_and_pay","situation":"He can''t decide and says you choose.","tagalog":"Ako, gusto ko ng sisig.","translation":"Me, I''d like sisig.","chunks":[{"tagalog":"Ako,","english":"me,","note":"Start the thought with this reusable chunk."},{"tagalog":"gusto ko","english":"I want","note":"Ko is ''I'' here, the one who wants."},{"tagalog":"ng sisig.","english":"sisig (sizzling pork).","note":"Ng marks the thing you want."}],"wordGlosses":[{"token":"Ako,","english":"I / me"},{"token":"gusto ko","english":"I want"},{"token":"ng","english":"of / (object marker)"},{"token":"sisig.","english":"sisig (sizzling pork)"}],"speakingPrompt":"Say what you''d like to eat."},{"topicKey":"roadmap_beginner_06_eat_and_pay","situation":"You know a cheap place at the end of the street.","tagalog":"Sa kanto na lang tayo, mura doon.","translation":"Let''s just go to the corner place. It''s cheap there.","chunks":[{"tagalog":"Sa kanto","english":"at the corner","note":"Kanto is a street corner."},{"tagalog":"na lang tayo,","english":"let''s just go,","note":"Na lang means ''just, instead''."},{"tagalog":"mura doon.","english":"it''s cheap there.","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Sa","english":"at / to / in"},{"token":"kanto","english":"corner"},{"token":"na lang","english":"just / instead"},{"token":"tayo,","english":"we / let''s (including you)"},{"token":"mura","english":"cheap"},{"token":"doon.","english":"there"}],"speakingPrompt":"Suggest the place on the corner and say why.","responseExercise":{"promptTagalog":"Sa kanto na lang tayo, mura doon.","promptTranslation":"Let''s just go to the corner place. It''s cheap there.","options":[{"englishTranslation":"Have you eaten yet?"},{"englishTranslation":"Let''s just go to the corner place. It''s cheap there."},{"englishTranslation":"Come on, let''s eat!"}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Kumain","english":"eaten","example":"Kumain ka na?","exampleTranslation":"Have you eaten yet?"},{"tagalog":"ka na","english":"have you yet?","example":"Kumain ka na?","exampleTranslation":"Have you eaten yet?"},{"tagalog":"Tara","english":"come on,","example":"Tara, kain tayo!","exampleTranslation":"Come on, let''s eat!"},{"tagalog":"kain tayo","english":"let''s eat!","example":"Tara, kain tayo!","exampleTranslation":"Come on, let''s eat!"},{"tagalog":"Anong gusto","english":"what (do you) want","example":"Anong gusto mong kainin?","exampleTranslation":"What do you want to eat?"},{"tagalog":"mong kainin","english":"you to eat?","example":"Anong gusto mong kainin?","exampleTranslation":"What do you want to eat?"},{"tagalog":"Ako","english":"me,","example":"Ako, gusto ko ng sisig.","exampleTranslation":"Me, I''d like sisig."},{"tagalog":"gusto ko","english":"I want","example":"Ako, gusto ko ng sisig.","exampleTranslation":"Me, I''d like sisig."},{"tagalog":"ng sisig","english":"sisig (sizzling pork).","example":"Ako, gusto ko ng sisig.","exampleTranslation":"Me, I''d like sisig."},{"tagalog":"Sa kanto","english":"at the corner","example":"Sa kanto na lang tayo, mura doon.","exampleTranslation":"Let''s just go to the corner place. It''s cheap there."}]}'::jsonb, '557092e8ca146e96a962f37bc45bf605a4ef55687e0e385be114bdb771205d61', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
