(
    '43010000-0000-4000-8100-000000000007'::uuid,
    'beginner-07-ride-a-jeepney', 'Ride a jeepney', 'Check the route, pass the fare and get off at your stop.',
    'beginner', 5, 7, false, 1,
    'beginner-v1', 'out-and-about', 'Out and about',
    3, 7, 3, 14,
    1.60, array['travel', 'lifeInThePhilippines']::text[], 'authored_roadmap', 'native_speaker_review_required',
    '{"title":"Ride a jeepney","scenarioKey":"roadmap_beginner_07_out_and_about","scenario":"Check the route, pass the fare and get off at your stop.","minutes":5,"difficulty":1.6,"rounds":[{"topicKey":"roadmap_beginner_07_out_and_about","situation":"A jeepney pulls up. Before climbing in, check the route with the driver.","tagalog":"Kuya, Cubao po ba ito?","translation":"Driver, is this going to Cubao?","chunks":[{"tagalog":"Kuya,","english":"driver,","note":"Kuya (''big brother'') is how you address a male driver."},{"tagalog":"Cubao po","english":"to Cubao","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"ba ito?","english":"is this?","note":"Ba makes it a yes-or-no question."}],"wordGlosses":[{"token":"Kuya,","english":"sir / driver (lit. big brother)"},{"token":"Cubao","english":"Cubao (a Quezon City district)"},{"token":"po","english":"(respect marker)"},{"token":"ba","english":"(question marker)"},{"token":"ito?","english":"this"}],"speakingPrompt":"Ask the driver if it goes to Cubao."},{"topicKey":"roadmap_beginner_07_out_and_about","situation":"You sit at the back, far from the driver. Hand your coins to the passenger next to you.","tagalog":"Bayad po, isa lang.","translation":"Here''s my fare, just one.","chunks":[{"tagalog":"Bayad po,","english":"fare,","note":"Bayad is what everyone says when passing money forward."},{"tagalog":"isa lang.","english":"just one.","note":"Lang means ''just, only''."}],"wordGlosses":[{"token":"Bayad","english":"payment / fare"},{"token":"po,","english":"(respect marker)"},{"token":"isa","english":"one"},{"token":"lang.","english":"just / only"}],"speakingPrompt":"Pass your fare and say it''s for one person."},{"topicKey":"roadmap_beginner_07_out_and_about","situation":"A new passenger hands you coins to pass forward to the driver.","tagalog":"Kuya, bayad daw po.","translation":"Driver, here''s a fare from them.","chunks":[{"tagalog":"Kuya,","english":"driver,","note":"Start the thought with this reusable chunk."},{"tagalog":"bayad daw","english":"a fare, they say","note":"Daw means someone else said it; use raw after a vowel."},{"tagalog":"po.","english":"(respect).","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Kuya,","english":"sir / driver (lit. big brother)"},{"token":"bayad","english":"payment / fare"},{"token":"daw","english":"(someone) says"},{"token":"po.","english":"(respect marker)"}],"speakingPrompt":"Pass it on and tell the driver it''s someone else''s.","responseExercise":{"promptTagalog":"Kuya, bayad daw po.","promptTranslation":"Driver, here''s a fare from them.","options":[{"englishTranslation":"Please tell me when we reach Cubao."},{"englishTranslation":"Driver, here''s a fare from them."},{"englishTranslation":"Stop please, just by the side!"}],"correctOptionIndex":1}},{"topicKey":"roadmap_beginner_07_out_and_about","situation":"You don''t know the stops well. Ask the driver to warn you.","tagalog":"Pakisabi po kapag Cubao na.","translation":"Please tell me when we reach Cubao.","chunks":[{"tagalog":"Pakisabi po","english":"please tell me","note":"Paki- turns a verb into a polite request."},{"tagalog":"kapag Cubao na.","english":"when it''s Cubao already.","note":"Kapag means ''when''."}],"wordGlosses":[{"token":"Pakisabi","english":"please tell"},{"token":"po","english":"(respect marker)"},{"token":"kapag","english":"when / if"},{"token":"Cubao","english":"Cubao (a Quezon City district)"},{"token":"na.","english":"already / now"}],"speakingPrompt":"Ask him to let you know when you get there."},{"topicKey":"roadmap_beginner_07_out_and_about","situation":"You see your stop coming up.","tagalog":"Para po, sa tabi lang!","translation":"Stop please, just by the side!","chunks":[{"tagalog":"Para po,","english":"stop,","note":"Para is how you ask any jeepney to stop."},{"tagalog":"sa tabi lang!","english":"just at the side!","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Para","english":"stop (for a ride)"},{"token":"po,","english":"(respect marker)"},{"token":"sa","english":"at / to / in"},{"token":"tabi","english":"side (of the road)"},{"token":"lang!","english":"just / only"}],"speakingPrompt":"Tell the driver to stop so you can get off.","responseExercise":{"promptTagalog":"Para po, sa tabi lang!","promptTranslation":"Stop please, just by the side!","options":[{"englishTranslation":"Driver, is this going to Cubao?"},{"englishTranslation":"Stop please, just by the side!"},{"englishTranslation":"Here''s my fare, just one."}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Kuya","english":"driver,","example":"Kuya, Cubao po ba ito?","exampleTranslation":"Driver, is this going to Cubao?"},{"tagalog":"Cubao po","english":"to Cubao","example":"Kuya, Cubao po ba ito?","exampleTranslation":"Driver, is this going to Cubao?"},{"tagalog":"ba ito","english":"is this?","example":"Kuya, Cubao po ba ito?","exampleTranslation":"Driver, is this going to Cubao?"},{"tagalog":"Bayad po","english":"fare,","example":"Bayad po, isa lang.","exampleTranslation":"Here''s my fare, just one."},{"tagalog":"isa lang","english":"just one.","example":"Bayad po, isa lang.","exampleTranslation":"Here''s my fare, just one."},{"tagalog":"bayad daw","english":"a fare, they say","example":"Kuya, bayad daw po.","exampleTranslation":"Driver, here''s a fare from them."},{"tagalog":"po","english":"(respect).","example":"Kuya, bayad daw po.","exampleTranslation":"Driver, here''s a fare from them."},{"tagalog":"Pakisabi po","english":"please tell me","example":"Pakisabi po kapag Cubao na.","exampleTranslation":"Please tell me when we reach Cubao."},{"tagalog":"kapag Cubao na","english":"when it''s Cubao already.","example":"Pakisabi po kapag Cubao na.","exampleTranslation":"Please tell me when we reach Cubao."},{"tagalog":"Para po","english":"stop,","example":"Para po, sa tabi lang!","exampleTranslation":"Stop please, just by the side!"}]}'::jsonb, '80882ab13dd620c99989aa0da7b71c4e171a53dec3fac10539c1128d2f5f9d56', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
