(
    '43010000-0000-4000-8100-000000000008'::uuid,
    'beginner-08-ask-for-directions', 'Ask for directions', 'Find an ATM, the pharmacy and the mall by asking a guard.',
    'beginner', 5, 8, false, 1,
    'beginner-v1', 'out-and-about', 'Out and about',
    3, 8, 3, 14,
    1.70, array['travel', 'lifeInThePhilippines']::text[], 'authored_roadmap', 'native_speaker_review_required',
    '{"title":"Ask for directions","scenarioKey":"roadmap_beginner_08_out_and_about","scenario":"Find an ATM, the pharmacy and the mall by asking a guard.","minutes":5,"difficulty":1.7,"rounds":[{"topicKey":"roadmap_beginner_08_out_and_about","situation":"You need cash. A security guard is standing outside a bank on a busy street.","tagalog":"Kuya, may ATM po ba malapit dito?","translation":"Excuse me, is there an ATM near here?","chunks":[{"tagalog":"Kuya,","english":"excuse me (sir),","note":"Use kuya for a man a bit older than you."},{"tagalog":"may ATM po ba","english":"is there an ATM","note":"May means ''there is''."},{"tagalog":"malapit dito?","english":"near here?","note":"Malapit is ''near''."}],"wordGlosses":[{"token":"Kuya,","english":"sir / driver (lit. big brother)"},{"token":"may","english":"there is / have"},{"token":"ATM","english":"ATM"},{"token":"po","english":"(respect marker)"},{"token":"ba","english":"(question marker)"},{"token":"malapit","english":"near"},{"token":"dito?","english":"here"}],"speakingPrompt":"Ask him if there''s a cash machine nearby."},{"topicKey":"roadmap_beginner_08_out_and_about","situation":"He points and gives directions quickly. Repeat them back to be sure.","tagalog":"Diretso lang po, tapos kanan?","translation":"Straight ahead, then right?","chunks":[{"tagalog":"Diretso lang po,","english":"just straight,","note":"From Spanish derecho."},{"tagalog":"tapos kanan?","english":"then right?","note":"Kanan is right; kaliwa is left."}],"wordGlosses":[{"token":"Diretso","english":"straight ahead"},{"token":"lang","english":"just / only"},{"token":"po,","english":"(respect marker)"},{"token":"tapos","english":"then"},{"token":"kanan?","english":"right"}],"speakingPrompt":"Check that you understood the way."},{"topicKey":"roadmap_beginner_08_out_and_about","situation":"You also need medicine for a headache.","tagalog":"Saan po ang pinakamalapit na botika?","translation":"Where''s the nearest pharmacy?","chunks":[{"tagalog":"Saan po ang","english":"where is the","note":"Saan asks for a place."},{"tagalog":"pinakamalapit na","english":"nearest","note":"Pinaka- means ''most''; na links it to the noun."},{"tagalog":"botika?","english":"pharmacy?","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Saan","english":"where"},{"token":"po","english":"(respect marker)"},{"token":"ang","english":"the (topic marker)"},{"token":"pinakamalapit","english":"nearest"},{"token":"na","english":"already / now"},{"token":"botika?","english":"pharmacy"}],"speakingPrompt":"Ask him where the closest pharmacy is.","responseExercise":{"promptTagalog":"Saan po ang pinakamalapit na botika?","promptTranslation":"Where''s the nearest pharmacy?","options":[{"englishTranslation":"Is it far? Can I walk there?"},{"englishTranslation":"Where''s the nearest pharmacy?"},{"englishTranslation":"How do I get to the mall?"}],"correctOptionIndex":1}},{"topicKey":"roadmap_beginner_08_out_and_about","situation":"He says it''s past the church.","tagalog":"Malayo po ba? Kaya bang lakarin?","translation":"Is it far? Can I walk there?","chunks":[{"tagalog":"Malayo po ba?","english":"is it far?","note":"Start the thought with this reusable chunk."},{"tagalog":"Kaya bang","english":"is it possible","note":"Kaya means ''can manage''."},{"tagalog":"lakarin?","english":"to walk?","note":"Lakarin is ''to walk (a distance)''."}],"wordGlosses":[{"token":"Malayo","english":"far"},{"token":"po","english":"(respect marker)"},{"token":"ba?","english":"(question marker)"},{"token":"Kaya","english":"can manage / possible"},{"token":"bang","english":"(question marker + linker)"},{"token":"lakarin?","english":"to walk (it)"}],"speakingPrompt":"Ask if it''s far and whether you can walk."},{"topicKey":"roadmap_beginner_08_out_and_about","situation":"Last stop of the day is the mall, but you have no idea which way it is.","tagalog":"Paano po pumunta sa mall?","translation":"How do I get to the mall?","chunks":[{"tagalog":"Paano po","english":"how","note":"Paano asks ''how''."},{"tagalog":"pumunta","english":"to go","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"sa mall?","english":"to the mall?","note":"Sa marks where you''re going."}],"wordGlosses":[{"token":"Paano","english":"how"},{"token":"po","english":"(respect marker)"},{"token":"pumunta","english":"to go"},{"token":"sa","english":"at / to / in"},{"token":"mall?","english":"mall"}],"speakingPrompt":"Ask him how to get to the mall.","responseExercise":{"promptTagalog":"Paano po pumunta sa mall?","promptTranslation":"How do I get to the mall?","options":[{"englishTranslation":"Excuse me, is there an ATM near here?"},{"englishTranslation":"How do I get to the mall?"},{"englishTranslation":"Straight ahead, then right?"}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Kuya","english":"excuse me (sir),","example":"Kuya, may ATM po ba malapit dito?","exampleTranslation":"Excuse me, is there an ATM near here?"},{"tagalog":"may ATM po ba","english":"is there an ATM","example":"Kuya, may ATM po ba malapit dito?","exampleTranslation":"Excuse me, is there an ATM near here?"},{"tagalog":"malapit dito","english":"near here?","example":"Kuya, may ATM po ba malapit dito?","exampleTranslation":"Excuse me, is there an ATM near here?"},{"tagalog":"Diretso lang po","english":"just straight,","example":"Diretso lang po, tapos kanan?","exampleTranslation":"Straight ahead, then right?"},{"tagalog":"tapos kanan","english":"then right?","example":"Diretso lang po, tapos kanan?","exampleTranslation":"Straight ahead, then right?"},{"tagalog":"Saan po ang","english":"where is the","example":"Saan po ang pinakamalapit na botika?","exampleTranslation":"Where''s the nearest pharmacy?"},{"tagalog":"pinakamalapit na","english":"nearest","example":"Saan po ang pinakamalapit na botika?","exampleTranslation":"Where''s the nearest pharmacy?"},{"tagalog":"botika","english":"pharmacy?","example":"Saan po ang pinakamalapit na botika?","exampleTranslation":"Where''s the nearest pharmacy?"},{"tagalog":"Malayo po ba","english":"is it far?","example":"Malayo po ba? Kaya bang lakarin?","exampleTranslation":"Is it far? Can I walk there?"},{"tagalog":"Kaya bang","english":"is it possible","example":"Malayo po ba? Kaya bang lakarin?","exampleTranslation":"Is it far? Can I walk there?"}]}'::jsonb, '0b715eabec3ebbeebb7d910abdbb3fde907ed4fd90235179fdedc90fb9ff6cdf', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
