    '{"title":"Halo-halo and fruit at the market","scenarioKey":"roadmap_beginner_09_out_and_about","scenario":"Order a dessert at the market, then haggle a little over mangoes.","minutes":5,"difficulty":1.8,"rounds":[{"topicKey":"roadmap_beginner_09_out_and_about","situation":"It''s a hot afternoon at the market. A woman is shaving ice at a dessert stall.","tagalog":"Ate, isang halo-halo nga po.","translation":"Miss, one halo-halo, please.","chunks":[{"tagalog":"Ate,","english":"miss,","note":"Start the thought with this reusable chunk."},{"tagalog":"isang halo-halo","english":"one halo-halo","note":"Halo-halo means ''mix-mix'': you stir it all together."},{"tagalog":"nga po.","english":"please.","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Ate,","english":"miss (lit. big sister)"},{"token":"isang","english":"one (+ linker)"},{"token":"halo-halo","english":"halo-halo (shaved-ice dessert)"},{"token":"nga po.","english":"please (polite)"}],"speakingPrompt":"Order one of the famous shaved-ice desserts."},{"topicKey":"roadmap_beginner_09_out_and_about","situation":"You see slices of leche flan next to the ice. You want extra.","tagalog":"Puwede pong dagdagan ng leche flan?","translation":"Can you add more leche flan?","chunks":[{"tagalog":"Puwede pong","english":"can you","note":"Puwede is ''can, may''; often written pwede."},{"tagalog":"dagdagan","english":"add more","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"ng leche flan?","english":"leche flan?","note":"A caramel custard from the Spanish era."}],"wordGlosses":[{"token":"Puwede","english":"can / may"},{"token":"pong","english":"(respect marker + linker)"},{"token":"dagdagan","english":"add more (to it)"},{"token":"ng","english":"of / (object marker)"},{"token":"leche flan?","english":"leche flan (caramel custard)"}],"speakingPrompt":"Ask her to add extra caramel custard."},{"topicKey":"roadmap_beginner_09_out_and_about","situation":"After your dessert, you stop at a fruit stand piled with ripe mangoes.","tagalog":"Magkano po ang isang kilo ng mangga?","translation":"How much for a kilo of mangoes?","chunks":[{"tagalog":"Magkano po","english":"how much","note":"Start the thought with this reusable chunk."},{"tagalog":"ang isang kilo","english":"is one kilo","note":"Fruit is sold by the kilo."},{"tagalog":"ng mangga?","english":"of mangoes?","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Magkano","english":"how much"},{"token":"po","english":"(respect marker)"},{"token":"ang","english":"the (topic marker)"},{"token":"isang","english":"one (+ linker)"},{"token":"kilo","english":"kilo"},{"token":"ng","english":"of / (object marker)"},{"token":"mangga?","english":"mango(es)"}],"speakingPrompt":"Ask the price of one kilo.","responseExercise":{"promptTagalog":"Magkano po ang isang kilo ng mangga?","promptTranslation":"How much for a kilo of mangoes?","options":[{"englishTranslation":"That''s pricey. Any discount?"},{"englishTranslation":"How much for a kilo of mangoes?"},{"englishTranslation":"Make it a hundred and I''ll take it."}],"correctOptionIndex":1}},{"topicKey":"roadmap_beginner_09_out_and_about","situation":"The vendor names a price that seems a bit high.","tagalog":"Ang mahal naman. May tawad pa po?","translation":"That''s pricey. Any discount?","chunks":[{"tagalog":"Ang mahal naman.","english":"that''s so pricey.","note":"Ang plus an adjective is an exclamation: ''how expensive!''"},{"tagalog":"May tawad","english":"is there a discount","note":"Tawad is a haggled discount."},{"tagalog":"pa po?","english":"still?","note":"Pa means ''still, more''."}],"wordGlosses":[{"token":"Ang mahal","english":"how expensive"},{"token":"naman.","english":"(softener) thankfully"},{"token":"May","english":"there is / have"},{"token":"tawad","english":"discount (haggled)"},{"token":"pa","english":"still / more"},{"token":"po?","english":"(respect marker)"}],"speakingPrompt":"React to the price and ask for a discount."},{"topicKey":"roadmap_beginner_09_out_and_about","situation":"The vendor laughs and waits for your offer.","tagalog":"Isang daan na lang po, kukunin ko na.","translation":"Make it a hundred and I''ll take it.","chunks":[{"tagalog":"Isang daan","english":"one hundred","note":"Start the thought with this reusable chunk."},{"tagalog":"na lang po,","english":"just, please,","note":"Na lang lowers an offer: ''just this instead''."},{"tagalog":"kukunin ko na.","english":"I''ll take it now.","note":"Kukunin is ''will take''."}],"wordGlosses":[{"token":"Isang daan","english":"one hundred"},{"token":"na lang","english":"just / instead"},{"token":"po,","english":"(respect marker)"},{"token":"kukunin","english":"will take"},{"token":"ko","english":"my / I"},{"token":"na.","english":"already / now"}],"speakingPrompt":"Offer one hundred pesos and promise to buy.","responseExercise":{"promptTagalog":"Isang daan na lang po, kukunin ko na.","promptTranslation":"Make it a hundred and I''ll take it.","options":[{"englishTranslation":"Miss, one halo-halo, please."},{"englishTranslation":"Make it a hundred and I''ll take it."},{"englishTranslation":"Can you add more leche flan?"}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Ate","english":"miss,","example":"Ate, isang halo-halo nga po.","exampleTranslation":"Miss, one halo-halo, please."},{"tagalog":"isang halo-halo","english":"one halo-halo","example":"Ate, isang halo-halo nga po.","exampleTranslation":"Miss, one halo-halo, please."},{"tagalog":"nga po","english":"please.","example":"Ate, isang halo-halo nga po.","exampleTranslation":"Miss, one halo-halo, please."},{"tagalog":"Puwede pong","english":"can you","example":"Puwede pong dagdagan ng leche flan?","exampleTranslation":"Can you add more leche flan?"},{"tagalog":"dagdagan","english":"add more","example":"Puwede pong dagdagan ng leche flan?","exampleTranslation":"Can you add more leche flan?"},{"tagalog":"ng leche flan","english":"leche flan?","example":"Puwede pong dagdagan ng leche flan?","exampleTranslation":"Can you add more leche flan?"},{"tagalog":"Magkano po","english":"how much","example":"Magkano po ang isang kilo ng mangga?","exampleTranslation":"How much for a kilo of mangoes?"},{"tagalog":"ang isang kilo","english":"is one kilo","example":"Magkano po ang isang kilo ng mangga?","exampleTranslation":"How much for a kilo of mangoes?"},{"tagalog":"ng mangga","english":"of mangoes?","example":"Magkano po ang isang kilo ng mangga?","exampleTranslation":"How much for a kilo of mangoes?"},{"tagalog":"Ang mahal naman","english":"that''s so pricey.","example":"Ang mahal naman. May tawad pa po?","exampleTranslation":"That''s pricey. Any discount?"}]}'::jsonb, '0132f0025877f3f00e66179b751615d844e3fd1568974501e95c1d1a4498cd1b', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
