    3, 10, 3, 14,
    1.90, array['partner', 'lifeInThePhilippines']::text[], 'authored_roadmap', 'native_speaker_review_required',
    '{"title":"Set a time to meet up","scenarioKey":"roadmap_beginner_10_out_and_about","scenario":"Plan a weekend meetup with a friend: the time and the place.","minutes":5,"difficulty":1.9,"rounds":[{"topicKey":"roadmap_beginner_10_out_and_about","situation":"You''re chatting with your friend Bea on the phone about the weekend.","tagalog":"Libre ka ba bukas?","translation":"Are you free tomorrow?","chunks":[{"tagalog":"Libre ka ba","english":"are you free","note":"Libre means both ''free time'' and ''free of charge''."},{"tagalog":"bukas?","english":"tomorrow?","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Libre","english":"free"},{"token":"ka","english":"you (casual)"},{"token":"ba","english":"(question marker)"},{"token":"bukas?","english":"tomorrow"}],"speakingPrompt":"Ask if she''s free tomorrow."},{"topicKey":"roadmap_beginner_10_out_and_about","situation":"She says yes, after lunch.","tagalog":"Anong oras ka puwede?","translation":"What time works for you?","chunks":[{"tagalog":"Anong oras","english":"what time","note":"Oras is time, the hour."},{"tagalog":"ka puwede?","english":"can you?","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Anong","english":"what (+ linker)"},{"token":"oras","english":"time / hour"},{"token":"ka","english":"you (casual)"},{"token":"puwede?","english":"can / may"}],"speakingPrompt":"Ask her what time she can make it."},{"topicKey":"roadmap_beginner_10_out_and_about","situation":"She suggests mid-afternoon. You agree on a time.","tagalog":"Sige, alas-tres ng hapon.","translation":"Okay, three in the afternoon.","chunks":[{"tagalog":"Sige,","english":"okay,","note":"Start the thought with this reusable chunk."},{"tagalog":"alas-tres","english":"three o''clock","note":"Clock times use Spanish numbers: alas-dos, alas-tres."},{"tagalog":"ng hapon.","english":"in the afternoon.","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Sige,","english":"okay"},{"token":"alas-tres","english":"three o''clock"},{"token":"ng","english":"of / (object marker)"},{"token":"hapon.","english":"afternoon"}],"speakingPrompt":"Confirm three o''clock in the afternoon.","responseExercise":{"promptTagalog":"Sige, alas-tres ng hapon.","promptTranslation":"Okay, three in the afternoon.","options":[{"englishTranslation":"Let''s meet in front of the church."},{"englishTranslation":"Okay, three in the afternoon."},{"englishTranslation":"Don''t be late, okay!"}],"correctOptionIndex":1}},{"topicKey":"roadmap_beginner_10_out_and_about","situation":"Now pick an easy place to find each other in town.","tagalog":"Kita tayo sa harap ng simbahan.","translation":"Let''s meet in front of the church.","chunks":[{"tagalog":"Kita tayo","english":"let''s meet","note":"Kita tayo is ''let''s see each other''."},{"tagalog":"sa harap","english":"in front","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"ng simbahan.","english":"of the church.","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Kita tayo","english":"let''s meet"},{"token":"sa","english":"at / to / in"},{"token":"harap","english":"front"},{"token":"ng","english":"of / (object marker)"},{"token":"simbahan.","english":"church"}],"speakingPrompt":"Suggest meeting in front of the church."},{"topicKey":"roadmap_beginner_10_out_and_about","situation":"Bea is famous for running late. Tease her before you hang up.","tagalog":"Huwag kang male-late, ha!","translation":"Don''t be late, okay!","chunks":[{"tagalog":"Huwag kang","english":"don''t you","note":"Huwag plus ka plus the linker -ng: ''don''t you...''"},{"tagalog":"male-late,","english":"be late,","note":"Manila speakers happily put Tagalog prefixes on English verbs."},{"tagalog":"ha!","english":"okay!","note":"Ha at the end adds ''okay?'' with a friendly push."}],"wordGlosses":[{"token":"Huwag","english":"don''t"},{"token":"kang","english":"you (+ linker)"},{"token":"male-late,","english":"be late"},{"token":"ha!","english":"okay? (friendly tag)"}],"speakingPrompt":"Tell her not to be late, in a playful way.","responseExercise":{"promptTagalog":"Huwag kang male-late, ha!","promptTranslation":"Don''t be late, okay!","options":[{"englishTranslation":"Are you free tomorrow?"},{"englishTranslation":"Don''t be late, okay!"},{"englishTranslation":"What time works for you?"}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Libre ka ba","english":"are you free","example":"Libre ka ba bukas?","exampleTranslation":"Are you free tomorrow?"},{"tagalog":"bukas","english":"tomorrow?","example":"Libre ka ba bukas?","exampleTranslation":"Are you free tomorrow?"},{"tagalog":"Anong oras","english":"what time","example":"Anong oras ka puwede?","exampleTranslation":"What time works for you?"},{"tagalog":"ka puwede","english":"can you?","example":"Anong oras ka puwede?","exampleTranslation":"What time works for you?"},{"tagalog":"Sige","english":"okay,","example":"Sige, alas-tres ng hapon.","exampleTranslation":"Okay, three in the afternoon."},{"tagalog":"alas-tres","english":"three o''clock","example":"Sige, alas-tres ng hapon.","exampleTranslation":"Okay, three in the afternoon."},{"tagalog":"ng hapon","english":"in the afternoon.","example":"Sige, alas-tres ng hapon.","exampleTranslation":"Okay, three in the afternoon."},{"tagalog":"Kita tayo","english":"let''s meet","example":"Kita tayo sa harap ng simbahan.","exampleTranslation":"Let''s meet in front of the church."},{"tagalog":"sa harap","english":"in front","example":"Kita tayo sa harap ng simbahan.","exampleTranslation":"Let''s meet in front of the church."},{"tagalog":"ng simbahan","english":"of the church.","example":"Kita tayo sa harap ng simbahan.","exampleTranslation":"Let''s meet in front of the church."}]}'::jsonb, '1af4a719038439e5f400ffa868bd77e26e153ea5b2f9ca08bccda80c688ac8e8', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
