    1, 1, 3, 14,
    2.25, array['family', 'culture']::text[], 'authored_roadmap', 'native_speaker_review_required',
    '{"title":"Sunday lunch at Lola''s","scenarioKey":"roadmap_intermediate_01_people_you_love","scenario":"Eat, praise the cooking and turn down a third plate politely.","minutes":5,"difficulty":2.25,"rounds":[{"topicKey":"roadmap_intermediate_01_people_you_love","situation":"You walk into your partner''s grandmother''s kitchen for Sunday lunch. The whole table is covered in dishes.","tagalog":"Ang bango po dito, Lola! Ano pong niluto ninyo?","translation":"It smells so good, Lola! What did you cook?","chunks":[{"tagalog":"Ang bango po","english":"it smells so good","note":"Ang + adjective is an exclamation: ''how fragrant!''"},{"tagalog":"dito, Lola!","english":"in here, Grandma!","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"Ano pong niluto ninyo?","english":"what did you cook?","note":"Po takes the linker -ng before a verb: ''ano pong''. Ninyo is the respectful ''you''."}],"wordGlosses":[{"token":"Ang","english":"the (focus marker)"},{"token":"bango","english":"fragrant"},{"token":"po","english":"(respect marker)"},{"token":"dito,","english":"here"},{"token":"Lola!","english":"Grandma"},{"token":"Ano","english":"what"},{"token":"pong","english":"(respect marker + linker)"},{"token":"niluto","english":"cooked"},{"token":"ninyo?","english":"you / your (respectful)"}],"speakingPrompt":"Compliment the smell and ask her what she cooked, respectfully."},{"topicKey":"roadmap_intermediate_01_people_you_love","situation":"You take the first bite of her kare-kare. Lola watches you, waiting for your verdict.","tagalog":"Grabe, ang sarap po ng kare-kare ninyo!","translation":"Wow, your kare-kare is delicious!","chunks":[{"tagalog":"Grabe,","english":"wow,","note":"Grabe is an all-purpose ''wow'' for anything extreme."},{"tagalog":"ang sarap po","english":"it''s so delicious","note":"Sarap is the go-to compliment for food. Ang makes it an exclamation."},{"tagalog":"ng kare-kare ninyo!","english":"your kare-kare!","note":"Ng marks whose delicious thing it is: ''the deliciousness of your kare-kare''."}],"wordGlosses":[{"token":"Grabe,","english":"wow / terrible"},{"token":"ang","english":"the (focus marker)"},{"token":"sarap","english":"delicious"},{"token":"po","english":"(respect marker)"},{"token":"ng","english":"of / (object marker)"},{"token":"kare-kare","english":"oxtail peanut stew"},{"token":"ninyo!","english":"you / your (respectful)"}],"speakingPrompt":"Tell her the dish is delicious."},{"topicKey":"roadmap_intermediate_01_people_you_love","situation":"Lola spoons more rice towards your plate and insists you keep eating.","tagalog":"Sige po, pero konting kanin lang.","translation":"Okay, but just a little rice.","chunks":[{"tagalog":"Sige po,","english":"okay,","note":"Sige is ''okay, go ahead''. Add po for an elder."},{"tagalog":"pero konting kanin","english":"but a little rice","note":"Konting is konti + the linker -ng."},{"tagalog":"lang.","english":"only.","note":"Lang means ''just, only'' and softens the request."}],"wordGlosses":[{"token":"Sige","english":"okay"},{"token":"po,","english":"(respect marker)"},{"token":"pero","english":"but"},{"token":"konting","english":"a little"},{"token":"kanin","english":"rice"},{"token":"lang.","english":"just / only"}],"speakingPrompt":"Accept, but ask for only a small amount.","responseExercise":{"promptTagalog":"Sige po, pero konting kanin lang.","promptTranslation":"Okay, but just a little rice.","options":[{"englishTranslation":"Oh no, I''m completely full, Lola."},{"englishTranslation":"Okay, but just a little rice."},{"englishTranslation":"Just wrap some up for me, so I have food for tomorrow."}],"correctOptionIndex":1}},{"topicKey":"roadmap_intermediate_01_people_you_love","situation":"She is already reaching for the serving spoon a third time.","tagalog":"Naku, busog na busog na po ako, Lola.","translation":"Oh no, I''m completely full, Lola.","chunks":[{"tagalog":"Naku,","english":"oh no,","note":"Naku softens a refusal with a little drama."},{"tagalog":"busog na busog","english":"completely full","note":"Repeating an adjective with na intensifies it: ''very, very full''."},{"tagalog":"na po ako, Lola.","english":"I already am, Grandma.","note":"Short words go first: na, then po, then ako."}],"wordGlosses":[{"token":"Naku,","english":"oh no / oh"},{"token":"busog","english":"full (from eating)"},{"token":"na","english":"already / now"},{"token":"busog","english":"full (from eating)"},{"token":"na","english":"already / now"},{"token":"po","english":"(respect marker)"},{"token":"ako,","english":"I"},{"token":"Lola.","english":"Grandma"}],"speakingPrompt":"Turn down the third serving politely."},{"topicKey":"roadmap_intermediate_01_people_you_love","situation":"Lola looks disappointed that so much food is left. Offer her a way out.","tagalog":"Pabalot na lang po ako, para may baon ako bukas.","translation":"Just wrap some up for me, so I have food for tomorrow.","chunks":[{"tagalog":"Pabalot na lang po ako,","english":"just wrap some for me,","note":"Pa- turns a verb into a request: pabalot is ''have it wrapped''. Na lang means ''instead''."},{"tagalog":"para may baon ako","english":"so I have food to bring","note":"Baon is food you take with you."},{"tagalog":"bukas.","english":"tomorrow.","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Pabalot","english":"please wrap (request)"},{"token":"na","english":"already / now"},{"token":"lang","english":"just / only"},{"token":"po","english":"(respect marker)"},{"token":"ako,","english":"I"},{"token":"para","english":"so that / for"},{"token":"may","english":"there is / have"},{"token":"baon","english":"packed food"},{"token":"ako","english":"I"},{"token":"bukas.","english":"tomorrow"}],"speakingPrompt":"Ask her to pack some leftovers so you can eat them tomorrow.","responseExercise":{"promptTagalog":"Pabalot na lang po ako, para may baon ako bukas.","promptTranslation":"Just wrap some up for me, so I have food for tomorrow.","options":[{"englishTranslation":"It smells so good, Lola! What did you cook?"},{"englishTranslation":"Just wrap some up for me, so I have food for tomorrow."},{"englishTranslation":"Wow, your kare-kare is delicious!"}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Ang bango po","english":"it smells so good","example":"Ang bango po dito, Lola! Ano pong niluto ninyo?","exampleTranslation":"It smells so good, Lola! What did you cook?"},{"tagalog":"dito, Lola","english":"in here, Grandma!","example":"Ang bango po dito, Lola! Ano pong niluto ninyo?","exampleTranslation":"It smells so good, Lola! What did you cook?"},{"tagalog":"Ano pong niluto ninyo","english":"what did you cook?","example":"Ang bango po dito, Lola! Ano pong niluto ninyo?","exampleTranslation":"It smells so good, Lola! What did you cook?"},{"tagalog":"Grabe","english":"wow,","example":"Grabe, ang sarap po ng kare-kare ninyo!","exampleTranslation":"Wow, your kare-kare is delicious!"},{"tagalog":"ang sarap po","english":"it''s so delicious","example":"Grabe, ang sarap po ng kare-kare ninyo!","exampleTranslation":"Wow, your kare-kare is delicious!"},{"tagalog":"ng kare-kare ninyo","english":"your kare-kare!","example":"Grabe, ang sarap po ng kare-kare ninyo!","exampleTranslation":"Wow, your kare-kare is delicious!"},{"tagalog":"Sige po","english":"okay,","example":"Sige po, pero konting kanin lang.","exampleTranslation":"Okay, but just a little rice."},{"tagalog":"pero konting kanin","english":"but a little rice","example":"Sige po, pero konting kanin lang.","exampleTranslation":"Okay, but just a little rice."},{"tagalog":"lang","english":"only.","example":"Sige po, pero konting kanin lang.","exampleTranslation":"Okay, but just a little rice."},{"tagalog":"Naku","english":"oh no,","example":"Naku, busog na busog na po ako, Lola.","exampleTranslation":"Oh no, I''m completely full, Lola."}]}'::jsonb, 'dc25c49610f3d51c1db1741c2e894d0fa417a0d537796ccc088989abb2847be8', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
  ),
(
    '43020000-0000-4000-8100-000000000002'::uuid,
    'intermediate-02-sound-natural-with-little-words', 'Sound natural with little words', 'Catch up with an old friend using the small words locals love.',
    'intermediate', 5, 2, false, 1,
    'intermediate-v1', 'people-you-love', 'The people you love',
    1, 2, 3, 14,
    2.30, array['lifeInThePhilippines', 'culture']::text[], 'authored_roadmap', 'native_speaker_review_required',
    '{"title":"Sound natural with little words","scenarioKey":"roadmap_intermediate_02_people_you_love","scenario":"Catch up with an old friend using the small words locals love.","minutes":5,"difficulty":2.3,"rounds":[{"topicKey":"roadmap_intermediate_02_people_you_love","situation":"You bump into your old friend Bea at a coffee shop in Makati. You only recognise her at the last second.","tagalog":"Uy, ikaw pala! Ang tagal na nating hindi nagkita.","translation":"Hey, it''s you! We haven''t seen each other in so long.","chunks":[{"tagalog":"Uy,","english":"hey,","note":"Start the thought with this reusable chunk."},{"tagalog":"ikaw pala!","english":"oh, it''s you!","note":"Pala marks a sudden realisation: ''so it''s you!''"},{"tagalog":"Ang tagal na","english":"it''s been so long","note":"Ang + adjective again: ''how long it''s been''."},{"tagalog":"nating hindi nagkita.","english":"since we''ve seen each other.","note":"Natin takes -g as a linker: ''natin'' becomes ''nating''."}],"wordGlosses":[{"token":"Uy,","english":"hey"},{"token":"ikaw","english":"you (casual)"},{"token":"pala!","english":"oh, so it''s (surprise)"},{"token":"Ang","english":"the (focus marker)"},{"token":"tagal","english":"long (time)"},{"token":"na","english":"already / now"},{"token":"nating","english":"we (linked, incl. you)"},{"token":"hindi","english":"not"},{"token":"nagkita.","english":"saw each other"}],"speakingPrompt":"Show your surprise at seeing her and say it''s been ages."},{"topicKey":"roadmap_intermediate_02_people_you_love","situation":"Bea asks how you''ve been lately.","tagalog":"Okay naman ako, medyo busy lang sa trabaho.","translation":"I''m okay. Just a bit busy with work.","chunks":[{"tagalog":"Okay naman ako,","english":"I''m okay,","note":"Naman softens your answer: ''I''m okay, all things considered''."},{"tagalog":"medyo busy lang","english":"just a bit busy","note":"Lang downplays it: ''only a bit''."},{"tagalog":"sa trabaho.","english":"at work.","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Okay","english":"okay"},{"token":"naman","english":"(softener)"},{"token":"ako,","english":"I"},{"token":"medyo","english":"a bit"},{"token":"busy","english":"busy"},{"token":"lang","english":"just / only"},{"token":"sa","english":"in / at / to"},{"token":"trabaho.","english":"work"}],"speakingPrompt":"Say you''re fine, only a little busy at work."},{"topicKey":"roadmap_intermediate_02_people_you_love","situation":"You arrived twenty minutes late. Explain why.","tagalog":"Na-late ako kanina kasi grabe ang traffic sa EDSA.","translation":"I was late earlier because the traffic on EDSA was terrible.","chunks":[{"tagalog":"Na-late ako kanina","english":"I was late earlier","note":"Na- + English verb means it happened to you."},{"tagalog":"kasi grabe","english":"because it was terrible","note":"Kasi means ''because''. It''s how people give reasons in conversation."},{"tagalog":"ang traffic sa EDSA.","english":"the traffic on EDSA.","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Na-late","english":"was late"},{"token":"ako","english":"I"},{"token":"kanina","english":"earlier today"},{"token":"kasi","english":"because"},{"token":"grabe","english":"wow / terrible"},{"token":"ang","english":"the (focus marker)"},{"token":"traffic","english":"traffic"},{"token":"sa","english":"in / at / to"},{"token":"EDSA.","english":"EDSA (main highway)"}],"speakingPrompt":"Say you were late and give the reason: the traffic.","responseExercise":{"promptTagalog":"Na-late ako kanina kasi grabe ang traffic sa EDSA.","promptTranslation":"I was late earlier because the traffic on EDSA was terrible.","options":[{"englishTranslation":"Apparently Carlo is getting married in December!"},{"englishTranslation":"I was late earlier because the traffic on EDSA was terrible."},{"englishTranslation":"How about you, how''s your love life?"}],"correctOptionIndex":1}},{"topicKey":"roadmap_intermediate_02_people_you_love","situation":"You heard some gossip about your old classmate Carlo. Pass it on.","tagalog":"Ikakasal na raw si Carlo sa Disyembre!","translation":"Apparently Carlo is getting married in December!","chunks":[{"tagalog":"Ikakasal na raw","english":"is apparently getting married","note":"Raw means ''they say''. Use raw after a vowel and daw after a consonant."},{"tagalog":"si Carlo","english":"Carlo","note":"Si marks a person''s name."},{"tagalog":"sa Disyembre!","english":"in December!","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Ikakasal","english":"will get married"},{"token":"na","english":"already / now"},{"token":"raw","english":"they say / apparently"},{"token":"si","english":"(name marker)"},{"token":"Carlo","english":"Carlo"},{"token":"sa","english":"in / at / to"},{"token":"Disyembre!","english":"December"}],"speakingPrompt":"Share the news you heard from someone else."},{"topicKey":"roadmap_intermediate_02_people_you_love","situation":"You''ve talked about yourself enough. Turn the question back to Bea.","tagalog":"Ikaw naman, kumusta na ang love life mo?","translation":"How about you, how''s your love life?","chunks":[{"tagalog":"Ikaw naman,","english":"how about you,","note":"Ikaw naman means ''your turn'': naman shifts the focus to the other person."},{"tagalog":"kumusta na","english":"how is it now","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"ang love life mo?","english":"your love life?","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Ikaw","english":"you (casual)"},{"token":"naman,","english":"(softener)"},{"token":"kumusta","english":"how is"},{"token":"na","english":"already / now"},{"token":"ang","english":"the (focus marker)"},{"token":"love","english":"love"},{"token":"life","english":"life"},{"token":"mo?","english":"you / your (casual)"}],"speakingPrompt":"Turn the conversation to her and ask about her love life.","responseExercise":{"promptTagalog":"Ikaw naman, kumusta na ang love life mo?","promptTranslation":"How about you, how''s your love life?","options":[{"englishTranslation":"Hey, it''s you! We haven''t seen each other in so long."},{"englishTranslation":"How about you, how''s your love life?"},{"englishTranslation":"I''m okay. Just a bit busy with work."}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Uy","english":"hey,","example":"Uy, ikaw pala! Ang tagal na nating hindi nagkita.","exampleTranslation":"Hey, it''s you! We haven''t seen each other in so long."},{"tagalog":"ikaw pala","english":"oh, it''s you!","example":"Uy, ikaw pala! Ang tagal na nating hindi nagkita.","exampleTranslation":"Hey, it''s you! We haven''t seen each other in so long."},{"tagalog":"Ang tagal na","english":"it''s been so long","example":"Uy, ikaw pala! Ang tagal na nating hindi nagkita.","exampleTranslation":"Hey, it''s you! We haven''t seen each other in so long."},{"tagalog":"nating hindi nagkita","english":"since we''ve seen each other.","example":"Uy, ikaw pala! Ang tagal na nating hindi nagkita.","exampleTranslation":"Hey, it''s you! We haven''t seen each other in so long."},{"tagalog":"Okay naman ako","english":"I''m okay,","example":"Okay naman ako, medyo busy lang sa trabaho.","exampleTranslation":"I''m okay. Just a bit busy with work."},{"tagalog":"medyo busy lang","english":"just a bit busy","example":"Okay naman ako, medyo busy lang sa trabaho.","exampleTranslation":"I''m okay. Just a bit busy with work."},{"tagalog":"sa trabaho","english":"at work.","example":"Okay naman ako, medyo busy lang sa trabaho.","exampleTranslation":"I''m okay. Just a bit busy with work."},{"tagalog":"Na-late ako kanina","english":"I was late earlier","example":"Na-late ako kanina kasi grabe ang traffic sa EDSA.","exampleTranslation":"I was late earlier because the traffic on EDSA was terrible."},{"tagalog":"kasi grabe","english":"because it was terrible","example":"Na-late ako kanina kasi grabe ang traffic sa EDSA.","exampleTranslation":"I was late earlier because the traffic on EDSA was terrible."},{"tagalog":"ang traffic sa EDSA","english":"the traffic on EDSA.","example":"Na-late ako kanina kasi grabe ang traffic sa EDSA.","exampleTranslation":"I was late earlier because the traffic on EDSA was terrible."}]}'::jsonb, 'f83604bf1301ae812c66ec00d5220e486cd375e97853d8909607992633e52ec6', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
  ),
(
    '43020000-0000-4000-8100-000000000003'::uuid,
    'intermediate-03-weekend-stories', 'Weekend stories', 'Say what you did, what you''re doing and what you will do.',
    'intermediate', 5, 3, false, 1,
