    2.40, array['family', 'partner']::text[], 'authored_roadmap', 'native_speaker_review_required',
    '{"title":"Weekend stories","scenarioKey":"roadmap_intermediate_03_people_you_love","scenario":"Say what you did, what you''re doing and what you will do.","minutes":5,"difficulty":2.4,"rounds":[{"topicKey":"roadmap_intermediate_03_people_you_love","situation":"It''s Saturday evening and you''re on a video call with your partner Mark''s sister, Joy. She asks about your day.","tagalog":"Kaninang umaga, naglaba ako at naglinis ng bahay.","translation":"This morning I did the laundry and cleaned the house.","chunks":[{"tagalog":"Kaninang umaga,","english":"this morning,","note":"Kanina means ''earlier today''."},{"tagalog":"naglaba ako","english":"I did the laundry","note":"Completed aspect: mag- becomes nag-. Maglaba, naglaba."},{"tagalog":"at naglinis ng bahay.","english":"and cleaned the house.","note":"Same pattern: maglinis, naglinis."}],"wordGlosses":[{"token":"Kaninang","english":"earlier (linked)"},{"token":"umaga,","english":"morning"},{"token":"naglaba","english":"did the laundry"},{"token":"ako","english":"I"},{"token":"at","english":"and"},{"token":"naglinis","english":"cleaned"},{"token":"ng","english":"of / (object marker)"},{"token":"bahay.","english":"house / home"}],"speakingPrompt":"Tell her the chores you finished this morning."},{"topicKey":"roadmap_intermediate_03_people_you_love","situation":"Joy asks what you did after that.","tagalog":"Pagkatapos, kumain kami ni Mark sa labas.","translation":"After that, Mark and I ate out.","chunks":[{"tagalog":"Pagkatapos,","english":"after that,","note":"Start the thought with this reusable chunk."},{"tagalog":"kumain kami","english":"we ate","note":"Completed aspect of -um- verbs: kain becomes kumain. Kami means ''we, not you''."},{"tagalog":"ni Mark sa labas.","english":"Mark and I, out.","note":"Kami ni Mark means ''Mark and I''."}],"wordGlosses":[{"token":"Pagkatapos,","english":"after that"},{"token":"kumain","english":"ate / to eat"},{"token":"kami","english":"we (not you)"},{"token":"ni","english":"and (with a name)"},{"token":"Mark","english":"Mark"},{"token":"sa","english":"in / at / to"},{"token":"labas.","english":"outside / out"}],"speakingPrompt":"Say you and Mark went out to eat."},{"topicKey":"roadmap_intermediate_03_people_you_love","situation":"Joy hears a movie playing in the background.","tagalog":"Ngayon, nanonood kami ng pelikula sa bahay.","translation":"Right now we''re watching a movie at home.","chunks":[{"tagalog":"Ngayon,","english":"right now,","note":"Start the thought with this reusable chunk."},{"tagalog":"nanonood kami","english":"we''re watching","note":"Ongoing aspect: repeat the first syllable of the root. Nood becomes nanonood."},{"tagalog":"ng pelikula sa bahay.","english":"a movie at home.","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Ngayon,","english":"now"},{"token":"nanonood","english":"are watching"},{"token":"kami","english":"we (not you)"},{"token":"ng","english":"of / (object marker)"},{"token":"pelikula","english":"movie"},{"token":"sa","english":"in / at / to"},{"token":"bahay.","english":"house / home"}],"speakingPrompt":"Tell her what you two are doing at the moment.","responseExercise":{"promptTagalog":"Ngayon, nanonood kami ng pelikula sa bahay.","promptTranslation":"Right now we''re watching a movie at home.","options":[{"englishTranslation":"Tomorrow we''re going to Tagaytay to eat bulalo."},{"englishTranslation":"Right now we''re watching a movie at home."},{"englishTranslation":"Are you coming with us? We''re leaving around seven."}],"correctOptionIndex":1}},{"topicKey":"roadmap_intermediate_03_people_you_love","situation":"Joy asks if you have plans for tomorrow.","tagalog":"Bukas, pupunta kami sa Tagaytay para kumain ng bulalo.","translation":"Tomorrow we''re going to Tagaytay to eat bulalo.","chunks":[{"tagalog":"Bukas,","english":"tomorrow,","note":"Start the thought with this reusable chunk."},{"tagalog":"pupunta kami sa Tagaytay","english":"we''ll go to Tagaytay","note":"Contemplated aspect: repeat the first syllable, no -um-. Punta becomes pupunta."},{"tagalog":"para kumain ng bulalo.","english":"to eat bulalo.","note":"After para, use the plain infinitive."}],"wordGlosses":[{"token":"Bukas,","english":"tomorrow"},{"token":"pupunta","english":"will go"},{"token":"kami","english":"we (not you)"},{"token":"sa","english":"in / at / to"},{"token":"Tagaytay","english":"Tagaytay"},{"token":"para","english":"so that / for"},{"token":"kumain","english":"ate / to eat"},{"token":"ng","english":"of / (object marker)"},{"token":"bulalo.","english":"beef bone-marrow soup"}],"speakingPrompt":"Tell her your plan for tomorrow and why."},{"topicKey":"roadmap_intermediate_03_people_you_love","situation":"There''s a free seat in the car. Invite Joy along.","tagalog":"Sasama ka ba sa amin? Aalis kami mga alas-siyete.","translation":"Are you coming with us? We''re leaving around seven.","chunks":[{"tagalog":"Sasama ka ba","english":"will you come along","note":"Contemplated aspect of sumama: sasama. Ba turns it into a question."},{"tagalog":"sa amin?","english":"with us?","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"Aalis kami","english":"we''ll leave","note":"Alis becomes aalis: a vowel root just doubles its vowel."},{"tagalog":"mga alas-siyete.","english":"around seven.","note":"Mga before a time means ''around''."}],"wordGlosses":[{"token":"Sasama","english":"will come along"},{"token":"ka","english":"you (casual)"},{"token":"ba","english":"(question marker)"},{"token":"sa","english":"in / at / to"},{"token":"amin?","english":"us"},{"token":"Aalis","english":"will leave"},{"token":"kami","english":"we (not you)"},{"token":"mga","english":"around / (plural)"},{"token":"alas-siyete.","english":"seven o''clock"}],"speakingPrompt":"Invite her and say what time you''re leaving.","responseExercise":{"promptTagalog":"Sasama ka ba sa amin? Aalis kami mga alas-siyete.","promptTranslation":"Are you coming with us? We''re leaving around seven.","options":[{"englishTranslation":"This morning I did the laundry and cleaned the house."},{"englishTranslation":"Are you coming with us? We''re leaving around seven."},{"englishTranslation":"After that, Mark and I ate out."}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Kaninang umaga","english":"this morning,","example":"Kaninang umaga, naglaba ako at naglinis ng bahay.","exampleTranslation":"This morning I did the laundry and cleaned the house."},{"tagalog":"naglaba ako","english":"I did the laundry","example":"Kaninang umaga, naglaba ako at naglinis ng bahay.","exampleTranslation":"This morning I did the laundry and cleaned the house."},{"tagalog":"at naglinis ng bahay","english":"and cleaned the house.","example":"Kaninang umaga, naglaba ako at naglinis ng bahay.","exampleTranslation":"This morning I did the laundry and cleaned the house."},{"tagalog":"Pagkatapos","english":"after that,","example":"Pagkatapos, kumain kami ni Mark sa labas.","exampleTranslation":"After that, Mark and I ate out."},{"tagalog":"kumain kami","english":"we ate","example":"Pagkatapos, kumain kami ni Mark sa labas.","exampleTranslation":"After that, Mark and I ate out."},{"tagalog":"ni Mark sa labas","english":"Mark and I, out.","example":"Pagkatapos, kumain kami ni Mark sa labas.","exampleTranslation":"After that, Mark and I ate out."},{"tagalog":"Ngayon","english":"right now,","example":"Ngayon, nanonood kami ng pelikula sa bahay.","exampleTranslation":"Right now we''re watching a movie at home."},{"tagalog":"nanonood kami","english":"we''re watching","example":"Ngayon, nanonood kami ng pelikula sa bahay.","exampleTranslation":"Right now we''re watching a movie at home."},{"tagalog":"ng pelikula sa bahay","english":"a movie at home.","example":"Ngayon, nanonood kami ng pelikula sa bahay.","exampleTranslation":"Right now we''re watching a movie at home."},{"tagalog":"Bukas","english":"tomorrow,","example":"Bukas, pupunta kami sa Tagaytay para kumain ng bulalo.","exampleTranslation":"Tomorrow we''re going to Tagaytay to eat bulalo."}]}'::jsonb, '120e9f2222e16a1db0e46a5b3e4d94f976867d5fb92aeb9a20ec928516e6f5cb', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
