    '{"title":"Ask someone out to the movies","scenarioKey":"roadmap_intermediate_04_people_you_love","scenario":"Ask for a date, set the time and place, then book the tickets.","minutes":5,"difficulty":2.45,"rounds":[{"topicKey":"roadmap_intermediate_04_people_you_love","situation":"You''ve been chatting with Mika after your dance class for weeks. You finally work up the nerve.","tagalog":"Libre ka ba sa Sabado ng gabi?","translation":"Are you free on Saturday night?","chunks":[{"tagalog":"Libre ka ba","english":"are you free","note":"Libre means both ''free of plans'' and ''my treat''."},{"tagalog":"sa Sabado ng gabi?","english":"on Saturday night?","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Libre","english":"free"},{"token":"ka","english":"you (casual)"},{"token":"ba","english":"(question marker)"},{"token":"sa","english":"in / at / to"},{"token":"Sabado","english":"Saturday"},{"token":"ng","english":"of / (object marker)"},{"token":"gabi?","english":"night / evening"}],"speakingPrompt":"Ask if she''s free on Saturday night."},{"topicKey":"roadmap_intermediate_04_people_you_love","situation":"She smiles and says she is. Make your invitation.","tagalog":"Gusto mo bang manood ng sine kasama ko?","translation":"Would you like to watch a movie with me?","chunks":[{"tagalog":"Gusto mo bang","english":"would you like","note":"Ba takes the linker -ng before the next verb: ''bang manood''."},{"tagalog":"manood ng sine","english":"to watch a movie","note":"Sine is the everyday word for the cinema."},{"tagalog":"kasama ko?","english":"with me?","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Gusto","english":"want / like"},{"token":"mo","english":"you / your (casual)"},{"token":"bang","english":"(question marker + linker)"},{"token":"manood","english":"to watch"},{"token":"ng","english":"of / (object marker)"},{"token":"sine","english":"movie / cinema"},{"token":"kasama","english":"with / included"},{"token":"ko?","english":"I / my"}],"speakingPrompt":"Invite her to see a movie with you."},{"topicKey":"roadmap_intermediate_04_people_you_love","situation":"She says yes. Suggest a place and a time to meet.","tagalog":"Kita tayo sa Megamall mga alas-sais, okay lang ba?","translation":"Let''s meet at Megamall around six, is that okay?","chunks":[{"tagalog":"Kita tayo","english":"let''s meet","note":"Kita tayo is the casual short form of magkita tayo."},{"tagalog":"sa Megamall","english":"at Megamall","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"mga alas-sais,","english":"around six,","note":"Clock times use Spanish numbers: alas-sais."},{"tagalog":"okay lang ba?","english":"is that okay?","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Kita","english":"meet (short for magkita)"},{"token":"tayo","english":"we / let''s (incl. you)"},{"token":"sa","english":"in / at / to"},{"token":"Megamall","english":"Megamall"},{"token":"mga","english":"around / (plural)"},{"token":"alas-sais,","english":"six o''clock"},{"token":"okay","english":"okay"},{"token":"lang","english":"just / only"},{"token":"ba?","english":"(question marker)"}],"speakingPrompt":"Suggest meeting at the mall at about six and check it works for her.","responseExercise":{"promptTagalog":"Kita tayo sa Megamall mga alas-sais, okay lang ba?","promptTranslation":"Let''s meet at Megamall around six, is that okay?","options":[{"englishTranslation":"Two tickets for the seven-thirty show, please."},{"englishTranslation":"Let''s meet at Megamall around six, is that okay?"},{"englishTranslation":"Can we sit together, somewhere in the middle?"}],"correctOptionIndex":1}},{"topicKey":"roadmap_intermediate_04_people_you_love","situation":"Saturday night at the cinema counter. The young cashier is waiting.","tagalog":"Dalawang ticket po para sa alas-siyete y medya.","translation":"Two tickets for the seven-thirty show, please.","chunks":[{"tagalog":"Dalawang ticket po","english":"two tickets, please","note":"Numbers link to the noun with -ng: dalawa becomes dalawang."},{"tagalog":"para sa alas-siyete y medya.","english":"for half past seven.","note":"Y medya means ''and a half''."}],"wordGlosses":[{"token":"Dalawang","english":"two"},{"token":"ticket","english":"ticket"},{"token":"po","english":"(respect marker)"},{"token":"para","english":"so that / for"},{"token":"sa","english":"in / at / to"},{"token":"alas-siyete","english":"seven o''clock"},{"token":"y","english":"and (in times)"},{"token":"medya.","english":"half (thirty minutes)"}],"speakingPrompt":"Ask the cashier for two tickets to the half past seven screening."},{"topicKey":"roadmap_intermediate_04_people_you_love","situation":"The cashier turns the screen to show you the seating map.","tagalog":"Pwede po bang magkatabi kami, sa bandang gitna?","translation":"Can we sit together, somewhere in the middle?","chunks":[{"tagalog":"Pwede po bang","english":"may we","note":"Pwede po bang opens any polite request."},{"tagalog":"magkatabi kami,","english":"sit side by side,","note":"Magka- means ''together'': magkatabi is ''next to each other''."},{"tagalog":"sa bandang gitna?","english":"around the middle?","note":"Banda means ''around, near''."}],"wordGlosses":[{"token":"Pwede","english":"can / may"},{"token":"po","english":"(respect marker)"},{"token":"bang","english":"(question marker + linker)"},{"token":"magkatabi","english":"sit side by side"},{"token":"kami,","english":"we (not you)"},{"token":"sa","english":"in / at / to"},{"token":"bandang","english":"around (linked)"},{"token":"gitna?","english":"middle"}],"speakingPrompt":"Ask for two seats next to each other near the middle.","responseExercise":{"promptTagalog":"Pwede po bang magkatabi kami, sa bandang gitna?","promptTranslation":"Can we sit together, somewhere in the middle?","options":[{"englishTranslation":"Are you free on Saturday night?"},{"englishTranslation":"Can we sit together, somewhere in the middle?"},{"englishTranslation":"Would you like to watch a movie with me?"}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Libre ka ba","english":"are you free","example":"Libre ka ba sa Sabado ng gabi?","exampleTranslation":"Are you free on Saturday night?"},{"tagalog":"sa Sabado ng gabi","english":"on Saturday night?","example":"Libre ka ba sa Sabado ng gabi?","exampleTranslation":"Are you free on Saturday night?"},{"tagalog":"Gusto mo bang","english":"would you like","example":"Gusto mo bang manood ng sine kasama ko?","exampleTranslation":"Would you like to watch a movie with me?"},{"tagalog":"manood ng sine","english":"to watch a movie","example":"Gusto mo bang manood ng sine kasama ko?","exampleTranslation":"Would you like to watch a movie with me?"},{"tagalog":"kasama ko","english":"with me?","example":"Gusto mo bang manood ng sine kasama ko?","exampleTranslation":"Would you like to watch a movie with me?"},{"tagalog":"Kita tayo","english":"let''s meet","example":"Kita tayo sa Megamall mga alas-sais, okay lang ba?","exampleTranslation":"Let''s meet at Megamall around six, is that okay?"},{"tagalog":"sa Megamall","english":"at Megamall","example":"Kita tayo sa Megamall mga alas-sais, okay lang ba?","exampleTranslation":"Let''s meet at Megamall around six, is that okay?"},{"tagalog":"mga alas-sais","english":"around six,","example":"Kita tayo sa Megamall mga alas-sais, okay lang ba?","exampleTranslation":"Let''s meet at Megamall around six, is that okay?"},{"tagalog":"okay lang ba","english":"is that okay?","example":"Kita tayo sa Megamall mga alas-sais, okay lang ba?","exampleTranslation":"Let''s meet at Megamall around six, is that okay?"},{"tagalog":"Dalawang ticket po","english":"two tickets, please","example":"Dalawang ticket po para sa alas-siyete y medya.","exampleTranslation":"Two tickets for the seven-thirty show, please."}]}'::jsonb, 'bf0775df625ef8a0b0a1c3eb0c0d373f6aefc4fd396aaba1e5983f18eb6c202f', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
