    '{"title":"Island trip to Puerto Galera","scenarioKey":"roadmap_intermediate_05_plans_and_practicalities","scenario":"Book the boat, deal with a tricycle driver and check in.","minutes":5,"difficulty":2.55,"rounds":[{"topicKey":"roadmap_intermediate_05_plans_and_practicalities","situation":"You''re at the ticket booth at Batangas port. The ferry office has a long queue behind you.","tagalog":"Isang round trip po papuntang Puerto Galera, yung alas-diyes.","translation":"One round trip to Puerto Galera, the ten o''clock one, please.","chunks":[{"tagalog":"Isang round trip po","english":"one round trip, please","note":"Start the thought with this reusable chunk."},{"tagalog":"papuntang Puerto Galera,","english":"going to Puerto Galera,","note":"Papunta means ''heading to''."},{"tagalog":"yung alas-diyes.","english":"the ten o''clock one.","note":"Yung points to a specific one: ''the one at ten''."}],"wordGlosses":[{"token":"Isang","english":"one / a"},{"token":"round","english":"round"},{"token":"trip","english":"trip"},{"token":"po","english":"(respect marker)"},{"token":"papuntang","english":"going to"},{"token":"Puerto","english":"Puerto (place name)"},{"token":"Galera,","english":"Galera (place name)"},{"token":"yung","english":"the / the one"},{"token":"alas-diyes.","english":"ten o''clock"}],"speakingPrompt":"Ask for a return ticket on the ten o''clock boat."},{"topicKey":"roadmap_intermediate_05_plans_and_practicalities","situation":"You''ll be coming back tomorrow and want to plan ahead.","tagalog":"Anong oras po ang huling biyahe pabalik bukas?","translation":"What time is the last trip back tomorrow?","chunks":[{"tagalog":"Anong oras po","english":"what time","note":"Anong is ano + -ng: ''what time''."},{"tagalog":"ang huling biyahe","english":"is the last trip","note":"Huli + -ng: ''huling'' means ''last''."},{"tagalog":"pabalik bukas?","english":"back tomorrow?","note":"Pabalik means ''heading back''."}],"wordGlosses":[{"token":"Anong","english":"what (linked)"},{"token":"oras","english":"time / hour"},{"token":"po","english":"(respect marker)"},{"token":"ang","english":"the (focus marker)"},{"token":"huling","english":"last"},{"token":"biyahe","english":"trip"},{"token":"pabalik","english":"heading back"},{"token":"bukas?","english":"tomorrow"}],"speakingPrompt":"Ask the clerk when the last boat back leaves tomorrow."},{"topicKey":"roadmap_intermediate_05_plans_and_practicalities","situation":"The boat docks. Tricycle drivers crowd the pier. You wave one over.","tagalog":"Kuya, magkano po hanggang White Beach?","translation":"How much to White Beach, sir?","chunks":[{"tagalog":"Kuya,","english":"sir,","note":"Kuya (''big brother'') is how you address any man a bit older: drivers, guards, vendors."},{"tagalog":"magkano po","english":"how much","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"hanggang White Beach?","english":"to White Beach?","note":"Hanggang means ''up to, as far as''."}],"wordGlosses":[{"token":"Kuya,","english":"sir (big brother)"},{"token":"magkano","english":"how much"},{"token":"po","english":"(respect marker)"},{"token":"hanggang","english":"up to / as far as"},{"token":"White","english":"White (beach name)"},{"token":"Beach?","english":"beach"}],"speakingPrompt":"Ask the driver the fare to the beach.","responseExercise":{"promptTagalog":"Kuya, magkano po hanggang White Beach?","promptTranslation":"How much to White Beach, sir?","options":[{"englishTranslation":"That''s too expensive. Can we make it fifty instead?"},{"englishTranslation":"How much to White Beach, sir?"},{"englishTranslation":"Hi, I have a booking under the name Alex Smith."}],"correctOptionIndex":1}},{"topicKey":"roadmap_intermediate_05_plans_and_practicalities","situation":"He quotes a price that''s clearly for tourists. Haggle politely.","tagalog":"Ang mahal naman po. Pwede bang singkwenta na lang?","translation":"That''s too expensive. Can we make it fifty instead?","chunks":[{"tagalog":"Ang mahal naman po.","english":"that''s too expensive.","note":"Naman here adds a gentle complaint: ''that''s a bit much''."},{"tagalog":"Pwede bang","english":"can it be","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"singkwenta na lang?","english":"just fifty instead?","note":"Prices often use Spanish numbers: singkwenta is fifty. Na lang means ''instead''."}],"wordGlosses":[{"token":"Ang","english":"the (focus marker)"},{"token":"mahal","english":"expensive"},{"token":"naman","english":"(softener)"},{"token":"po.","english":"(respect marker)"},{"token":"Pwede","english":"can / may"},{"token":"bang","english":"(question marker + linker)"},{"token":"singkwenta","english":"fifty"},{"token":"na","english":"already / now"},{"token":"lang?","english":"just / only"}],"speakingPrompt":"Say it''s too pricey and offer fifty pesos."},{"topicKey":"roadmap_intermediate_05_plans_and_practicalities","situation":"You reach the beach resort. A receptionist greets you at the front desk.","tagalog":"Hi po, may booking po ako sa pangalang Alex Smith.","translation":"Hi, I have a booking under the name Alex Smith.","chunks":[{"tagalog":"Hi po,","english":"hi,","note":"Even an English ''hi'' gets po for staff and strangers."},{"tagalog":"may booking po ako","english":"I have a booking","note":"May means ''there is, have''."},{"tagalog":"sa pangalang Alex Smith.","english":"under the name Alex Smith.","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Hi","english":"hi"},{"token":"po,","english":"(respect marker)"},{"token":"may","english":"there is / have"},{"token":"booking","english":"booking"},{"token":"po","english":"(respect marker)"},{"token":"ako","english":"I"},{"token":"sa","english":"in / at / to"},{"token":"pangalang","english":"name (linked)"},{"token":"Alex","english":"Alex"},{"token":"Smith.","english":"Smith"}],"speakingPrompt":"Greet the receptionist and give the name on your booking.","responseExercise":{"promptTagalog":"Hi po, may booking po ako sa pangalang Alex Smith.","promptTranslation":"Hi, I have a booking under the name Alex Smith.","options":[{"englishTranslation":"One round trip to Puerto Galera, the ten o''clock one, please."},{"englishTranslation":"Hi, I have a booking under the name Alex Smith."},{"englishTranslation":"What time is the last trip back tomorrow?"}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Isang round trip po","english":"one round trip, please","example":"Isang round trip po papuntang Puerto Galera, yung alas-diyes.","exampleTranslation":"One round trip to Puerto Galera, the ten o''clock one, please."},{"tagalog":"papuntang Puerto Galera","english":"going to Puerto Galera,","example":"Isang round trip po papuntang Puerto Galera, yung alas-diyes.","exampleTranslation":"One round trip to Puerto Galera, the ten o''clock one, please."},{"tagalog":"yung alas-diyes","english":"the ten o''clock one.","example":"Isang round trip po papuntang Puerto Galera, yung alas-diyes.","exampleTranslation":"One round trip to Puerto Galera, the ten o''clock one, please."},{"tagalog":"Anong oras po","english":"what time","example":"Anong oras po ang huling biyahe pabalik bukas?","exampleTranslation":"What time is the last trip back tomorrow?"},{"tagalog":"ang huling biyahe","english":"is the last trip","example":"Anong oras po ang huling biyahe pabalik bukas?","exampleTranslation":"What time is the last trip back tomorrow?"},{"tagalog":"pabalik bukas","english":"back tomorrow?","example":"Anong oras po ang huling biyahe pabalik bukas?","exampleTranslation":"What time is the last trip back tomorrow?"},{"tagalog":"Kuya","english":"sir,","example":"Kuya, magkano po hanggang White Beach?","exampleTranslation":"How much to White Beach, sir?"},{"tagalog":"magkano po","english":"how much","example":"Kuya, magkano po hanggang White Beach?","exampleTranslation":"How much to White Beach, sir?"},{"tagalog":"hanggang White Beach","english":"to White Beach?","example":"Kuya, magkano po hanggang White Beach?","exampleTranslation":"How much to White Beach, sir?"},{"tagalog":"Ang mahal naman po","english":"that''s too expensive.","example":"Ang mahal naman po. Pwede bang singkwenta na lang?","exampleTranslation":"That''s too expensive. Can we make it fifty instead?"}]}'::jsonb, '93addc6c402d3a5eff155939b54cf736f6dedf3fc3f02774ce4a362fab9b9f01', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
