    '{"title":"At the doctor and the pharmacy","scenarioKey":"roadmap_intermediate_06_plans_and_practicalities","scenario":"Describe your symptoms and leave with the right medicine.","minutes":5,"difficulty":2.6,"rounds":[{"topicKey":"roadmap_intermediate_06_plans_and_practicalities","situation":"You''re sitting across from the doctor at a clinic in Quezon City. She asks what''s wrong.","tagalog":"Dok, tatlong araw na po akong may lagnat.","translation":"Doc, I''ve had a fever for three days.","chunks":[{"tagalog":"Dok,","english":"Doc,","note":"Dok is how everyone addresses a doctor."},{"tagalog":"tatlong araw na","english":"three days now","note":"Na after a length of time means ''already, so far''."},{"tagalog":"po akong may lagnat.","english":"I''ve had a fever.","note":"Ako takes the linker -ng before may: ''akong may lagnat''."}],"wordGlosses":[{"token":"Dok,","english":"Doc"},{"token":"tatlong","english":"three"},{"token":"araw","english":"day(s)"},{"token":"na","english":"already / now"},{"token":"po","english":"(respect marker)"},{"token":"akong","english":"I (linked)"},{"token":"may","english":"there is / have"},{"token":"lagnat.","english":"fever"}],"speakingPrompt":"Tell the doctor how long you''ve had a fever."},{"topicKey":"roadmap_intermediate_06_plans_and_practicalities","situation":"The doctor asks if you have any other symptoms.","tagalog":"Masakit din po ang lalamunan ko, at inuubo ako.","translation":"My throat hurts too, and I''ve been coughing.","chunks":[{"tagalog":"Masakit din po","english":"also hurts","note":"Din follows a consonant (masakit); rin would follow a vowel."},{"tagalog":"ang lalamunan ko,","english":"my throat,","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"at inuubo ako.","english":"and I''ve been coughing.","note":"Inuubo is ''being hit by a cough'': the illness is the doer."}],"wordGlosses":[{"token":"Masakit","english":"hurts / painful"},{"token":"din","english":"also"},{"token":"po","english":"(respect marker)"},{"token":"ang","english":"the (focus marker)"},{"token":"lalamunan","english":"throat"},{"token":"ko,","english":"I / my"},{"token":"at","english":"and"},{"token":"inuubo","english":"coughing"},{"token":"ako.","english":"I"}],"speakingPrompt":"Describe your sore throat and your cough."},{"topicKey":"roadmap_intermediate_06_plans_and_practicalities","situation":"Before writing the prescription, she asks if you''re allergic to anything.","tagalog":"Wala po akong allergy sa kahit anong gamot.","translation":"I''m not allergic to any medicine.","chunks":[{"tagalog":"Wala po akong allergy","english":"I don''t have an allergy","note":"Wala + -ng means ''have no''."},{"tagalog":"sa kahit anong gamot.","english":"to any medicine.","note":"Kahit ano means ''any at all''."}],"wordGlosses":[{"token":"Wala","english":"there''s no / have no"},{"token":"po","english":"(respect marker)"},{"token":"akong","english":"I (linked)"},{"token":"allergy","english":"allergy"},{"token":"sa","english":"in / at / to"},{"token":"kahit","english":"any / even"},{"token":"anong","english":"what (linked)"},{"token":"gamot.","english":"medicine"}],"speakingPrompt":"Tell her you have no medicine allergies.","responseExercise":{"promptTagalog":"Wala po akong allergy sa kahit anong gamot.","promptTranslation":"I''m not allergic to any medicine.","options":[{"englishTranslation":"Miss, here''s my prescription from the doctor."},{"englishTranslation":"I''m not allergic to any medicine."},{"englishTranslation":"How many times a day should I take this?"}],"correctOptionIndex":1}},{"topicKey":"roadmap_intermediate_06_plans_and_practicalities","situation":"At the pharmacy counter, you hand the prescription to the pharmacist, a young woman.","tagalog":"Ate, heto po ang reseta ko galing sa doktor.","translation":"Miss, here''s my prescription from the doctor.","chunks":[{"tagalog":"Ate,","english":"miss,","note":"Ate (''big sister'') is a warm way to address a woman serving you."},{"tagalog":"heto po ang reseta ko","english":"here''s my prescription","note":"Heto means ''here it is''."},{"tagalog":"galing sa doktor.","english":"from the doctor.","note":"Galing sa means ''coming from''."}],"wordGlosses":[{"token":"Ate,","english":"miss (big sister)"},{"token":"heto","english":"here it is"},{"token":"po","english":"(respect marker)"},{"token":"ang","english":"the (focus marker)"},{"token":"reseta","english":"prescription"},{"token":"ko","english":"I / my"},{"token":"galing","english":"coming from"},{"token":"sa","english":"in / at / to"},{"token":"doktor.","english":"doctor"}],"speakingPrompt":"Hand over the prescription and say where it''s from."},{"topicKey":"roadmap_intermediate_06_plans_and_practicalities","situation":"She puts the tablets on the counter. You want to be sure how to take them.","tagalog":"Ilang beses ko po ba ito iinumin sa isang araw?","translation":"How many times a day should I take this?","chunks":[{"tagalog":"Ilang beses","english":"how many times","note":"Ilan + -g: ''ilang beses'' means ''how many times''."},{"tagalog":"ko po ba ito iinumin","english":"should I take this","note":"Short words line up: ko, then po, then ba. Iinumin is the future of inumin."},{"tagalog":"sa isang araw?","english":"in a day?","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Ilang","english":"how many"},{"token":"beses","english":"times"},{"token":"ko","english":"I / my"},{"token":"po","english":"(respect marker)"},{"token":"ba","english":"(question marker)"},{"token":"ito","english":"this"},{"token":"iinumin","english":"will take (drink)"},{"token":"sa","english":"in / at / to"},{"token":"isang","english":"one / a"},{"token":"araw?","english":"day(s)"}],"speakingPrompt":"Ask how many times a day to take the medicine.","responseExercise":{"promptTagalog":"Ilang beses ko po ba ito iinumin sa isang araw?","promptTranslation":"How many times a day should I take this?","options":[{"englishTranslation":"Doc, I''ve had a fever for three days."},{"englishTranslation":"How many times a day should I take this?"},{"englishTranslation":"My throat hurts too, and I''ve been coughing."}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Dok","english":"Doc,","example":"Dok, tatlong araw na po akong may lagnat.","exampleTranslation":"Doc, I''ve had a fever for three days."},{"tagalog":"tatlong araw na","english":"three days now","example":"Dok, tatlong araw na po akong may lagnat.","exampleTranslation":"Doc, I''ve had a fever for three days."},{"tagalog":"po akong may lagnat","english":"I''ve had a fever.","example":"Dok, tatlong araw na po akong may lagnat.","exampleTranslation":"Doc, I''ve had a fever for three days."},{"tagalog":"Masakit din po","english":"also hurts","example":"Masakit din po ang lalamunan ko, at inuubo ako.","exampleTranslation":"My throat hurts too, and I''ve been coughing."},{"tagalog":"ang lalamunan ko","english":"my throat,","example":"Masakit din po ang lalamunan ko, at inuubo ako.","exampleTranslation":"My throat hurts too, and I''ve been coughing."},{"tagalog":"at inuubo ako","english":"and I''ve been coughing.","example":"Masakit din po ang lalamunan ko, at inuubo ako.","exampleTranslation":"My throat hurts too, and I''ve been coughing."},{"tagalog":"Wala po akong allergy","english":"I don''t have an allergy","example":"Wala po akong allergy sa kahit anong gamot.","exampleTranslation":"I''m not allergic to any medicine."},{"tagalog":"sa kahit anong gamot","english":"to any medicine.","example":"Wala po akong allergy sa kahit anong gamot.","exampleTranslation":"I''m not allergic to any medicine."},{"tagalog":"Ate","english":"miss,","example":"Ate, heto po ang reseta ko galing sa doktor.","exampleTranslation":"Miss, here''s my prescription from the doctor."},{"tagalog":"heto po ang reseta ko","english":"here''s my prescription","example":"Ate, heto po ang reseta ko galing sa doktor.","exampleTranslation":"Miss, here''s my prescription from the doctor."}]}'::jsonb, 'c639b088c72aa9e05ba386e7cf713bce5e310631112f6b03ead4d8126bb84416', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
