    '{"title":"Renting a condo","scenarioKey":"roadmap_intermediate_07_plans_and_practicalities","scenario":"View a unit, ask the right questions and agree on the rent.","minutes":5,"difficulty":2.7,"rounds":[{"topicKey":"roadmap_intermediate_07_plans_and_practicalities","situation":"The landlady, Mrs. Reyes, is showing you a one-bedroom unit in Mandaluyong. You like the view.","tagalog":"Magkano po ang upa kada buwan?","translation":"How much is the rent per month?","chunks":[{"tagalog":"Magkano po","english":"how much","note":"Start the thought with this reusable chunk."},{"tagalog":"ang upa","english":"is the rent","note":"Upa is rent. Many people also just say ''rent''."},{"tagalog":"kada buwan?","english":"per month?","note":"Kada means ''every, per''."}],"wordGlosses":[{"token":"Magkano","english":"how much"},{"token":"po","english":"(respect marker)"},{"token":"ang","english":"the (focus marker)"},{"token":"upa","english":"rent"},{"token":"kada","english":"per / every"},{"token":"buwan?","english":"month(s)"}],"speakingPrompt":"Ask her the monthly rent."},{"topicKey":"roadmap_intermediate_07_plans_and_practicalities","situation":"She tells you the price. Check what it covers.","tagalog":"Kasama na po ba ang tubig at kuryente sa upa?","translation":"Are water and electricity already included in the rent?","chunks":[{"tagalog":"Kasama na po ba","english":"is it already included","note":"Kasama means ''included, together with''."},{"tagalog":"ang tubig at kuryente","english":"the water and electricity","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"sa upa?","english":"in the rent?","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Kasama","english":"with / included"},{"token":"na","english":"already / now"},{"token":"po","english":"(respect marker)"},{"token":"ba","english":"(question marker)"},{"token":"ang","english":"the (focus marker)"},{"token":"tubig","english":"water"},{"token":"at","english":"and"},{"token":"kuryente","english":"electricity"},{"token":"sa","english":"in / at / to"},{"token":"upa?","english":"rent"}],"speakingPrompt":"Ask whether utilities are part of the rent."},{"topicKey":"roadmap_intermediate_07_plans_and_practicalities","situation":"She mentions an upfront payment. Ask the details.","tagalog":"Ilang buwan po ang advance at deposit na kailangan?","translation":"How many months of advance and deposit do you need?","chunks":[{"tagalog":"Ilang buwan po","english":"how many months","note":"Start the thought with this reusable chunk."},{"tagalog":"ang advance at deposit","english":"the advance and deposit","note":"Landlords use the English terms."},{"tagalog":"na kailangan?","english":"that''s needed?","note":"Na here is a linker joining the noun to its description."}],"wordGlosses":[{"token":"Ilang","english":"how many"},{"token":"buwan","english":"month(s)"},{"token":"po","english":"(respect marker)"},{"token":"ang","english":"the (focus marker)"},{"token":"advance","english":"advance (payment)"},{"token":"at","english":"and"},{"token":"deposit","english":"deposit"},{"token":"na","english":"already / now"},{"token":"kailangan?","english":"needed"}],"speakingPrompt":"Ask how many months you have to pay upfront.","responseExercise":{"promptTagalog":"Ilang buwan po ang advance at deposit na kailangan?","promptTranslation":"How many months of advance and deposit do you need?","options":[{"englishTranslation":"If I sign for a year, could you lower it a little?"},{"englishTranslation":"How many months of advance and deposit do you need?"},{"englishTranslation":"Okay, I''ll take it. When can I move in?"}],"correctOptionIndex":1}},{"topicKey":"roadmap_intermediate_07_plans_and_practicalities","situation":"The rent is a bit above your budget. Try to negotiate.","tagalog":"Kung pipirma po ako ng isang taon, pwede bang bawasan nang kaunti?","translation":"If I sign for a year, could you lower it a little?","chunks":[{"tagalog":"Kung pipirma po ako","english":"if I sign","note":"Kung means ''if''. Pipirma is the future of pumirma."},{"tagalog":"ng isang taon,","english":"for one year,","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"pwede bang bawasan","english":"can you lower it","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"nang kaunti?","english":"a little?","note":"Nang (not ng) introduces how something is done: ''by a little''."}],"wordGlosses":[{"token":"Kung","english":"if"},{"token":"pipirma","english":"will sign"},{"token":"po","english":"(respect marker)"},{"token":"ako","english":"I"},{"token":"ng","english":"of / (object marker)"},{"token":"isang","english":"one / a"},{"token":"taon,","english":"year"},{"token":"pwede","english":"can / may"},{"token":"bang","english":"(question marker + linker)"},{"token":"bawasan","english":"lower / reduce"},{"token":"nang","english":"by / (manner marker)"},{"token":"kaunti?","english":"a little"}],"speakingPrompt":"Offer a one-year contract in exchange for a lower rent."},{"topicKey":"roadmap_intermediate_07_plans_and_practicalities","situation":"She agrees to a small discount. You''re ready to decide.","tagalog":"Sige po, kukunin ko na. Kailan po ako pwedeng lumipat?","translation":"Okay, I''ll take it. When can I move in?","chunks":[{"tagalog":"Sige po,","english":"okay,","note":"Start the thought with this reusable chunk."},{"tagalog":"kukunin ko na.","english":"I''ll take it.","note":"Kukunin is the future of kunin. Na: ''now, settled''."},{"tagalog":"Kailan po ako","english":"when can I","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"pwedeng lumipat?","english":"move in?","note":"Pwede + -ng links to the verb: ''pwedeng lumipat''."}],"wordGlosses":[{"token":"Sige","english":"okay"},{"token":"po,","english":"(respect marker)"},{"token":"kukunin","english":"will take"},{"token":"ko","english":"I / my"},{"token":"na.","english":"already / now"},{"token":"Kailan","english":"when"},{"token":"po","english":"(respect marker)"},{"token":"ako","english":"I"},{"token":"pwedeng","english":"can (linked)"},{"token":"lumipat?","english":"move in"}],"speakingPrompt":"Accept the unit and ask when you can move in.","responseExercise":{"promptTagalog":"Sige po, kukunin ko na. Kailan po ako pwedeng lumipat?","promptTranslation":"Okay, I''ll take it. When can I move in?","options":[{"englishTranslation":"How much is the rent per month?"},{"englishTranslation":"Okay, I''ll take it. When can I move in?"},{"englishTranslation":"Are water and electricity already included in the rent?"}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Magkano po","english":"how much","example":"Magkano po ang upa kada buwan?","exampleTranslation":"How much is the rent per month?"},{"tagalog":"ang upa","english":"is the rent","example":"Magkano po ang upa kada buwan?","exampleTranslation":"How much is the rent per month?"},{"tagalog":"kada buwan","english":"per month?","example":"Magkano po ang upa kada buwan?","exampleTranslation":"How much is the rent per month?"},{"tagalog":"Kasama na po ba","english":"is it already included","example":"Kasama na po ba ang tubig at kuryente sa upa?","exampleTranslation":"Are water and electricity already included in the rent?"},{"tagalog":"ang tubig at kuryente","english":"the water and electricity","example":"Kasama na po ba ang tubig at kuryente sa upa?","exampleTranslation":"Are water and electricity already included in the rent?"},{"tagalog":"sa upa","english":"in the rent?","example":"Kasama na po ba ang tubig at kuryente sa upa?","exampleTranslation":"Are water and electricity already included in the rent?"},{"tagalog":"Ilang buwan po","english":"how many months","example":"Ilang buwan po ang advance at deposit na kailangan?","exampleTranslation":"How many months of advance and deposit do you need?"},{"tagalog":"ang advance at deposit","english":"the advance and deposit","example":"Ilang buwan po ang advance at deposit na kailangan?","exampleTranslation":"How many months of advance and deposit do you need?"},{"tagalog":"na kailangan","english":"that''s needed?","example":"Ilang buwan po ang advance at deposit na kailangan?","exampleTranslation":"How many months of advance and deposit do you need?"},{"tagalog":"Kung pipirma po ako","english":"if I sign","example":"Kung pipirma po ako ng isang taon, pwede bang bawasan nang kaunti?","exampleTranslation":"If I sign for a year, could you lower it a little?"}]}'::jsonb, '17abfdf4b0a18ad3ea8f2557ff5ce35c4e5c1ac794ad79bf85b0a09e3b3361c2', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
  ),
(
    '43020000-0000-4000-8100-000000000008'::uuid,
    'intermediate-08-office-small-talk-in-taglish', 'Office small talk in Taglish', 'Chat with a coworker the way Manila offices really talk.',
