    2.75, array['work']::text[], 'authored_roadmap', 'native_speaker_review_required',
    '{"title":"Office small talk in Taglish","scenarioKey":"roadmap_intermediate_08_work_celebrations_fixes","scenario":"Chat with a coworker the way Manila offices really talk.","minutes":5,"difficulty":2.75,"rounds":[{"topicKey":"roadmap_intermediate_08_work_celebrations_fixes","situation":"Monday morning in the office pantry in BGC. Your coworker Paolo is making coffee.","tagalog":"Uy, good morning! Kumusta yung weekend mo?","translation":"Hey, good morning! How was your weekend?","chunks":[{"tagalog":"Uy, good morning!","english":"hey, good morning!","note":"Offices greet in English all the time."},{"tagalog":"Kumusta yung weekend mo?","english":"how was your weekend?","note":"Yung is the casual form of ''iyong'', pointing to ''the'' weekend."}],"wordGlosses":[{"token":"Uy,","english":"hey"},{"token":"good","english":"good"},{"token":"morning!","english":"morning"},{"token":"Kumusta","english":"how is"},{"token":"yung","english":"the / the one"},{"token":"weekend","english":"weekend"},{"token":"mo?","english":"you / your (casual)"}],"speakingPrompt":"Greet him and ask about his weekend."},{"topicKey":"roadmap_intermediate_08_work_celebrations_fixes","situation":"He asks how your week is looking.","tagalog":"Grabe, ang dami kong deadlines this week.","translation":"Wow, I have so many deadlines this week.","chunks":[{"tagalog":"Grabe,","english":"wow,","note":"Start the thought with this reusable chunk."},{"tagalog":"ang dami kong deadlines","english":"I have so many deadlines","note":"Ang dami + ko + -ng: ''how many I have''. English nouns slot right in."},{"tagalog":"this week.","english":"this week.","note":"Time words often stay in English in Taglish."}],"wordGlosses":[{"token":"Grabe,","english":"wow / terrible"},{"token":"ang","english":"the (focus marker)"},{"token":"dami","english":"so many"},{"token":"kong","english":"I (linked)"},{"token":"deadlines","english":"deadlines"},{"token":"this","english":"this"},{"token":"week.","english":"week"}],"speakingPrompt":"Complain about your workload this week."},{"topicKey":"roadmap_intermediate_08_work_celebrations_fixes","situation":"You both glance at the calendar on his phone.","tagalog":"May meeting pa tayo mamayang alas-dos, di ba?","translation":"We still have a meeting at two later, right?","chunks":[{"tagalog":"May meeting pa tayo","english":"we still have a meeting","note":"Pa means ''still, yet to come''."},{"tagalog":"mamayang alas-dos,","english":"at two later,","note":"Mamaya + -ng: ''later today, at''."},{"tagalog":"di ba?","english":"right?","note":"Di ba is the tag question ''right?'' or ''isn''t it?''"}],"wordGlosses":[{"token":"May","english":"there is / have"},{"token":"meeting","english":"meeting"},{"token":"pa","english":"still / more"},{"token":"tayo","english":"we / let''s (incl. you)"},{"token":"mamayang","english":"later today, at"},{"token":"alas-dos,","english":"two o''clock"},{"token":"di","english":"not (short for hindi)"},{"token":"ba?","english":"(question marker)"}],"speakingPrompt":"Double-check that you both have a meeting this afternoon.","responseExercise":{"promptTagalog":"May meeting pa tayo mamayang alas-dos, di ba?","promptTranslation":"We still have a meeting at two later, right?","options":[{"englishTranslation":"Okay, I''ll just send you the file after lunch."},{"englishTranslation":"We still have a meeting at two later, right?"},{"englishTranslation":"Come on, let''s have lunch together later!"}],"correctOptionIndex":1}},{"topicKey":"roadmap_intermediate_08_work_celebrations_fixes","situation":"Paolo needs a file from you before the meeting.","tagalog":"Sige, i-send ko na lang sa''yo yung file after lunch.","translation":"Okay, I''ll just send you the file after lunch.","chunks":[{"tagalog":"Sige, i-send ko","english":"okay, I''ll send","note":"I- + English verb, with a hyphen, makes a Tagalog verb: i-send."},{"tagalog":"na lang sa''yo","english":"to you instead","note":"Sa''yo is the spoken short form of ''sa iyo''."},{"tagalog":"yung file after lunch.","english":"the file after lunch.","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Sige,","english":"okay"},{"token":"i-send","english":"send (will)"},{"token":"ko","english":"I / my"},{"token":"na","english":"already / now"},{"token":"lang","english":"just / only"},{"token":"sa''yo","english":"to you"},{"token":"yung","english":"the / the one"},{"token":"file","english":"file"},{"token":"after","english":"after"},{"token":"lunch.","english":"lunch"}],"speakingPrompt":"Promise to send him the file after lunch."},{"topicKey":"roadmap_intermediate_08_work_celebrations_fixes","situation":"It''s almost noon. Suggest eating together.","tagalog":"Tara, sabay na tayong mag-lunch mamaya!","translation":"Come on, let''s have lunch together later!","chunks":[{"tagalog":"Tara,","english":"come on,","note":"Tara means ''let''s go''."},{"tagalog":"sabay na tayong","english":"let''s go together","note":"Sabay means ''at the same time, together''. Tayo + -ng links to the verb."},{"tagalog":"mag-lunch mamaya!","english":"have lunch later!","note":"Mag- + English noun: ''to have lunch''."}],"wordGlosses":[{"token":"Tara,","english":"come on / let''s go"},{"token":"sabay","english":"together"},{"token":"na","english":"already / now"},{"token":"tayong","english":"we (linked, incl. you)"},{"token":"mag-lunch","english":"have lunch"},{"token":"mamaya!","english":"later today"}],"speakingPrompt":"Invite him to eat lunch with you.","responseExercise":{"promptTagalog":"Tara, sabay na tayong mag-lunch mamaya!","promptTranslation":"Come on, let''s have lunch together later!","options":[{"englishTranslation":"Hey, good morning! How was your weekend?"},{"englishTranslation":"Come on, let''s have lunch together later!"},{"englishTranslation":"Wow, I have so many deadlines this week."}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Uy, good morning","english":"hey, good morning!","example":"Uy, good morning! Kumusta yung weekend mo?","exampleTranslation":"Hey, good morning! How was your weekend?"},{"tagalog":"Kumusta yung weekend mo","english":"how was your weekend?","example":"Uy, good morning! Kumusta yung weekend mo?","exampleTranslation":"Hey, good morning! How was your weekend?"},{"tagalog":"Grabe","english":"wow,","example":"Grabe, ang dami kong deadlines this week.","exampleTranslation":"Wow, I have so many deadlines this week."},{"tagalog":"ang dami kong deadlines","english":"I have so many deadlines","example":"Grabe, ang dami kong deadlines this week.","exampleTranslation":"Wow, I have so many deadlines this week."},{"tagalog":"this week","english":"this week.","example":"Grabe, ang dami kong deadlines this week.","exampleTranslation":"Wow, I have so many deadlines this week."},{"tagalog":"May meeting pa tayo","english":"we still have a meeting","example":"May meeting pa tayo mamayang alas-dos, di ba?","exampleTranslation":"We still have a meeting at two later, right?"},{"tagalog":"mamayang alas-dos","english":"at two later,","example":"May meeting pa tayo mamayang alas-dos, di ba?","exampleTranslation":"We still have a meeting at two later, right?"},{"tagalog":"di ba","english":"right?","example":"May meeting pa tayo mamayang alas-dos, di ba?","exampleTranslation":"We still have a meeting at two later, right?"},{"tagalog":"Sige, i-send ko","english":"okay, I''ll send","example":"Sige, i-send ko na lang sa''yo yung file after lunch.","exampleTranslation":"Okay, I''ll just send you the file after lunch."},{"tagalog":"na lang sa''yo","english":"to you instead","example":"Sige, i-send ko na lang sa''yo yung file after lunch.","exampleTranslation":"Okay, I''ll just send you the file after lunch."}]}'::jsonb, '37364e8c8ea16690bcb10236c9537dbd7662873fc8843b2da995375da0c99f97', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
