    2.80, array['culture', 'family']::text[], 'authored_roadmap', 'native_speaker_review_required',
    '{"title":"Christmas in the Philippines","scenarioKey":"roadmap_intermediate_09_work_celebrations_fixes","scenario":"Dawn Mass, Noche Buena and greeting your godparents.","minutes":5,"difficulty":2.8,"rounds":[{"topicKey":"roadmap_intermediate_09_work_celebrations_fixes","situation":"It''s 3:30 in the morning in December. Your cousin is still half asleep on the sofa.","tagalog":"Tara na, alas-kuwatro magsisimula ang Simbang Gabi.","translation":"Come on, Simbang Gabi starts at four.","chunks":[{"tagalog":"Tara na,","english":"come on,","note":"Na adds urgency: ''let''s go now''."},{"tagalog":"alas-kuwatro magsisimula","english":"starts at four","note":"Magsisimula is the future of magsimula."},{"tagalog":"ang Simbang Gabi.","english":"Simbang Gabi.","note":"The dawn Masses held for nine days before Christmas."}],"wordGlosses":[{"token":"Tara","english":"come on / let''s go"},{"token":"na,","english":"already / now"},{"token":"alas-kuwatro","english":"four o''clock"},{"token":"magsisimula","english":"will start"},{"token":"ang","english":"the (focus marker)"},{"token":"Simbang","english":"Mass of (Simbang)"},{"token":"Gabi.","english":"night / evening"}],"speakingPrompt":"Hurry your cousin along to the dawn Mass."},{"topicKey":"roadmap_intermediate_09_work_celebrations_fixes","situation":"Mass is ending. You can already smell the food stalls outside the church.","tagalog":"Bili tayo ng bibingka at puto bumbong paglabas natin.","translation":"Let''s buy bibingka and puto bumbong when we get out.","chunks":[{"tagalog":"Bili tayo","english":"let''s buy","note":"Bare root + tayo is a casual ''let''s'': bili tayo."},{"tagalog":"ng bibingka at puto bumbong","english":"bibingka and puto bumbong","note":"Two Christmas rice cakes."},{"tagalog":"paglabas natin.","english":"when we get out.","note":"Pag- + verb root means ''when, upon''."}],"wordGlosses":[{"token":"Bili","english":"buy"},{"token":"tayo","english":"we / let''s (incl. you)"},{"token":"ng","english":"of / (object marker)"},{"token":"bibingka","english":"rice cake (baked)"},{"token":"at","english":"and"},{"token":"puto","english":"rice cake"},{"token":"bumbong","english":"bamboo-steamed (purple)"},{"token":"paglabas","english":"upon going out"},{"token":"natin.","english":"we / our (incl. you)"}],"speakingPrompt":"Suggest getting the classic rice cakes after Mass."},{"topicKey":"roadmap_intermediate_09_work_celebrations_fixes","situation":"Christmas Eve. The clock strikes midnight and the table is full.","tagalog":"Alas-dose na! Tara, mag-Noche Buena na tayo.","translation":"It''s midnight! Come on, let''s have Noche Buena.","chunks":[{"tagalog":"Alas-dose na!","english":"it''s twelve o''clock!","note":"Start the thought with this reusable chunk."},{"tagalog":"Tara,","english":"come on,","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"mag-Noche Buena na tayo.","english":"let''s have Noche Buena.","note":"Mag- turns an event into a verb: ''to do Noche Buena''."}],"wordGlosses":[{"token":"Alas-dose","english":"twelve o''clock"},{"token":"na!","english":"already / now"},{"token":"Tara,","english":"come on / let''s go"},{"token":"mag-Noche","english":"have Noche (Christmas Eve)"},{"token":"Buena","english":"Buena (Christmas Eve feast)"},{"token":"na","english":"already / now"},{"token":"tayo.","english":"we / let''s (incl. you)"}],"speakingPrompt":"Announce it''s midnight and call everyone to eat.","responseExercise":{"promptTagalog":"Alas-dose na! Tara, mag-Noche Buena na tayo.","promptTranslation":"It''s midnight! Come on, let''s have Noche Buena.","options":[{"englishTranslation":"Merry Christmas, Ninong! Your blessing, please."},{"englishTranslation":"It''s midnight! Come on, let''s have Noche Buena."},{"englishTranslation":"Oh, you didn''t have to. Thank you, Ninang!"}],"correctOptionIndex":1}},{"topicKey":"roadmap_intermediate_09_work_celebrations_fixes","situation":"On Christmas Day your godfather arrives. You take his hand and press it to your forehead.","tagalog":"Maligayang Pasko po, Ninong! Mano po.","translation":"Merry Christmas, Ninong! Your blessing, please.","chunks":[{"tagalog":"Maligayang Pasko po,","english":"Merry Christmas,","note":"Start the thought with this reusable chunk."},{"tagalog":"Ninong!","english":"Godfather!","note":"Ninong and ninang are your godparents."},{"tagalog":"Mano po.","english":"your blessing, please.","note":"Say it as you press an elder''s hand to your forehead."}],"wordGlosses":[{"token":"Maligayang","english":"merry / happy"},{"token":"Pasko","english":"Christmas"},{"token":"po,","english":"(respect marker)"},{"token":"Ninong!","english":"godfather"},{"token":"Mano","english":"blessing (hand to forehead)"},{"token":"po.","english":"(respect marker)"}],"speakingPrompt":"Greet your godfather and ask for his blessing."},{"topicKey":"roadmap_intermediate_09_work_celebrations_fixes","situation":"Your godmother hands you an envelope with a gift inside.","tagalog":"Naku, nag-abala pa po kayo. Salamat po, Ninang!","translation":"Oh, you didn''t have to. Thank you, Ninang!","chunks":[{"tagalog":"Naku,","english":"oh,","note":"Start the thought with this reusable chunk."},{"tagalog":"nag-abala pa po kayo.","english":"you went to the trouble.","note":"The polite way to receive a gift: ''you shouldn''t have''."},{"tagalog":"Salamat po, Ninang!","english":"thank you, Godmother!","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Naku,","english":"oh no / oh"},{"token":"nag-abala","english":"went to the trouble"},{"token":"pa","english":"still / more"},{"token":"po","english":"(respect marker)"},{"token":"kayo.","english":"you (respectful)"},{"token":"Salamat","english":"thank you"},{"token":"po,","english":"(respect marker)"},{"token":"Ninang!","english":"godmother"}],"speakingPrompt":"Thank your godmother warmly for the gift.","responseExercise":{"promptTagalog":"Naku, nag-abala pa po kayo. Salamat po, Ninang!","promptTranslation":"Oh, you didn''t have to. Thank you, Ninang!","options":[{"englishTranslation":"Come on, Simbang Gabi starts at four."},{"englishTranslation":"Oh, you didn''t have to. Thank you, Ninang!"},{"englishTranslation":"Let''s buy bibingka and puto bumbong when we get out."}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Tara na","english":"come on,","example":"Tara na, alas-kuwatro magsisimula ang Simbang Gabi.","exampleTranslation":"Come on, Simbang Gabi starts at four."},{"tagalog":"alas-kuwatro magsisimula","english":"starts at four","example":"Tara na, alas-kuwatro magsisimula ang Simbang Gabi.","exampleTranslation":"Come on, Simbang Gabi starts at four."},{"tagalog":"ang Simbang Gabi","english":"Simbang Gabi.","example":"Tara na, alas-kuwatro magsisimula ang Simbang Gabi.","exampleTranslation":"Come on, Simbang Gabi starts at four."},{"tagalog":"Bili tayo","english":"let''s buy","example":"Bili tayo ng bibingka at puto bumbong paglabas natin.","exampleTranslation":"Let''s buy bibingka and puto bumbong when we get out."},{"tagalog":"ng bibingka at puto bumbong","english":"bibingka and puto bumbong","example":"Bili tayo ng bibingka at puto bumbong paglabas natin.","exampleTranslation":"Let''s buy bibingka and puto bumbong when we get out."},{"tagalog":"paglabas natin","english":"when we get out.","example":"Bili tayo ng bibingka at puto bumbong paglabas natin.","exampleTranslation":"Let''s buy bibingka and puto bumbong when we get out."},{"tagalog":"Alas-dose na","english":"it''s twelve o''clock!","example":"Alas-dose na! Tara, mag-Noche Buena na tayo.","exampleTranslation":"It''s midnight! Come on, let''s have Noche Buena."},{"tagalog":"Tara","english":"come on,","example":"Alas-dose na! Tara, mag-Noche Buena na tayo.","exampleTranslation":"It''s midnight! Come on, let''s have Noche Buena."},{"tagalog":"mag-Noche Buena na tayo","english":"let''s have Noche Buena.","example":"Alas-dose na! Tara, mag-Noche Buena na tayo.","exampleTranslation":"It''s midnight! Come on, let''s have Noche Buena."},{"tagalog":"Maligayang Pasko po","english":"Merry Christmas,","example":"Maligayang Pasko po, Ninong! Mano po.","exampleTranslation":"Merry Christmas, Ninong! Your blessing, please."}]}'::jsonb, 'c43733f17146c1acd4f05beeb45d9a6bef6897199b0637c43483a981b96383eb', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
  ),
(
    '43020000-0000-4000-8100-000000000010'::uuid,
    'intermediate-10-wrong-order-at-the-restaurant', 'Wrong order at the restaurant', 'Sort out a mix-up politely but firmly.',
    'intermediate', 5, 10, false, 1,
    'intermediate-v1', 'work-celebrations-fixes', 'Work, celebrations and fixes',
    3, 10, 3, 14,
    2.90, array['lifeInThePhilippines', 'travel']::text[], 'authored_roadmap', 'native_speaker_review_required',
    '{"title":"Wrong order at the restaurant","scenarioKey":"roadmap_intermediate_10_work_celebrations_fixes","scenario":"Sort out a mix-up politely but firmly.","minutes":5,"difficulty":2.9,"rounds":[{"topicKey":"roadmap_intermediate_10_work_celebrations_fixes","situation":"The waiter puts a bowl of soup in front of you. It''s not what you asked for.","tagalog":"Excuse me po, hindi po ito yung in-order ko.","translation":"Excuse me, this isn''t what I ordered.","chunks":[{"tagalog":"Excuse me po,","english":"excuse me,","note":"English ''excuse me'' plus po is standard with staff."},{"tagalog":"hindi po ito","english":"this isn''t","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"yung in-order ko.","english":"what I ordered.","note":"In- + English verb with a hyphen: ''in-order'' means ''ordered''."}],"wordGlosses":[{"token":"Excuse","english":"excuse"},{"token":"me","english":"me"},{"token":"po,","english":"(respect marker)"},{"token":"hindi","english":"not"},{"token":"po","english":"(respect marker)"},{"token":"ito","english":"this"},{"token":"yung","english":"the / the one"},{"token":"in-order","english":"ordered"},{"token":"ko.","english":"I / my"}],"speakingPrompt":"Get the waiter''s attention and say it''s the wrong dish."},{"topicKey":"roadmap_intermediate_10_work_celebrations_fixes","situation":"The waiter looks confused and checks his notepad.","tagalog":"Sinigang na baboy po ang in-order ko, hindi sinigang na hipon.","translation":"I ordered pork sinigang, not shrimp sinigang.","chunks":[{"tagalog":"Sinigang na baboy po","english":"pork sinigang","note":"Na links the dish to its main ingredient."},{"tagalog":"ang in-order ko,","english":"is what I ordered,","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"hindi sinigang na hipon.","english":"not shrimp sinigang.","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Sinigang","english":"sour tamarind soup"},{"token":"na","english":"already / now"},{"token":"baboy","english":"pork"},{"token":"po","english":"(respect marker)"},{"token":"ang","english":"the (focus marker)"},{"token":"in-order","english":"ordered"},{"token":"ko,","english":"I / my"},{"token":"hindi","english":"not"},{"token":"sinigang","english":"sour tamarind soup"},{"token":"na","english":"already / now"},{"token":"hipon.","english":"shrimp"}],"speakingPrompt":"Explain which dish you ordered and which one you got."},{"topicKey":"roadmap_intermediate_10_work_celebrations_fixes","situation":"Your friends have already finished eating. Make it clear this has taken too long.","tagalog":"Kalahating oras na po kaming naghihintay.","translation":"We''ve already been waiting for half an hour.","chunks":[{"tagalog":"Kalahating oras na po","english":"half an hour already","note":"Kalahati + -ng: ''half an hour''."},{"tagalog":"kaming naghihintay.","english":"we''ve been waiting.","note":"Naghihintay is the ongoing form: the wait is still going on."}],"wordGlosses":[{"token":"Kalahating","english":"half (an)"},{"token":"oras","english":"time / hour"},{"token":"na","english":"already / now"},{"token":"po","english":"(respect marker)"},{"token":"kaming","english":"we (linked)"},{"token":"naghihintay.","english":"are waiting"}],"speakingPrompt":"Say firmly how long you''ve been waiting.","responseExercise":{"promptTagalog":"Kalahating oras na po kaming naghihintay.","promptTranslation":"We''ve already been waiting for half an hour.","options":[{"englishTranslation":"Can you replace it right away? I''m allergic to shrimp."},{"englishTranslation":"We''ve already been waiting for half an hour."},{"englishTranslation":"Please just remove the shrimp from the bill. Thank you."}],"correctOptionIndex":1}},{"topicKey":"roadmap_intermediate_10_work_celebrations_fixes","situation":"The waiter offers to fix it. Shrimp is a real problem for you.","tagalog":"Pwede po bang palitan ninyo agad? May allergy po ako sa hipon.","translation":"Can you replace it right away? I''m allergic to shrimp.","chunks":[{"tagalog":"Pwede po bang","english":"could you","note":"Start the thought with this reusable chunk."},{"tagalog":"palitan ninyo agad?","english":"replace it right away?","note":"Agad means ''immediately''."},{"tagalog":"May allergy po ako","english":"I have an allergy","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"sa hipon.","english":"to shrimp.","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Pwede","english":"can / may"},{"token":"po","english":"(respect marker)"},{"token":"bang","english":"(question marker + linker)"},{"token":"palitan","english":"replace"},{"token":"ninyo","english":"you / your (respectful)"},{"token":"agad?","english":"right away"},{"token":"May","english":"there is / have"},{"token":"allergy","english":"allergy"},{"token":"po","english":"(respect marker)"},{"token":"ako","english":"I"},{"token":"sa","english":"in / at / to"},{"token":"hipon.","english":"shrimp"}],"speakingPrompt":"Ask for a quick replacement and explain your allergy."},{"topicKey":"roadmap_intermediate_10_work_celebrations_fixes","situation":"The right dish finally arrives. When the bill comes, the shrimp soup is still on it.","tagalog":"Pakitanggal na lang po yung hipon sa bill. Salamat po.","translation":"Please just remove the shrimp from the bill. Thank you.","chunks":[{"tagalog":"Pakitanggal na lang po","english":"please just remove","note":"Paki- + verb is a polite ''please'': pakitanggal."},{"tagalog":"yung hipon sa bill.","english":"the shrimp from the bill.","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"Salamat po.","english":"thank you.","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Pakitanggal","english":"please remove"},{"token":"na","english":"already / now"},{"token":"lang","english":"just / only"},{"token":"po","english":"(respect marker)"},{"token":"yung","english":"the / the one"},{"token":"hipon","english":"shrimp"},{"token":"sa","english":"in / at / to"},{"token":"bill.","english":"bill"},{"token":"Salamat","english":"thank you"},{"token":"po.","english":"(respect marker)"}],"speakingPrompt":"Ask firmly but politely for the wrong dish to be taken off the bill.","responseExercise":{"promptTagalog":"Pakitanggal na lang po yung hipon sa bill. Salamat po.","promptTranslation":"Please just remove the shrimp from the bill. Thank you.","options":[{"englishTranslation":"Excuse me, this isn''t what I ordered."},{"englishTranslation":"Please just remove the shrimp from the bill. Thank you."},{"englishTranslation":"I ordered pork sinigang, not shrimp sinigang."}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Excuse me po","english":"excuse me,","example":"Excuse me po, hindi po ito yung in-order ko.","exampleTranslation":"Excuse me, this isn''t what I ordered."},{"tagalog":"hindi po ito","english":"this isn''t","example":"Excuse me po, hindi po ito yung in-order ko.","exampleTranslation":"Excuse me, this isn''t what I ordered."},{"tagalog":"yung in-order ko","english":"what I ordered.","example":"Excuse me po, hindi po ito yung in-order ko.","exampleTranslation":"Excuse me, this isn''t what I ordered."},{"tagalog":"Sinigang na baboy po","english":"pork sinigang","example":"Sinigang na baboy po ang in-order ko, hindi sinigang na hipon.","exampleTranslation":"I ordered pork sinigang, not shrimp sinigang."},{"tagalog":"ang in-order ko","english":"is what I ordered,","example":"Sinigang na baboy po ang in-order ko, hindi sinigang na hipon.","exampleTranslation":"I ordered pork sinigang, not shrimp sinigang."},{"tagalog":"hindi sinigang na hipon","english":"not shrimp sinigang.","example":"Sinigang na baboy po ang in-order ko, hindi sinigang na hipon.","exampleTranslation":"I ordered pork sinigang, not shrimp sinigang."},{"tagalog":"Kalahating oras na po","english":"half an hour already","example":"Kalahating oras na po kaming naghihintay.","exampleTranslation":"We''ve already been waiting for half an hour."},{"tagalog":"kaming naghihintay","english":"we''ve been waiting.","example":"Kalahating oras na po kaming naghihintay.","exampleTranslation":"We''ve already been waiting for half an hour."},{"tagalog":"Pwede po bang","english":"could you","example":"Pwede po bang palitan ninyo agad? May allergy po ako sa hipon.","exampleTranslation":"Can you replace it right away? I''m allergic to shrimp."},{"tagalog":"palitan ninyo agad","english":"replace it right away?","example":"Pwede po bang palitan ninyo agad? May allergy po ako sa hipon.","exampleTranslation":"Can you replace it right away? I''m allergic to shrimp."}]}'::jsonb, '82ebe67afc05626d3ca32b37ef9a5935a3d8470b66bbbe163c4750b340496baa', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
