(
    '43030000-0000-4000-8100-000000000004'::uuid,
    'advanced-04-hay-naku-sayang-bahala-na-everyday-expressions', 'Hay naku, sayang, bahala na: everyday expressions', 'Miss the last bus with a friend and react like a true local.',
    'advanced', 5, 4, false, 1,
    'advanced-v1', 'sound-like-a-local', 'Sound like a local',
    2, 4, 3, 14,
    3.20, array['lifeInThePhilippines', 'travel', 'culture']::text[], 'authored_roadmap', 'native_speaker_review_required',
    '{"title":"Hay naku, sayang, bahala na: everyday expressions","scenarioKey":"roadmap_advanced_04_sound_like_a_local","scenario":"Miss the last bus with a friend and react like a true local.","minutes":5,"difficulty":3.2,"rounds":[{"topicKey":"roadmap_advanced_04_sound_like_a_local","situation":"You and your friend Migs run into the Cubao bus terminal, sweaty after an hour stuck on the highway.","tagalog":"Hay naku, ang traffic sa EDSA! Umalis na ''yung huling bus papuntang Baguio.","translation":"Oh man, the traffic on EDSA! The last bus to Baguio already left.","chunks":[{"tagalog":"Hay naku,","english":"oh, good grief","note":"Hay naku is the all-purpose sigh of exasperation."},{"tagalog":"ang traffic sa EDSA!","english":"the traffic on EDSA!","note":"Ang + noun works as an exclamation: ''such traffic!''."},{"tagalog":"Umalis na ''yung huling bus papuntang Baguio.","english":"the last bus to Baguio already left","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Hay naku,","english":"oh, good grief"},{"token":"ang","english":"the (topic marker)"},{"token":"traffic","english":"traffic"},{"token":"sa","english":"in, at, to, on"},{"token":"EDSA!","english":"EDSA (Manila''s main highway)"},{"token":"Umalis","english":"left (completed)"},{"token":"na","english":"already / now / that (linker)"},{"token":"''yung","english":"the, that (short for iyong)"},{"token":"huling","english":"last (+ linker)"},{"token":"bus","english":"bus"},{"token":"papuntang","english":"going to, bound for"},{"token":"Baguio.","english":"Baguio"}],"speakingPrompt":"Sigh about the traffic and break the news that the last bus is gone."},{"topicKey":"roadmap_advanced_04_sound_like_a_local","situation":"Migs waves the two printed tickets you bought online. Now they''re useless.","tagalog":"Sayang ''yung ticket natin, binayaran pa naman natin nang buo kahapon!","translation":"What a waste of our tickets, and we even paid for them in full yesterday!","chunks":[{"tagalog":"Sayang ''yung ticket natin,","english":"what a waste, our tickets","note":"Sayang = ''what a waste, too bad'': hard to translate, used constantly."},{"tagalog":"binayaran pa naman natin","english":"and to think we even paid for them","note":"Pa naman adds ''and to think we even ...''."},{"tagalog":"nang buo kahapon!","english":"in full yesterday!","note":"Nang (not ng) introduces how something was done."}],"wordGlosses":[{"token":"Sayang","english":"what a waste, too bad"},{"token":"''yung","english":"the, that (short for iyong)"},{"token":"ticket","english":"ticket"},{"token":"natin,","english":"our / let''s (including you)"},{"token":"binayaran","english":"paid for (completed)"},{"token":"pa naman","english":"and to think (we even)"},{"token":"natin","english":"our / let''s (including you)"},{"token":"nang","english":"(adverb marker) / for"},{"token":"buo","english":"whole, in full"},{"token":"kahapon!","english":"yesterday"}],"speakingPrompt":"Lament the wasted tickets and point out you''d already paid in full."},{"topicKey":"roadmap_advanced_04_sound_like_a_local","situation":"There''s a provincial bus leaving in ten minutes, with no guarantee of seats. Make the call.","tagalog":"Sige, bahala na! Sakay na lang tayo ng kahit anong bus, basta makarating tayo bago mag-alas dose.","translation":"Okay, come what may! Let''s just take any bus, as long as we get there before twelve.","chunks":[{"tagalog":"Sige, bahala na!","english":"okay, come what may!","note":"Bahala na = ''leave it to fate'': part courage, part shrug."},{"tagalog":"Sakay na lang tayo ng kahit anong bus,","english":"let''s just ride any bus","note":"Na lang = ''just, instead'', for a fallback plan."},{"tagalog":"basta makarating tayo bago mag-alas dose.","english":"as long as we get there before twelve","note":"Clock times use Spanish numbers: alas dose = twelve o''clock."}],"wordGlosses":[{"token":"Sige,","english":"okay, sure"},{"token":"bahala na!","english":"come what may"},{"token":"Sakay","english":"ride, get on"},{"token":"na lang","english":"just, instead"},{"token":"tayo","english":"we, us (including you)"},{"token":"ng","english":"of / a (marker)"},{"token":"kahit","english":"even, no matter"},{"token":"anong","english":"what (+ linker), any"},{"token":"bus,","english":"bus"},{"token":"basta","english":"as long as"},{"token":"makarating","english":"to get there, arrive"},{"token":"tayo","english":"we, us (including you)"},{"token":"bago","english":"before"},{"token":"mag-alas","english":"turns (o''clock)"},{"token":"dose.","english":"twelve (o''clock)"}],"speakingPrompt":"Decide to risk it: take any bus, as long as you arrive before midnight.","responseExercise":{"promptTagalog":"Sige, bahala na! Sakay na lang tayo ng kahit anong bus, basta makarating tayo bago mag-alas dose.","promptTranslation":"Okay, come what may! Let''s just take any bus, as long as we get there before twelve.","options":[{"englishTranslation":"You got two seats at the front? Your street smarts are something else, you''re the best!"},{"englishTranslation":"Okay, come what may! Let''s just take any bus, as long as we get there before twelve."},{"englishTranslation":"Your snacks were free too? Lucky you! Next time you''re in charge of everything, just kidding."}],"correctOptionIndex":1}},{"topicKey":"roadmap_advanced_04_sound_like_a_local","situation":"Somehow Migs talks to the conductor and gets you two seats right behind the driver.","tagalog":"Nakakuha ka ng dalawang upuan sa harap? Iba talaga ang diskarte mo, ikaw na!","translation":"You got two seats at the front? Your street smarts are something else, you''re the best!","chunks":[{"tagalog":"Nakakuha ka ng dalawang upuan sa harap?","english":"you got two seats up front?","note":"Nakakuha = managed to get."},{"tagalog":"Iba talaga ang diskarte mo,","english":"your hustle is really something else","note":"Diskarte = street-smart resourcefulness, a real compliment."},{"tagalog":"ikaw na!","english":"you''re the best!","note":"Ikaw na! means ''you win'': half praise, half teasing."}],"wordGlosses":[{"token":"Nakakuha","english":"managed to get (completed)"},{"token":"ka","english":"you (casual)"},{"token":"ng","english":"of / a (marker)"},{"token":"dalawang","english":"two (+ linker)"},{"token":"upuan","english":"seats"},{"token":"sa","english":"in, at, to, on"},{"token":"harap?","english":"front"},{"token":"Iba","english":"different, something else"},{"token":"talaga","english":"really, truly"},{"token":"ang","english":"the (topic marker)"},{"token":"diskarte","english":"street smarts, hustle"},{"token":"mo,","english":"you / your (casual)"},{"token":"ikaw","english":"you (emphatic)"},{"token":"na!","english":"already / now / that (linker)"}],"speakingPrompt":"Praise how resourceful he is, half impressed and half teasing."},{"topicKey":"roadmap_advanced_04_sound_like_a_local","situation":"The conductor even hands Migs free snacks because he was so charming. You get nothing.","tagalog":"Libre pa ''yung snacks mo? Sana all talaga! Next time, ikaw na ang bahala sa lahat, charot.","translation":"Your snacks were free too? Lucky you! Next time you''re in charge of everything, just kidding.","chunks":[{"tagalog":"Libre pa ''yung snacks mo?","english":"your snacks were free too?","note":"Libre = free of charge."},{"tagalog":"Sana all talaga!","english":"lucky you, I wish that were all of us!","note":"Sana all = ''I wish everyone got that'': playful envy that has stuck around for years."},{"tagalog":"Next time, ikaw na ang bahala sa lahat,","english":"next time, you''re in charge of everything","note":"Ikaw na ang bahala = ''it''s all up to you'': bahala again, now meaning ''in charge''."},{"tagalog":"charot.","english":"just kidding","note":"Charot (or char) tacks ''kidding!'' onto a teasing line."}],"wordGlosses":[{"token":"Libre","english":"free (of charge)"},{"token":"pa","english":"still / yet / more"},{"token":"''yung","english":"the, that (short for iyong)"},{"token":"snacks","english":"snacks"},{"token":"mo?","english":"you / your (casual)"},{"token":"Sana all","english":"lucky you (wish we all had that)"},{"token":"talaga!","english":"really, truly"},{"token":"Next time,","english":"next time"},{"token":"ikaw","english":"you (emphatic)"},{"token":"na","english":"already / now / that (linker)"},{"token":"ang","english":"the (topic marker)"},{"token":"bahala","english":"in charge, up to (someone)"},{"token":"sa","english":"in, at, to, on"},{"token":"lahat,","english":"all, everyone, everything"},{"token":"charot.","english":"just kidding"}],"speakingPrompt":"Tease him about his luck, put him in charge of the next trip, then say you''re kidding.","responseExercise":{"promptTagalog":"Libre pa ''yung snacks mo? Sana all talaga! Next time, ikaw na ang bahala sa lahat, charot.","promptTranslation":"Your snacks were free too? Lucky you! Next time you''re in charge of everything, just kidding.","options":[{"englishTranslation":"Oh man, the traffic on EDSA! The last bus to Baguio already left."},{"englishTranslation":"Your snacks were free too? Lucky you! Next time you''re in charge of everything, just kidding."},{"englishTranslation":"What a waste of our tickets, and we even paid for them in full yesterday!"}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Hay naku","english":"oh, good grief","example":"Hay naku, ang traffic sa EDSA! Umalis na ''yung huling bus papuntang Baguio.","exampleTranslation":"Oh man, the traffic on EDSA! The last bus to Baguio already left."},{"tagalog":"ang traffic sa EDSA","english":"the traffic on EDSA!","example":"Hay naku, ang traffic sa EDSA! Umalis na ''yung huling bus papuntang Baguio.","exampleTranslation":"Oh man, the traffic on EDSA! The last bus to Baguio already left."},{"tagalog":"Umalis na ''yung huling bus papuntang Baguio","english":"the last bus to Baguio already left","example":"Hay naku, ang traffic sa EDSA! Umalis na ''yung huling bus papuntang Baguio.","exampleTranslation":"Oh man, the traffic on EDSA! The last bus to Baguio already left."},{"tagalog":"Sayang ''yung ticket natin","english":"what a waste, our tickets","example":"Sayang ''yung ticket natin, binayaran pa naman natin nang buo kahapon!","exampleTranslation":"What a waste of our tickets, and we even paid for them in full yesterday!"},{"tagalog":"binayaran pa naman natin","english":"and to think we even paid for them","example":"Sayang ''yung ticket natin, binayaran pa naman natin nang buo kahapon!","exampleTranslation":"What a waste of our tickets, and we even paid for them in full yesterday!"},{"tagalog":"nang buo kahapon","english":"in full yesterday!","example":"Sayang ''yung ticket natin, binayaran pa naman natin nang buo kahapon!","exampleTranslation":"What a waste of our tickets, and we even paid for them in full yesterday!"},{"tagalog":"Sige, bahala na","english":"okay, come what may!","example":"Sige, bahala na! Sakay na lang tayo ng kahit anong bus, basta makarating tayo bago mag-alas dose.","exampleTranslation":"Okay, come what may! Let''s just take any bus, as long as we get there before twelve."},{"tagalog":"Sakay na lang tayo ng kahit anong bus","english":"let''s just ride any bus","example":"Sige, bahala na! Sakay na lang tayo ng kahit anong bus, basta makarating tayo bago mag-alas dose.","exampleTranslation":"Okay, come what may! Let''s just take any bus, as long as we get there before twelve."},{"tagalog":"basta makarating tayo bago mag-alas dose","english":"as long as we get there before twelve","example":"Sige, bahala na! Sakay na lang tayo ng kahit anong bus, basta makarating tayo bago mag-alas dose.","exampleTranslation":"Okay, come what may! Let''s just take any bus, as long as we get there before twelve."},{"tagalog":"Nakakuha ka ng dalawang upuan sa harap","english":"you got two seats up front?","example":"Nakakuha ka ng dalawang upuan sa harap? Iba talaga ang diskarte mo, ikaw na!","exampleTranslation":"You got two seats at the front? Your street smarts are something else, you''re the best!"}]}'::jsonb, '6b9ea1bed1f8966dc34f099689dd83b8b684a9ecb7d87799e9e71af3dafe46b9', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
  ),
(
    '43030000-0000-4000-8100-000000000005'::uuid,
    'advanced-05-lola-s-adobo-step-by-step', 'Lola''s adobo, step by step', 'Learn the family adobo recipe from Lola in her own kitchen.',
    'advanced', 5, 5, false, 1,
