    3.25, array['family', 'culture']::text[], 'authored_roadmap', 'native_speaker_review_required',
    '{"title":"Lola''s adobo, step by step","scenarioKey":"roadmap_advanced_05_sound_like_a_local","scenario":"Learn the family adobo recipe from Lola in her own kitchen.","minutes":5,"difficulty":3.25,"rounds":[{"topicKey":"roadmap_advanced_05_sound_like_a_local","situation":"It''s Sunday at your grandmother''s house. Lola is tying on her apron in the kitchen.","tagalog":"Lola, turuan n''yo naman po ako ng adobo ninyo, ''yung sikat sa buong pamilya.","translation":"Lola, please teach me your adobo, the one the whole family loves.","chunks":[{"tagalog":"Lola, turuan n''yo naman po ako","english":"Lola, please teach me","note":"Naman po turns a request into a sweet plea; n''yo is short for ninyo."},{"tagalog":"ng adobo ninyo,","english":"your adobo","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"''yung sikat sa buong pamilya.","english":"the one famous in the whole family","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Lola,","english":"grandma (Lola)"},{"token":"turuan","english":"teach"},{"token":"n''yo","english":"you (short for ninyo)"},{"token":"naman","english":"(softener) after all"},{"token":"po","english":"(respect marker)"},{"token":"ako","english":"I"},{"token":"ng","english":"of / a (marker)"},{"token":"adobo","english":"adobo"},{"token":"ninyo,","english":"your / by you (respectful / plural)"},{"token":"''yung","english":"the, that (short for iyong)"},{"token":"sikat","english":"famous"},{"token":"sa","english":"in, at, to, on"},{"token":"buong","english":"whole, entire (+ linker)"},{"token":"pamilya.","english":"family"}],"speakingPrompt":"Sweetly ask your grandmother to teach you her famous adobo."},{"topicKey":"roadmap_advanced_05_sound_like_a_local","situation":"Lola puts the chicken in a bowl and starts adding things. Check the first step with her.","tagalog":"Una po, ibababad muna ang manok sa toyo, suka at bawang nang mga isang oras, tama po ba?","translation":"First, you marinate the chicken in soy sauce, vinegar and garlic for about an hour, right?","chunks":[{"tagalog":"Una po, ibababad muna ang manok","english":"first, the chicken gets marinated","note":"Ibababad = will be soaked (future, object focus)."},{"tagalog":"sa toyo, suka at bawang","english":"in soy sauce, vinegar and garlic","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"nang mga isang oras,","english":"for about an hour","note":"Mga before a number means ''about''."},{"tagalog":"tama po ba?","english":"is that right?","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Una","english":"first"},{"token":"po,","english":"(respect marker)"},{"token":"ibababad","english":"will be soaked, marinated (future)"},{"token":"muna","english":"first, for now"},{"token":"ang","english":"the (topic marker)"},{"token":"manok","english":"chicken"},{"token":"sa","english":"in, at, to, on"},{"token":"toyo,","english":"soy sauce"},{"token":"suka","english":"vinegar"},{"token":"at","english":"and"},{"token":"bawang","english":"garlic"},{"token":"nang","english":"(adverb marker) / for"},{"token":"mga","english":"(plural marker) / about"},{"token":"isang","english":"one, a"},{"token":"oras,","english":"time, hour"},{"token":"tama","english":"right, correct"},{"token":"po","english":"(respect marker)"},{"token":"ba?","english":"(question marker)"}],"speakingPrompt":"Repeat the marinade step back to her and check you''ve got it right."},{"topicKey":"roadmap_advanced_05_sound_like_a_local","situation":"Lola slaps your hand away from the spoon. The vinegar has to boil before anyone stirs.","tagalog":"Ah, kaya pala hindi muna hinahalo pagkabuhos ng suka, para hindi lumabas na hilaw ang lasa.","translation":"Oh, so that''s why you don''t stir right after pouring in the vinegar, so it doesn''t taste raw.","chunks":[{"tagalog":"Ah, kaya pala","english":"oh, so that''s why","note":"Kaya pala is the ''aha, now I get it'' phrase."},{"tagalog":"hindi muna hinahalo pagkabuhos ng suka,","english":"you don''t stir yet once the vinegar is in","note":"Pagka- + root = ''right after ...''."},{"tagalog":"para hindi lumabas na hilaw ang lasa.","english":"so the taste doesn''t come out raw","note":"Kitchen lore: let the vinegar boil off before stirring."}],"wordGlosses":[{"token":"Ah,","english":"ah, oh"},{"token":"kaya pala","english":"so that''s why"},{"token":"hindi","english":"not"},{"token":"muna","english":"first, for now"},{"token":"hinahalo","english":"stirred (ongoing / habitual)"},{"token":"pagkabuhos","english":"right after pouring"},{"token":"ng","english":"of / a (marker)"},{"token":"suka,","english":"vinegar"},{"token":"para","english":"for / so that"},{"token":"hindi","english":"not"},{"token":"lumabas","english":"to come out"},{"token":"na","english":"already / now / that (linker)"},{"token":"hilaw","english":"raw"},{"token":"ang","english":"the (topic marker)"},{"token":"lasa.","english":"taste"}],"speakingPrompt":"Show you''ve understood why she won''t let you stir yet.","responseExercise":{"promptTagalog":"Ah, kaya pala hindi muna hinahalo pagkabuhos ng suka, para hindi lumabas na hilaw ang lasa.","promptTranslation":"Oh, so that''s why you don''t stir right after pouring in the vinegar, so it doesn''t taste raw.","options":[{"englishTranslation":"What''s your secret, Lola? Do you add a little sugar, or just bay leaf?"},{"englishTranslation":"Oh, so that''s why you don''t stir right after pouring in the vinegar, so it doesn''t taste raw."},{"englishTranslation":"It''s delicious! No matter how many times I copy it, Lola''s cooking is still something else."}],"correctOptionIndex":1}},{"topicKey":"roadmap_advanced_05_sound_like_a_local","situation":"Lola winks and says there''s one more thing that makes hers special. Ask about it.","tagalog":"Ano po ''yung sikreto ninyo, Lola? Nilalagyan n''yo po ba ng konting asukal, o laurel lang?","translation":"What''s your secret, Lola? Do you add a little sugar, or just bay leaf?","chunks":[{"tagalog":"Ano po ''yung sikreto ninyo, Lola?","english":"what''s your secret, Lola?","note":"Start the thought with this reusable chunk."},{"tagalog":"Nilalagyan n''yo po ba ng konting asukal,","english":"do you put in a little sugar","note":"Nilalagyan = put something into (habitual, location focus)."},{"tagalog":"o laurel lang?","english":"or just bay leaf?","note":"Laurel = bay leaf, from Spanish."}],"wordGlosses":[{"token":"Ano","english":"what"},{"token":"po","english":"(respect marker)"},{"token":"''yung","english":"the, that (short for iyong)"},{"token":"sikreto","english":"secret"},{"token":"ninyo,","english":"your / by you (respectful / plural)"},{"token":"Lola?","english":"grandma (Lola)"},{"token":"Nilalagyan","english":"put in (habitual)"},{"token":"n''yo","english":"you (short for ninyo)"},{"token":"po","english":"(respect marker)"},{"token":"ba","english":"(question marker)"},{"token":"ng","english":"of / a (marker)"},{"token":"konting","english":"a little (+ linker)"},{"token":"asukal,","english":"sugar"},{"token":"o","english":"or"},{"token":"laurel","english":"bay leaf"},{"token":"lang?","english":"only, just"}],"speakingPrompt":"Ask what her secret is, guessing between sugar and bay leaf."},{"topicKey":"roadmap_advanced_05_sound_like_a_local","situation":"The adobo is done. Lola hands you a spoonful over rice and waits for your verdict.","tagalog":"Ang sarap po! Kahit ilang beses ko pang gayahin, iba pa rin talaga ang luto ni Lola.","translation":"It''s delicious! No matter how many times I copy it, Lola''s cooking is still something else.","chunks":[{"tagalog":"Ang sarap po!","english":"so delicious!","note":"Start the thought with this reusable chunk."},{"tagalog":"Kahit ilang beses ko pang gayahin,","english":"no matter how many times I copy it","note":"Kahit ilang beses = ''no matter how many times''."},{"tagalog":"iba pa rin talaga ang luto ni Lola.","english":"Lola''s cooking is still something else","note":"Calling her ''Lola'' in the third person, to her face, is affectionate."}],"wordGlosses":[{"token":"Ang sarap","english":"so delicious"},{"token":"po!","english":"(respect marker)"},{"token":"Kahit","english":"even, no matter"},{"token":"ilang","english":"how many"},{"token":"beses","english":"times"},{"token":"ko","english":"I / my"},{"token":"pang","english":"more, still (+ linker)"},{"token":"gayahin,","english":"copy, imitate"},{"token":"iba","english":"different, something else"},{"token":"pa","english":"still / yet / more"},{"token":"rin","english":"too, also"},{"token":"talaga","english":"really, truly"},{"token":"ang","english":"the (topic marker)"},{"token":"luto","english":"cooking"},{"token":"ni","english":"of / by (name marker)"},{"token":"Lola.","english":"grandma (Lola)"}],"speakingPrompt":"Praise the taste and say your version will never match hers.","responseExercise":{"promptTagalog":"Ang sarap po! Kahit ilang beses ko pang gayahin, iba pa rin talaga ang luto ni Lola.","promptTranslation":"It''s delicious! No matter how many times I copy it, Lola''s cooking is still something else.","options":[{"englishTranslation":"Lola, please teach me your adobo, the one the whole family loves."},{"englishTranslation":"It''s delicious! No matter how many times I copy it, Lola''s cooking is still something else."},{"englishTranslation":"First, you marinate the chicken in soy sauce, vinegar and garlic for about an hour, right?"}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Lola, turuan n''yo naman po ako","english":"Lola, please teach me","example":"Lola, turuan n''yo naman po ako ng adobo ninyo, ''yung sikat sa buong pamilya.","exampleTranslation":"Lola, please teach me your adobo, the one the whole family loves."},{"tagalog":"ng adobo ninyo","english":"your adobo","example":"Lola, turuan n''yo naman po ako ng adobo ninyo, ''yung sikat sa buong pamilya.","exampleTranslation":"Lola, please teach me your adobo, the one the whole family loves."},{"tagalog":"''yung sikat sa buong pamilya","english":"the one famous in the whole family","example":"Lola, turuan n''yo naman po ako ng adobo ninyo, ''yung sikat sa buong pamilya.","exampleTranslation":"Lola, please teach me your adobo, the one the whole family loves."},{"tagalog":"Una po, ibababad muna ang manok","english":"first, the chicken gets marinated","example":"Una po, ibababad muna ang manok sa toyo, suka at bawang nang mga isang oras, tama po ba?","exampleTranslation":"First, you marinate the chicken in soy sauce, vinegar and garlic for about an hour, right?"},{"tagalog":"sa toyo, suka at bawang","english":"in soy sauce, vinegar and garlic","example":"Una po, ibababad muna ang manok sa toyo, suka at bawang nang mga isang oras, tama po ba?","exampleTranslation":"First, you marinate the chicken in soy sauce, vinegar and garlic for about an hour, right?"},{"tagalog":"nang mga isang oras","english":"for about an hour","example":"Una po, ibababad muna ang manok sa toyo, suka at bawang nang mga isang oras, tama po ba?","exampleTranslation":"First, you marinate the chicken in soy sauce, vinegar and garlic for about an hour, right?"},{"tagalog":"tama po ba","english":"is that right?","example":"Una po, ibababad muna ang manok sa toyo, suka at bawang nang mga isang oras, tama po ba?","exampleTranslation":"First, you marinate the chicken in soy sauce, vinegar and garlic for about an hour, right?"},{"tagalog":"Ah, kaya pala","english":"oh, so that''s why","example":"Ah, kaya pala hindi muna hinahalo pagkabuhos ng suka, para hindi lumabas na hilaw ang lasa.","exampleTranslation":"Oh, so that''s why you don''t stir right after pouring in the vinegar, so it doesn''t taste raw."},{"tagalog":"hindi muna hinahalo pagkabuhos ng suka","english":"you don''t stir yet once the vinegar is in","example":"Ah, kaya pala hindi muna hinahalo pagkabuhos ng suka, para hindi lumabas na hilaw ang lasa.","exampleTranslation":"Oh, so that''s why you don''t stir right after pouring in the vinegar, so it doesn''t taste raw."},{"tagalog":"para hindi lumabas na hilaw ang lasa","english":"so the taste doesn''t come out raw","example":"Ah, kaya pala hindi muna hinahalo pagkabuhos ng suka, para hindi lumabas na hilaw ang lasa.","exampleTranslation":"Oh, so that''s why you don''t stir right after pouring in the vinegar, so it doesn''t taste raw."}]}'::jsonb, '73b62480fc07d61b2d5efdfa8bae9cb8892af1ede9efb367a8e1b150e428693e', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
