(
    '43030000-0000-4000-8100-000000000006'::uuid,
    'advanced-06-teleserye-talk-and-a-videoke-night', 'Teleserye talk and a videoke night', 'Gush over last night''s teleserye finale, then plan a videoke night.',
    'advanced', 5, 6, false, 1,
    'advanced-v1', 'sound-like-a-local', 'Sound like a local',
    2, 6, 3, 14,
    3.30, array['culture', 'lifeInThePhilippines']::text[], 'authored_roadmap', 'native_speaker_review_required',
    '{"title":"Teleserye talk and a videoke night","scenarioKey":"roadmap_advanced_06_sound_like_a_local","scenario":"Gush over last night''s teleserye finale, then plan a videoke night.","minutes":5,"difficulty":3.3,"rounds":[{"topicKey":"roadmap_advanced_06_sound_like_a_local","situation":"At lunch, your officemate Tin sits down looking like she barely slept. The big drama ended last night.","tagalog":"Napanood mo ba ''yung finale kagabi? Grabe, hindi ko inakalang si Lorenzo pala ang tunay na ama!","translation":"Did you watch the finale last night? Wow, I never imagined Lorenzo was the real father!","chunks":[{"tagalog":"Napanood mo ba ''yung finale kagabi?","english":"did you watch the finale last night?","note":"Napanood = got to watch (completed)."},{"tagalog":"Grabe,","english":"wow, intense","note":"Grabe = ''that''s insane'': reaction word number one."},{"tagalog":"hindi ko inakalang si Lorenzo pala","english":"I never thought it would turn out to be Lorenzo","note":"Pala marks a surprise discovery: ''so it turns out''."},{"tagalog":"ang tunay na ama!","english":"who was the real father!","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Napanood","english":"got to watch (completed)"},{"token":"mo","english":"you / your (casual)"},{"token":"ba","english":"(question marker)"},{"token":"''yung","english":"the, that (short for iyong)"},{"token":"finale","english":"finale"},{"token":"kagabi?","english":"last night"},{"token":"Grabe,","english":"wow, that''s intense"},{"token":"hindi","english":"not"},{"token":"ko","english":"I / my"},{"token":"inakalang","english":"imagined that (completed + linker)"},{"token":"si","english":"(name marker)"},{"token":"Lorenzo","english":"Lorenzo"},{"token":"pala","english":"so it turns out"},{"token":"ang","english":"the (topic marker)"},{"token":"tunay","english":"real, true"},{"token":"na","english":"already / now / that (linker)"},{"token":"ama!","english":"father"}],"speakingPrompt":"Ask whether she saw the finale, and react to the big twist about the father."},{"topicKey":"roadmap_advanced_06_sound_like_a_local","situation":"Tin can''t stand the scheming villain, Veronica. You agree, but you''re also impressed.","tagalog":"Nakakainis ''yung kontrabida, pero ang galing niyang umarte, kaya siguradong mananalo siya ng award.","translation":"The villain is so annoying, but she acts so well that she''ll surely win an award.","chunks":[{"tagalog":"Nakakainis ''yung kontrabida,","english":"the villain is so infuriating","note":"Kontrabida = villain; every teleserye needs one."},{"tagalog":"pero ang galing niyang umarte,","english":"but she''s such a good actress","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"kaya siguradong mananalo siya ng award.","english":"so she''s sure to win an award","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Nakakainis","english":"annoying, infuriating"},{"token":"''yung","english":"the, that (short for iyong)"},{"token":"kontrabida,","english":"villain"},{"token":"pero","english":"but"},{"token":"ang galing","english":"so good (at)"},{"token":"niyang","english":"his, her (+ linker)"},{"token":"umarte,","english":"to act"},{"token":"kaya","english":"so, that''s why"},{"token":"siguradong","english":"sure to (+ linker)"},{"token":"mananalo","english":"will win (future)"},{"token":"siya","english":"he, she"},{"token":"ng","english":"of / a (marker)"},{"token":"award.","english":"award"}],"speakingPrompt":"Say the villain is infuriating, but praise her acting and predict an award."},{"topicKey":"roadmap_advanced_06_sound_like_a_local","situation":"Tin admits she cried at the ending. Confess that you did too.","tagalog":"Sa totoo lang, umiyak ako nang todo sa huling eksena, lalo na nung niyakap niya ang nanay niya.","translation":"Honestly, I cried my eyes out at the last scene, especially when she hugged her mother.","chunks":[{"tagalog":"Sa totoo lang,","english":"honestly","note":"Start the thought with this reusable chunk."},{"tagalog":"umiyak ako nang todo sa huling eksena,","english":"I cried hard at the final scene","note":"Nang todo = all-out (nang before a manner word)."},{"tagalog":"lalo na nung niyakap niya ang nanay niya.","english":"especially when she hugged her mum","note":"Nung is the spoken form of noong, ''when'' in the past."}],"wordGlosses":[{"token":"Sa","english":"in, at, to, on"},{"token":"totoo","english":"truth"},{"token":"lang,","english":"only, just"},{"token":"umiyak","english":"cried (completed)"},{"token":"ako","english":"I"},{"token":"nang","english":"(adverb marker) / for"},{"token":"todo","english":"all-out"},{"token":"sa","english":"in, at, to, on"},{"token":"huling","english":"last (+ linker)"},{"token":"eksena,","english":"scene"},{"token":"lalo","english":"especially"},{"token":"na","english":"already / now / that (linker)"},{"token":"nung","english":"when (spoken noong)"},{"token":"niyakap","english":"hugged (completed)"},{"token":"niya","english":"his, her / by him, her"},{"token":"ang","english":"the (topic marker)"},{"token":"nanay","english":"mother, mum"},{"token":"niya.","english":"his, her / by him, her"}],"speakingPrompt":"Admit you sobbed at the final scene, especially the hug with her mother.","responseExercise":{"promptTagalog":"Sa totoo lang, umiyak ako nang todo sa huling eksena, lalo na nung niyakap niya ang nanay niya.","promptTranslation":"Honestly, I cried my eyes out at the last scene, especially when she hugged her mother.","options":[{"englishTranslation":"Let''s do videoke on Saturday at my place! I''ll take care of the food, you guys bring drinks."},{"englishTranslation":"Honestly, I cried my eyes out at the last scene, especially when she hugged her mother."},{"englishTranslation":"But I get to sing the theme song first, then you belt out the chorus, deal?"}],"correctOptionIndex":1}},{"topicKey":"roadmap_advanced_06_sound_like_a_local","situation":"You want to celebrate the finale with the whole team. Invite them over for the weekend.","tagalog":"Videoke tayo sa Sabado sa bahay! Ako na ang bahala sa pagkain, kayo na lang sa drinks.","translation":"Let''s do videoke on Saturday at my place! I''ll take care of the food, you guys bring drinks.","chunks":[{"tagalog":"Videoke tayo sa Sabado sa bahay!","english":"let''s do videoke on Saturday at my place!","note":"Activity + tayo = ''let''s do ...''."},{"tagalog":"Ako na ang bahala sa pagkain,","english":"I''ll take care of the food","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"kayo na lang sa drinks.","english":"you all just handle the drinks","note":"Kayo here is the plural ''you all'', not the respectful form."}],"wordGlosses":[{"token":"Videoke","english":"videoke (karaoke)"},{"token":"tayo","english":"we, us (including you)"},{"token":"sa","english":"in, at, to, on"},{"token":"Sabado","english":"Saturday"},{"token":"sa","english":"in, at, to, on"},{"token":"bahay!","english":"house, home"},{"token":"Ako","english":"I"},{"token":"na","english":"already / now / that (linker)"},{"token":"ang","english":"the (topic marker)"},{"token":"bahala","english":"in charge, up to (someone)"},{"token":"sa","english":"in, at, to, on"},{"token":"pagkain,","english":"food"},{"token":"kayo","english":"you (respectful / plural)"},{"token":"na lang","english":"just, instead"},{"token":"sa","english":"in, at, to, on"},{"token":"drinks.","english":"drinks"}],"speakingPrompt":"Invite everyone to a Saturday videoke at your house and split the food and drinks."},{"topicKey":"roadmap_advanced_06_sound_like_a_local","situation":"Tin is already planning her song list. Call dibs on the drama''s theme song.","tagalog":"Basta ako ang unang kakanta ng theme song, tapos ikaw ang bibirit sa chorus, deal?","translation":"But I get to sing the theme song first, then you belt out the chorus, deal?","chunks":[{"tagalog":"Basta ako ang unang kakanta","english":"as long as I''m the first to sing","note":"Basta = ''as long as, just make sure''."},{"tagalog":"ng theme song,","english":"the theme song","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"tapos ikaw ang bibirit sa chorus, deal?","english":"then you belt out the chorus, deal?","note":"Bumirit = to belt out a high note, a videoke must."}],"wordGlosses":[{"token":"Basta","english":"as long as"},{"token":"ako","english":"I"},{"token":"ang","english":"the (topic marker)"},{"token":"unang","english":"first (+ linker)"},{"token":"kakanta","english":"will sing (future)"},{"token":"ng","english":"of / a (marker)"},{"token":"theme song,","english":"theme song"},{"token":"tapos","english":"then, after that"},{"token":"ikaw","english":"you (emphatic)"},{"token":"ang","english":"the (topic marker)"},{"token":"bibirit","english":"will belt out (future)"},{"token":"sa","english":"in, at, to, on"},{"token":"chorus,","english":"chorus"},{"token":"deal?","english":"deal"}],"speakingPrompt":"Claim the first turn on the theme song and give her the big chorus.","responseExercise":{"promptTagalog":"Basta ako ang unang kakanta ng theme song, tapos ikaw ang bibirit sa chorus, deal?","promptTranslation":"But I get to sing the theme song first, then you belt out the chorus, deal?","options":[{"englishTranslation":"Did you watch the finale last night? Wow, I never imagined Lorenzo was the real father!"},{"englishTranslation":"But I get to sing the theme song first, then you belt out the chorus, deal?"},{"englishTranslation":"The villain is so annoying, but she acts so well that she''ll surely win an award."}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Napanood mo ba ''yung finale kagabi","english":"did you watch the finale last night?","example":"Napanood mo ba ''yung finale kagabi? Grabe, hindi ko inakalang si Lorenzo pala ang tunay na ama!","exampleTranslation":"Did you watch the finale last night? Wow, I never imagined Lorenzo was the real father!"},{"tagalog":"Grabe","english":"wow, intense","example":"Napanood mo ba ''yung finale kagabi? Grabe, hindi ko inakalang si Lorenzo pala ang tunay na ama!","exampleTranslation":"Did you watch the finale last night? Wow, I never imagined Lorenzo was the real father!"},{"tagalog":"hindi ko inakalang si Lorenzo pala","english":"I never thought it would turn out to be Lorenzo","example":"Napanood mo ba ''yung finale kagabi? Grabe, hindi ko inakalang si Lorenzo pala ang tunay na ama!","exampleTranslation":"Did you watch the finale last night? Wow, I never imagined Lorenzo was the real father!"},{"tagalog":"ang tunay na ama","english":"who was the real father!","example":"Napanood mo ba ''yung finale kagabi? Grabe, hindi ko inakalang si Lorenzo pala ang tunay na ama!","exampleTranslation":"Did you watch the finale last night? Wow, I never imagined Lorenzo was the real father!"},{"tagalog":"Nakakainis ''yung kontrabida","english":"the villain is so infuriating","example":"Nakakainis ''yung kontrabida, pero ang galing niyang umarte, kaya siguradong mananalo siya ng award.","exampleTranslation":"The villain is so annoying, but she acts so well that she''ll surely win an award."},{"tagalog":"pero ang galing niyang umarte","english":"but she''s such a good actress","example":"Nakakainis ''yung kontrabida, pero ang galing niyang umarte, kaya siguradong mananalo siya ng award.","exampleTranslation":"The villain is so annoying, but she acts so well that she''ll surely win an award."},{"tagalog":"kaya siguradong mananalo siya ng award","english":"so she''s sure to win an award","example":"Nakakainis ''yung kontrabida, pero ang galing niyang umarte, kaya siguradong mananalo siya ng award.","exampleTranslation":"The villain is so annoying, but she acts so well that she''ll surely win an award."},{"tagalog":"Sa totoo lang","english":"honestly","example":"Sa totoo lang, umiyak ako nang todo sa huling eksena, lalo na nung niyakap niya ang nanay niya.","exampleTranslation":"Honestly, I cried my eyes out at the last scene, especially when she hugged her mother."},{"tagalog":"umiyak ako nang todo sa huling eksena","english":"I cried hard at the final scene","example":"Sa totoo lang, umiyak ako nang todo sa huling eksena, lalo na nung niyakap niya ang nanay niya.","exampleTranslation":"Honestly, I cried my eyes out at the last scene, especially when she hugged her mother."},{"tagalog":"lalo na nung niyakap niya ang nanay niya","english":"especially when she hugged her mum","example":"Sa totoo lang, umiyak ako nang todo sa huling eksena, lalo na nung niyakap niya ang nanay niya.","exampleTranslation":"Honestly, I cried my eyes out at the last scene, especially when she hugged her mother."}]}'::jsonb, '1f7dc7352cc5768096e728c55714a153b3ee51d6b0578ab182f41e9239361c6c', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
  ),
(
    '43030000-0000-4000-8100-000000000007'::uuid,
    'advanced-07-run-a-meeting-in-office-taglish', 'Run a meeting in office Taglish', 'Lead a team meeting in office Taglish and push back on a deadline.',
    'advanced', 5, 7, false, 1,
    'advanced-v1', 'sound-like-a-local', 'Sound like a local',
    2, 7, 3, 14,
    3.35, array['work']::text[], 'authored_roadmap', 'native_speaker_review_required',
    '{"title":"Run a meeting in office Taglish","scenarioKey":"roadmap_advanced_07_sound_like_a_local","scenario":"Lead a team meeting in office Taglish and push back on a deadline.","minutes":5,"difficulty":3.35,"rounds":[{"topicKey":"roadmap_advanced_07_sound_like_a_local","situation":"It''s Monday at your Ortigas office. You''re leading the weekly meeting, and everyone is settling in.","tagalog":"Good morning, team! Simulan na natin para matapos tayo on time. Una sa agenda, ''yung client launch.","translation":"Good morning, team! Let''s get started so we finish on time. First on the agenda, the client launch.","chunks":[{"tagalog":"Good morning, team!","english":"good morning, team!","note":"Manila office meetings often open fully in English."},{"tagalog":"Simulan na natin","english":"let''s start now","note":"Simulan na natin = ''let''s begin'' (natin includes everyone)."},{"tagalog":"para matapos tayo on time.","english":"so we finish on time","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"Una sa agenda, ''yung client launch.","english":"first on the agenda, the client launch","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Good morning,","english":"good morning"},{"token":"team!","english":"team"},{"token":"Simulan","english":"start, begin"},{"token":"na","english":"already / now / that (linker)"},{"token":"natin","english":"our / let''s (including you)"},{"token":"para","english":"for / so that"},{"token":"matapos","english":"to finish"},{"token":"tayo","english":"we, us (including you)"},{"token":"on time.","english":"on time"},{"token":"Una","english":"first"},{"token":"sa","english":"in, at, to, on"},{"token":"agenda,","english":"agenda"},{"token":"''yung","english":"the, that (short for iyong)"},{"token":"client","english":"client"},{"token":"launch.","english":"launch"}],"speakingPrompt":"Open the meeting, keep it moving, and announce the first item."},{"topicKey":"roadmap_advanced_07_sound_like_a_local","situation":"Jessa, your designer, has the latest mock-ups open on her laptop. Ask her for an update.","tagalog":"Jessa, puwede mo bang i-share ''yung update sa design? Nasaan na tayo sa timeline?","translation":"Jessa, could you share the design update? Where are we on the timeline?","chunks":[{"tagalog":"Jessa, puwede mo bang i-share","english":"Jessa, could you share","note":"I- + English verb is the standard Taglish pattern: i-share, i-check, i-move."},{"tagalog":"''yung update sa design?","english":"the update on the design?","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"Nasaan na tayo sa timeline?","english":"where are we on the timeline?","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Jessa,","english":"Jessa"},{"token":"puwede","english":"can, could"},{"token":"mo","english":"you / your (casual)"},{"token":"bang","english":"(question marker) + linker"},{"token":"i-share","english":"share"},{"token":"''yung","english":"the, that (short for iyong)"},{"token":"update","english":"update"},{"token":"sa","english":"in, at, to, on"},{"token":"design?","english":"design"},{"token":"Nasaan","english":"where (is it)"},{"token":"na","english":"already / now / that (linker)"},{"token":"tayo","english":"we, us (including you)"},{"token":"sa","english":"in, at, to, on"},{"token":"timeline?","english":"timeline"}],"speakingPrompt":"Ask Jessa to share her update and where the project stands on the timeline."},{"topicKey":"roadmap_advanced_07_sound_like_a_local","situation":"Your manager joins the call and says the client wants everything by Friday. Push back respectfully.","tagalog":"Sir, with all due respect, medyo kulang po ang isang linggo para ma-test namin nang maayos.","translation":"Sir, with all due respect, one week is a bit short for us to test it properly.","chunks":[{"tagalog":"Sir, with all due respect,","english":"sir, with all due respect","note":"Bosses are Sir or Ma''am; careful pushback often starts in English."},{"tagalog":"medyo kulang po ang isang linggo","english":"one week is a bit short","note":"Medyo (''somewhat'') softens the bad news."},{"tagalog":"para ma-test namin nang maayos.","english":"for us to test it properly","note":"Namin excludes the boss: ''we, the team''."}],"wordGlosses":[{"token":"Sir,","english":"sir"},{"token":"with","english":"with"},{"token":"all","english":"all"},{"token":"due","english":"due"},{"token":"respect,","english":"respect"},{"token":"medyo","english":"a bit, somewhat"},{"token":"kulang","english":"not enough, short"},{"token":"po","english":"(respect marker)"},{"token":"ang","english":"the (topic marker)"},{"token":"isang","english":"one, a"},{"token":"linggo","english":"week"},{"token":"para","english":"for / so that"},{"token":"ma-test","english":"to be able to test"},{"token":"namin","english":"by us / our (not including you)"},{"token":"nang maayos.","english":"properly"}],"speakingPrompt":"Tell your manager, respectfully, that a week isn''t enough to test properly.","responseExercise":{"promptTagalog":"Sir, with all due respect, medyo kulang po ang isang linggo para ma-test namin nang maayos.","promptTranslation":"Sir, with all due respect, one week is a bit short for us to test it properly.","options":[{"englishTranslation":"If it''s all right with you, could we move it to the end of the month?"},{"englishTranslation":"Sir, with all due respect, one week is a bit short for us to test it properly."},{"englishTranslation":"Okay, so our action items are that I''ll talk to the client and Jessa will update the timeline."}],"correctOptionIndex":1}},{"topicKey":"roadmap_advanced_07_sound_like_a_local","situation":"Your manager asks what you suggest instead. Offer a realistic new date.","tagalog":"Kung okay lang po sa inyo, puwede po bang i-move natin sa katapusan ng buwan?","translation":"If it''s all right with you, could we move it to the end of the month?","chunks":[{"tagalog":"Kung okay lang po sa inyo,","english":"if it''s all right with you","note":"Start the thought with this reusable chunk."},{"tagalog":"puwede po bang i-move natin","english":"could we move it","note":"Puwede po bang ...? is the polite request frame for a superior."},{"tagalog":"sa katapusan ng buwan?","english":"to the end of the month?","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Kung","english":"if / how / where"},{"token":"okay","english":"okay, all right"},{"token":"lang","english":"only, just"},{"token":"po","english":"(respect marker)"},{"token":"sa","english":"in, at, to, on"},{"token":"inyo,","english":"you (respectful / plural)"},{"token":"puwede","english":"can, could"},{"token":"po","english":"(respect marker)"},{"token":"bang","english":"(question marker) + linker"},{"token":"i-move","english":"move (reschedule)"},{"token":"natin","english":"our / let''s (including you)"},{"token":"sa","english":"in, at, to, on"},{"token":"katapusan","english":"end"},{"token":"ng","english":"of / a (marker)"},{"token":"buwan?","english":"month"}],"speakingPrompt":"Politely propose moving the deadline to the end of the month."},{"topicKey":"roadmap_advanced_07_sound_like_a_local","situation":"Your manager agrees. Wrap up the meeting by assigning who does what.","tagalog":"Sige, so ang action items natin, ako ang kakausap sa client, at si Jessa ang mag-a-update ng timeline.","translation":"Okay, so our action items are that I''ll talk to the client and Jessa will update the timeline.","chunks":[{"tagalog":"Sige, so ang action items natin,","english":"okay, so our action items","note":"Start the thought with this reusable chunk."},{"tagalog":"ako ang kakausap sa client,","english":"I''m the one who''ll talk to the client","note":"Kakausap = will talk to (future); ''ako ang ...'' = ''I''m the one who ...''."},{"tagalog":"at si Jessa ang mag-a-update ng timeline.","english":"and Jessa will update the timeline","note":"Mag-a-update: the first sound of the English verb repeats to mark the future."}],"wordGlosses":[{"token":"Sige,","english":"okay, sure"},{"token":"so","english":"so"},{"token":"ang","english":"the (topic marker)"},{"token":"action items","english":"action items"},{"token":"natin,","english":"our / let''s (including you)"},{"token":"ako","english":"I"},{"token":"ang","english":"the (topic marker)"},{"token":"kakausap","english":"will talk to (future)"},{"token":"sa","english":"in, at, to, on"},{"token":"client,","english":"client"},{"token":"at","english":"and"},{"token":"si","english":"(name marker)"},{"token":"Jessa","english":"Jessa"},{"token":"ang","english":"the (topic marker)"},{"token":"mag-a-update","english":"will update (future)"},{"token":"ng","english":"of / a (marker)"},{"token":"timeline.","english":"timeline"}],"speakingPrompt":"Sum up the action items: you''ll handle the client, Jessa will update the timeline.","responseExercise":{"promptTagalog":"Sige, so ang action items natin, ako ang kakausap sa client, at si Jessa ang mag-a-update ng timeline.","promptTranslation":"Okay, so our action items are that I''ll talk to the client and Jessa will update the timeline.","options":[{"englishTranslation":"Good morning, team! Let''s get started so we finish on time. First on the agenda, the client launch."},{"englishTranslation":"Okay, so our action items are that I''ll talk to the client and Jessa will update the timeline."},{"englishTranslation":"Jessa, could you share the design update? Where are we on the timeline?"}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Good morning, team","english":"good morning, team!","example":"Good morning, team! Simulan na natin para matapos tayo on time. Una sa agenda, ''yung client launch.","exampleTranslation":"Good morning, team! Let''s get started so we finish on time. First on the agenda, the client launch."},{"tagalog":"Simulan na natin","english":"let''s start now","example":"Good morning, team! Simulan na natin para matapos tayo on time. Una sa agenda, ''yung client launch.","exampleTranslation":"Good morning, team! Let''s get started so we finish on time. First on the agenda, the client launch."},{"tagalog":"para matapos tayo on time","english":"so we finish on time","example":"Good morning, team! Simulan na natin para matapos tayo on time. Una sa agenda, ''yung client launch.","exampleTranslation":"Good morning, team! Let''s get started so we finish on time. First on the agenda, the client launch."},{"tagalog":"Una sa agenda, ''yung client launch","english":"first on the agenda, the client launch","example":"Good morning, team! Simulan na natin para matapos tayo on time. Una sa agenda, ''yung client launch.","exampleTranslation":"Good morning, team! Let''s get started so we finish on time. First on the agenda, the client launch."},{"tagalog":"Jessa, puwede mo bang i-share","english":"Jessa, could you share","example":"Jessa, puwede mo bang i-share ''yung update sa design? Nasaan na tayo sa timeline?","exampleTranslation":"Jessa, could you share the design update? Where are we on the timeline?"},{"tagalog":"''yung update sa design","english":"the update on the design?","example":"Jessa, puwede mo bang i-share ''yung update sa design? Nasaan na tayo sa timeline?","exampleTranslation":"Jessa, could you share the design update? Where are we on the timeline?"},{"tagalog":"Nasaan na tayo sa timeline","english":"where are we on the timeline?","example":"Jessa, puwede mo bang i-share ''yung update sa design? Nasaan na tayo sa timeline?","exampleTranslation":"Jessa, could you share the design update? Where are we on the timeline?"},{"tagalog":"Sir, with all due respect","english":"sir, with all due respect","example":"Sir, with all due respect, medyo kulang po ang isang linggo para ma-test namin nang maayos.","exampleTranslation":"Sir, with all due respect, one week is a bit short for us to test it properly."},{"tagalog":"medyo kulang po ang isang linggo","english":"one week is a bit short","example":"Sir, with all due respect, medyo kulang po ang isang linggo para ma-test namin nang maayos.","exampleTranslation":"Sir, with all due respect, one week is a bit short for us to test it properly."},{"tagalog":"para ma-test namin nang maayos","english":"for us to test it properly","example":"Sir, with all due respect, medyo kulang po ang isang linggo para ma-test namin nang maayos.","exampleTranslation":"Sir, with all due respect, one week is a bit short for us to test it properly."}]}'::jsonb, '97547af05cbaf76579f887279a1e0c7ea448d1a7b1cb7da1c85f2508bab6c2bc', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
