(
    '43030000-0000-4000-8100-000000000008'::uuid,
    'advanced-08-forgot-the-monthsary', 'Forgot the monthsary', 'You forgot your monthsary. Apologise properly and make it up to them.',
    'advanced', 5, 8, false, 1,
    'advanced-v1', 'lifes-big-moments', 'Life''s big moments',
    3, 8, 3, 14,
    3.40, array['partner']::text[], 'authored_roadmap', 'native_speaker_review_required',
    '{"title":"Forgot the monthsary","scenarioKey":"roadmap_advanced_08_lifes_big_moments","scenario":"You forgot your monthsary. Apologise properly and make it up to them.","minutes":5,"difficulty":3.4,"rounds":[{"topicKey":"roadmap_advanced_08_lifes_big_moments","situation":"Your partner has been quiet all morning. Then you check the date and realise what you forgot.","tagalog":"Babe, sorry talaga, hindi ko sinasadyang makalimutan ''yung monthsary natin kahapon.","translation":"Babe, I''m really sorry, I didn''t mean to forget our monthsary yesterday.","chunks":[{"tagalog":"Babe, sorry talaga,","english":"babe, I''m really sorry","note":"Talaga makes the apology sincere: ''truly''."},{"tagalog":"hindi ko sinasadyang makalimutan","english":"I didn''t mean to forget","note":"Sinasadya = done on purpose; hindi ko sinasadya = I didn''t mean it."},{"tagalog":"''yung monthsary natin kahapon.","english":"our monthsary yesterday","note":"Many Filipino couples mark every month together, not just the yearly anniversary."}],"wordGlosses":[{"token":"Babe,","english":"babe"},{"token":"sorry","english":"sorry"},{"token":"talaga,","english":"really, truly"},{"token":"hindi","english":"not"},{"token":"ko","english":"I / my"},{"token":"sinasadyang","english":"doing on purpose (+ linker)"},{"token":"makalimutan","english":"to forget (by accident)"},{"token":"''yung","english":"the, that (short for iyong)"},{"token":"monthsary","english":"monthly anniversary"},{"token":"natin","english":"our / let''s (including you)"},{"token":"kahapon.","english":"yesterday"}],"speakingPrompt":"Apologise sincerely for forgetting your monthsary, and say it wasn''t on purpose."},{"topicKey":"roadmap_advanced_08_lifes_big_moments","situation":"Your partner crosses their arms and looks away. Don''t make excuses; show you understand.","tagalog":"Wala akong maidadahilan, alam kong nasaktan kita, at naiintindihan ko kung bakit ka nagtatampo.","translation":"I have no excuse; I know I hurt you, and I understand why you''re upset with me.","chunks":[{"tagalog":"Wala akong maidadahilan,","english":"I have no excuse","note":"Literally ''I have nothing I can give as an excuse''."},{"tagalog":"alam kong nasaktan kita,","english":"I know I hurt you","note":"Kita = ''I ... you'' in one word."},{"tagalog":"at naiintindihan ko kung bakit ka nagtatampo.","english":"and I understand why you''re sulking","note":"Tampo is a hurt, quiet withdrawal that waits to be coaxed away."}],"wordGlosses":[{"token":"Wala","english":"there''s no / nothing"},{"token":"akong","english":"I (+ linker)"},{"token":"maidadahilan,","english":"can give as an excuse"},{"token":"alam","english":"know / known"},{"token":"kong","english":"my / I (+ linker)"},{"token":"nasaktan","english":"hurt (completed)"},{"token":"kita,","english":"I ... you"},{"token":"at","english":"and"},{"token":"naiintindihan","english":"understand (ongoing)"},{"token":"ko","english":"I / my"},{"token":"kung","english":"if / how / where"},{"token":"bakit","english":"why"},{"token":"ka","english":"you (casual)"},{"token":"nagtatampo.","english":"sulking (ongoing)"}],"speakingPrompt":"Admit you have no excuse, that you hurt them, and that their sulking makes sense."},{"topicKey":"roadmap_advanced_08_lifes_big_moments","situation":"They glance back at you. Now offer a real plan to make up for it tonight.","tagalog":"Para bumawi, ipagluluto kita ng paborito mong sinigang, tapos manood tayo ng sine mamayang gabi.","translation":"To make it up to you, I''ll cook your favourite sinigang, and then let''s catch a movie tonight.","chunks":[{"tagalog":"Para bumawi,","english":"to make it up","note":"Bumawi = to make up for something."},{"tagalog":"ipagluluto kita ng paborito mong sinigang,","english":"I''ll cook you your favourite sinigang","note":"Ipagluluto = will cook for someone (future, benefactive)."},{"tagalog":"tapos manood tayo ng sine mamayang gabi.","english":"then let''s watch a movie tonight","note":"Use this ending to complete the spoken thought naturally."}],"wordGlosses":[{"token":"Para","english":"for / so that"},{"token":"bumawi,","english":"to make up for it"},{"token":"ipagluluto","english":"will cook for (future)"},{"token":"kita","english":"I ... you"},{"token":"ng","english":"of / a (marker)"},{"token":"paborito","english":"favourite"},{"token":"mong","english":"you / your (+ linker)"},{"token":"sinigang,","english":"sinigang (sour soup)"},{"token":"tapos","english":"then, after that"},{"token":"manood","english":"watch"},{"token":"tayo","english":"we, us (including you)"},{"token":"ng","english":"of / a (marker)"},{"token":"sine","english":"movie, cinema"},{"token":"mamayang","english":"later (+ linker), tonight"},{"token":"gabi.","english":"evening, night"}],"speakingPrompt":"Offer to cook their favourite dish and take them to a movie tonight.","responseExercise":{"promptTagalog":"Para bumawi, ipagluluto kita ng paborito mong sinigang, tapos manood tayo ng sine mamayang gabi.","promptTranslation":"To make it up to you, I''ll cook your favourite sinigang, and then let''s catch a movie tonight.","options":[{"englishTranslation":"Don''t sulk anymore, please? Let''s make up, okay? I miss you so much."},{"englishTranslation":"To make it up to you, I''ll cook your favourite sinigang, and then let''s catch a movie tonight."},{"englishTranslation":"I promise I''ll put every one of our monthsaries in my calendar so it never happens again."}],"correctOptionIndex":1}},{"topicKey":"roadmap_advanced_08_lifes_big_moments","situation":"A small smile is fighting its way onto their face. Coax them out of the sulk.","tagalog":"Huwag ka nang magtampo, please? Bati na tayo, ha? Miss na miss na kita.","translation":"Don''t sulk anymore, please? Let''s make up, okay? I miss you so much.","chunks":[{"tagalog":"Huwag ka nang magtampo, please?","english":"don''t sulk anymore, please?","note":"Here nang is na + linker: ''not anymore''."},{"tagalog":"Bati na tayo, ha?","english":"let''s make up, okay?","note":"Bati = on good terms again; ''bati na tayo'' is the classic make-up line."},{"tagalog":"Miss na miss na kita.","english":"I miss you so much","note":"Repeating the word with na intensifies it."}],"wordGlosses":[{"token":"Huwag","english":"don''t"},{"token":"ka","english":"you (casual)"},{"token":"nang","english":"(adverb marker) / for"},{"token":"magtampo,","english":"sulk"},{"token":"please?","english":"please"},{"token":"Bati","english":"on good terms, made up"},{"token":"na","english":"already / now / that (linker)"},{"token":"tayo,","english":"we, us (including you)"},{"token":"ha?","english":"okay? (seeking agreement)"},{"token":"Miss","english":"miss"},{"token":"na","english":"already / now / that (linker)"},{"token":"miss","english":"miss"},{"token":"na","english":"already / now / that (linker)"},{"token":"kita.","english":"I ... you"}],"speakingPrompt":"Sweetly ask them to stop sulking, suggest you make up, and say you miss them."},{"topicKey":"roadmap_advanced_08_lifes_big_moments","situation":"They finally laugh and hug you. Make a promise so it never happens again.","tagalog":"Promise, ilalagay ko na sa calendar ko ang bawat monthsary natin, para hindi na mauulit.","translation":"I promise I''ll put every one of our monthsaries in my calendar so it never happens again.","chunks":[{"tagalog":"Promise,","english":"I promise","note":"Start the thought with this reusable chunk."},{"tagalog":"ilalagay ko na sa calendar ko","english":"I''ll put it in my calendar","note":"Ilalagay = will put (future, object focus)."},{"tagalog":"ang bawat monthsary natin,","english":"every monthsary of ours","note":"Keep this chunk together in the middle of the sentence."},{"tagalog":"para hindi na mauulit.","english":"so it won''t happen again","note":"Hindi na mauulit is the standard ''it won''t happen again''."}],"wordGlosses":[{"token":"Promise,","english":"promise"},{"token":"ilalagay","english":"will put (future)"},{"token":"ko","english":"I / my"},{"token":"na","english":"already / now / that (linker)"},{"token":"sa","english":"in, at, to, on"},{"token":"calendar","english":"calendar"},{"token":"ko","english":"I / my"},{"token":"ang","english":"the (topic marker)"},{"token":"bawat","english":"each, every"},{"token":"monthsary","english":"monthly anniversary"},{"token":"natin,","english":"our / let''s (including you)"},{"token":"para","english":"for / so that"},{"token":"hindi","english":"not"},{"token":"na","english":"already / now / that (linker)"},{"token":"mauulit.","english":"will happen again (future)"}],"speakingPrompt":"Promise to put every monthsary in your calendar so you never forget again.","responseExercise":{"promptTagalog":"Promise, ilalagay ko na sa calendar ko ang bawat monthsary natin, para hindi na mauulit.","promptTranslation":"I promise I''ll put every one of our monthsaries in my calendar so it never happens again.","options":[{"englishTranslation":"Babe, I''m really sorry, I didn''t mean to forget our monthsary yesterday."},{"englishTranslation":"I promise I''ll put every one of our monthsaries in my calendar so it never happens again."},{"englishTranslation":"I have no excuse; I know I hurt you, and I understand why you''re upset with me."}],"correctOptionIndex":1}}],"vocabulary":[{"tagalog":"Babe, sorry talaga","english":"babe, I''m really sorry","example":"Babe, sorry talaga, hindi ko sinasadyang makalimutan ''yung monthsary natin kahapon.","exampleTranslation":"Babe, I''m really sorry, I didn''t mean to forget our monthsary yesterday."},{"tagalog":"hindi ko sinasadyang makalimutan","english":"I didn''t mean to forget","example":"Babe, sorry talaga, hindi ko sinasadyang makalimutan ''yung monthsary natin kahapon.","exampleTranslation":"Babe, I''m really sorry, I didn''t mean to forget our monthsary yesterday."},{"tagalog":"''yung monthsary natin kahapon","english":"our monthsary yesterday","example":"Babe, sorry talaga, hindi ko sinasadyang makalimutan ''yung monthsary natin kahapon.","exampleTranslation":"Babe, I''m really sorry, I didn''t mean to forget our monthsary yesterday."},{"tagalog":"Wala akong maidadahilan","english":"I have no excuse","example":"Wala akong maidadahilan, alam kong nasaktan kita, at naiintindihan ko kung bakit ka nagtatampo.","exampleTranslation":"I have no excuse; I know I hurt you, and I understand why you''re upset with me."},{"tagalog":"alam kong nasaktan kita","english":"I know I hurt you","example":"Wala akong maidadahilan, alam kong nasaktan kita, at naiintindihan ko kung bakit ka nagtatampo.","exampleTranslation":"I have no excuse; I know I hurt you, and I understand why you''re upset with me."},{"tagalog":"at naiintindihan ko kung bakit ka nagtatampo","english":"and I understand why you''re sulking","example":"Wala akong maidadahilan, alam kong nasaktan kita, at naiintindihan ko kung bakit ka nagtatampo.","exampleTranslation":"I have no excuse; I know I hurt you, and I understand why you''re upset with me."},{"tagalog":"Para bumawi","english":"to make it up","example":"Para bumawi, ipagluluto kita ng paborito mong sinigang, tapos manood tayo ng sine mamayang gabi.","exampleTranslation":"To make it up to you, I''ll cook your favourite sinigang, and then let''s catch a movie tonight."},{"tagalog":"ipagluluto kita ng paborito mong sinigang","english":"I''ll cook you your favourite sinigang","example":"Para bumawi, ipagluluto kita ng paborito mong sinigang, tapos manood tayo ng sine mamayang gabi.","exampleTranslation":"To make it up to you, I''ll cook your favourite sinigang, and then let''s catch a movie tonight."},{"tagalog":"tapos manood tayo ng sine mamayang gabi","english":"then let''s watch a movie tonight","example":"Para bumawi, ipagluluto kita ng paborito mong sinigang, tapos manood tayo ng sine mamayang gabi.","exampleTranslation":"To make it up to you, I''ll cook your favourite sinigang, and then let''s catch a movie tonight."},{"tagalog":"Huwag ka nang magtampo, please","english":"don''t sulk anymore, please?","example":"Huwag ka nang magtampo, please? Bati na tayo, ha? Miss na miss na kita.","exampleTranslation":"Don''t sulk anymore, please? Let''s make up, okay? I miss you so much."}]}'::jsonb, '1f98022a1ccab08fe48e75a42294138b40a3cb7c0559df5c7a41f5d1f34e32ff', '{"contract":"kumusta_lesson_v3","structured_output":true,"local_validation":true,"ordered_chunks":true,"vocabulary_grounded":true,"vocabulary_examples_grounded":true,"hear_respond_rounds":[2,4],"authored_curriculum":true,"native_speaker_review":false}'::jsonb
  ),
(
    '43030000-0000-4000-8100-000000000009'::uuid,
